import { HTMLElement } from "node-html-parser";
import {
  Import,
  isHTMLElement,
  TranspilationContext,
  transformAttrs,
  Transformer,
} from "../../transpile";

export const imports: Import[] = [
  {
    name: "WmLogin",
    from: "@wavemaker-ai/react-runtime/components/advanced/login",
  },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    // Find the wm-form child element and add app-login-form class
    const formElement = element.childNodes.find(
      child => isHTMLElement(child) && child.tagName === "WM-FORM"
    ) as HTMLElement;

    if (formElement) {
      const existingClass = formElement.getAttribute("class") || "";
      const newClass = existingClass ? `${existingClass} app-login-form` : "app-login-form";
      formElement.setAttribute("class", newClass);
    }

    return `<WmLogin listener={fragment} eventSource={fragment?.Actions.loginAction} ${transformAttrs(element, context)} >`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "</WmLogin>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
