import { HTMLElement } from "node-html-parser";
import { Import, TranspilationContext, transformAttrs, Transformer } from "../../../transpile";
import { convertActionToClickHandler, findNearestElement } from "./utils";

export const imports: Import[] = [
  {
    name: "WmTableRowAction",
    from: "@wavemaker-ai/react-runtime/components/data/table/table-row-action",
  },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const displayName = element.getAttribute("display-name");
    const actionAttr = element.getAttribute("action");
    const widgetType = element.getAttribute("widget-type") || "button";
    element.removeAttribute("widget-type");

    let onClickExpr = "";
    if (actionAttr) {
      const liveTableName = findNearestElement(element, "wm-livetable");
      const tableName = findNearestElement(element, "wm-table");
      onClickExpr = convertActionToClickHandler(actionAttr, tableName, liveTableName);
    }

    element.removeAttribute("display-name");
    if (displayName) {
      element.setAttribute("displayName", displayName);
    }
    element.removeAttribute("action");

    return `<WmTableRowAction listener={fragment} widgettype="${widgetType}" ${onClickExpr} ${transformAttrs(element, context)}`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "/>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
