import { HTMLElement } from "node-html-parser";

import { Import, transformAttrs, Transformer, TranspilationContext } from "../../transpile";

export const imports: Import[] = [
  {
    name: "WmLabel",
    from: "@wavemaker-ai/react-runtime/components/basic/label",
  },
];

const TEXT_TAGS = ["h1", "h2", "h3", "h4", "h5", "h6", "p"];

// Angular label.build.ts: notag -> <label>, else the `type` attr, else the first heading/p class, else <p>.
const resolveTag = (element: HTMLElement): string => {
  const notag = element.getAttribute("notag");
  if (notag !== undefined && notag !== "false") return "label";
  const type = element.getAttribute("type");
  if (type) return type;
  const classes = (element.getAttribute("class") || "").split(" ");
  return classes.find(c => TEXT_TAGS.includes(c)) || "p";
};

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    if (!element.getAttribute("type")?.startsWith("bind:"))
      element.setAttribute("type", resolveTag(element));
    return `<WmLabel listener={fragment} ${transformAttrs(element, context)} >`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "</WmLabel>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
