import { HTMLElement, NodeType } from "node-html-parser";
import { KeyAttributes } from "node-html-parser/dist/nodes/html";

import {
  Import,
  isHTMLElement,
  transformAttrs,
  Transformer,
  TranspilationContext,
} from "../../transpile";

export const imports: Import[] = [
  { name: "WmDialog", from: "@wavemaker-ai/react-runtime/components/dialogs/dialog" },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const widgetName = element.getAttribute("name");
    // Only synthesize a wm-dialogbody wrapper when the author hasn't already provided an
    // explicit content wrapper. wm-dialogcontent (mapped to WmDialogBody) and wm-dialogbody
    // are handled by their own transformers; wrapping them again would nest the explicit
    // wrapper inside the synthetic body and drop its content.
    const hasExplicitBody = element.childNodes.some(
      e =>
        isHTMLElement(e) &&
        ["wm-dialogcontent", "wm-dialogbody"].includes(e.tagName.toLowerCase()) &&
        e.childNodes.some(isHTMLElement)
    );
    if (!hasExplicitBody) {
      const markerIndex = element.childNodes.findIndex(
        e =>
          isHTMLElement(e) &&
          ["wm-dialogcontent", "wm-dialogbody"].includes(e.tagName.toLowerCase())
      );
      const marker = markerIndex >= 0 ? (element.childNodes[markerIndex] as HTMLElement) : null;
      const remainingChildren =
        markerIndex >= 0
          ? element.childNodes.filter((_, i) => i !== markerIndex)
          : element.childNodes;

      const content = new HTMLElement(
        "wm-dialogbody",
        {} as KeyAttributes,
        null as any,
        element,
        [0, 41]
      );
      content.nodeType = NodeType.ELEMENT_NODE;
      if (marker) {
        content.setAttributes(marker.attributes);
      }
      const actionsIndex = remainingChildren.findIndex(
        e => isHTMLElement(e) && e.tagName.toLowerCase() === "wm-dialogactions"
      );
      content.childNodes = remainingChildren;
      element.childNodes = [content];
      if (actionsIndex >= 0) {
        const actions = content.childNodes.splice(actionsIndex, 1);
        actions && element.childNodes.push(actions[0]);
      }
    }
    return `<WmDialog listener={fragment} ${transformAttrs(element, context)}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "</WmDialog>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
