import { HTMLElement, NodeType } from "node-html-parser";
import {
  Import,
  isHTMLElement,
  TranspilationContext,
  transformAttrs,
  Transformer,
} from "../../../transpile";

export const imports: Import[] = [
  { name: "WmTableColumn", from: "@wavemaker-ai/react-runtime/components/data/table/table-column" },
];
import transformEx from "../../../bind.ex.transformer";
import { transformRepeatChildAttr } from "../../utils";
import { addOptionalChaining } from "../../../../utils.browser";
import {
  getFormatCellExpression,
  parseVariableDataSetBinding,
  transformTableColumnClassExpression,
} from "./utils";

function transformColAttr(element: HTMLElement) {
  Object.keys(element.attributes).forEach(key => {
    const value = element.getAttribute(key);
    if (value?.includes("getProperty") && value.startsWith("bind:")) {
      element.setAttribute(key, value.replace("bind:", ""));
    }
  });

  return element;
}

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const editWidgetType =
      element.getAttribute("edit-widget-type") || element.getAttribute("type") || "text";
    const widgetType = element.getAttribute("widget-type") || "label";
    const staticColClass = element.getAttribute("col-class") || "";
    const colNgClass = element.getAttribute("col-ng-class") || "";
    const rowOperations = element.getAttribute("binding") === "rowOperations";

    const filterDataset = element.getAttribute("filterdataset");
    if (filterDataset) {
      const binding = parseVariableDataSetBinding(filterDataset);
      if (binding?.variableName) {
        element.setAttribute(
          "bindfilterdataset",
          `${binding.scopePath}.${binding.variableName}.dataSet`
        );
      }
    }

    ["edit-widget-type", "widget-type", "col-class", "col-ng-class"].forEach(attr =>
      element.removeAttribute(attr)
    );
    // Remove non-wm elements nodes
    Array.from(element.childNodes).forEach((child: any) => {
      if (isHTMLElement(child)) {
        const tag = child.tagName?.toLowerCase();
        if (!tag?.startsWith("wm-")) {
          element.removeChild(child);
        }
      }
    });

    // Build colClass prop from dynamic expression only
    // Static class will be set as class attribute on the element
    let colClassAttr = "";
    if (colNgClass) {
      const transformed = transformEx(colNgClass, "fragment", "attr");

      // If transformed is a single-key object like {'grey': condition}, convert to ternary string
      const singleKeyRegex = /^\{\s*'([^']+)'\s*:\s*(.+)\s*\}$/;
      const match = typeof transformed === "string" ? transformed.match(singleKeyRegex) : null;

      if (match) {
        const classKey = match[1];
        const condition = match[2];
        const transformedCondition = transformTableColumnClassExpression(condition || "");

        // Only conditional class - output as string attribute
        colClassAttr = `colClass="${transformedCondition} ? '${classKey}' : ''"`;
      } else {
        // Fallback to object/array form if multiple keys or non-standard expression
        const finalTransformed = transformTableColumnClassExpression(transformed?.toString() || "");
        colClassAttr = `colClass="${finalTransformed}"`;
      }
    }

    // Append static class to existing class attribute on the element
    const updatedElement = transformColAttr(element);
    if (staticColClass) {
      const existingClass = updatedElement.getAttribute("class") || "";
      const combinedClass = existingClass
        ? `${existingClass} ${staticColClass}`.trim()
        : staticColClass;
      updatedElement.setAttribute("class", combinedClass);
    }
    const template = element.childNodes.find(c => isHTMLElement(c)) as HTMLElement | undefined;

    // Convert formatpattern/custompipeformat into a formatted cell expression
    const formatCellExp = getFormatCellExpression(updatedElement, context);

    // Check if child content starts with {{ and convert to React expression with optional chaining
    let customExp: string | null = null;
    const textNodes = element.childNodes.filter((c: any) => c.nodeType === NodeType.TEXT_NODE);
    for (const textNode of textNodes) {
      const textContent = (textNode as any).text?.trim();
      if (textContent?.startsWith("{{") && textContent.endsWith("}}")) {
        // Extract expression between {{ and }}
        const expression = textContent.slice(2, -2).trim();
        // Transform the expression (replace fragment.row and standalone row. with rowData)
        const transformed = transformEx(expression, "fragment", "attr");
        let replacedExp = transformed?.replace(/fragment\??\.row/g, "rowData")?.toString() || "";
        // Replace standalone row. (word boundary to avoid matching "error" or "arrow")
        replacedExp = replacedExp.replace(/\brow\./g, "rowData.");
        // Apply optional chaining
        customExp = `{${addOptionalChaining(replacedExp)}}`;
        element.removeChild(textNode);
        break;
      }
    }

    if (template || customExp || formatCellExp) {
      //skipping name attribute to generate
      context.set("isInsideTableColumn", true);
      if (template) {
        transformRepeatChildAttr(template, "fragment.row", "rowData");

        const tableVarName = context.get("tableDatasetVariableName") as string | undefined;
        if (tableVarName) {
          const dataSetPath = `fragment.Variables.${tableVarName}.dataSet`;
          transformRepeatChildAttr(template, `${dataSetPath}[0]`, "rowData");
        }
      }
      const hasElementChildren = element.childNodes.some(c => isHTMLElement(c));
      const cellContent = customExp || (formatCellExp ? `{${formatCellExp}}` : "");
      return `<WmTableColumn listener={fragment} ${!rowOperations ? `editWidgetType="${editWidgetType}"` : ""}  widgetType="${widgetType}" ${colClassAttr} ${transformAttrs(updatedElement, context)} 
      renderCellContent={(rowData:any , columnData : any) =>
      (<> ${cellContent ? `${cellContent} </>)}` : ""} ${hasElementChildren ? "" : ">"}`;
    }

    return `<WmTableColumn listener={fragment} ${!rowOperations ? `editWidgetType="${editWidgetType}"` : ""}  widgetType="${widgetType}" ${colClassAttr} ${transformAttrs(updatedElement, context)}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => {
    const hasElementChildren = element.childNodes.some(c => isHTMLElement(c));
    if (hasElementChildren) {
      return " </>)}/>";
    }
    return "</WmTableColumn>";
  },
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
