import { HTMLElement } from "node-html-parser";

import { Import, transformAttrs, Transformer, TranspilationContext } from "../../transpile";

export function createSelfClosingDialogTransformer(config: {
  component: string;
  importPath: string;
}): Transformer {
  const imports: Import[] = [
    {
      name: config.component,
      from: config.importPath,
    },
  ];

  return {
    pre: (element: HTMLElement, context: TranspilationContext) =>
      `<${config.component} listener={fragment} ${transformAttrs(element, context)}`,
    post: (element: HTMLElement, context: TranspilationContext) => "/>",
    imports: (element: HTMLElement, context: TranspilationContext) => imports,
  };
}
