import { Import, Transformer, TranspilationContext, transformAttrs, parse } from "../../transpile";
import { HTMLElement, NodeType } from "node-html-parser";

const isOnlyWmParamChildren = (element: HTMLElement): boolean => {
  const elementChildren = element.childNodes.filter(
    node => node.nodeType === NodeType.ELEMENT_NODE
  ) as HTMLElement[];
  return elementChildren.length > 0 && elementChildren.every(node => node.tagName === "WM-PARAM");
};

interface LayoutRegionConfig {
  component: string[];
  importPath: string[];
  defaultContent: string;
  defaultName: string;
}

const partialContainerImport: Import[] = [
  {
    name: "WmPartialContainer",
    from: "@wavemaker-ai/react-runtime/components/page/partial-container",
  },
];

export function createLayoutRegionTransformer(config: LayoutRegionConfig): Transformer {
  const { component, importPath, defaultContent, defaultName } = config;
  const tag = component[0];

  const componentImports: Import[] = component.map((name, i) => ({ name, from: importPath[i] }));

  return {
    pre: (element: HTMLElement, context: TranspilationContext) => {
      const content = element.getAttribute("content") || defaultContent;
      const name = element.getAttribute("name") || defaultName;
      const isPreview = context.get("preview") === true;
      const hasCustomContent =
        element.childNodes.some(node => node.nodeType === NodeType.ELEMENT_NODE) &&
        !isOnlyWmParamChildren(element);

      if (hasCustomContent) {
        return `<${tag} ${transformAttrs(element, context)}>
        `;
      }

      if (isPreview) {
        return `<${tag} ${transformAttrs(element, context)}>
        <WmPartialContainer content="${content}" isLayout={true} partialName="${name}" listener={fragment} />
        `;
      }

      return `<${tag} ${transformAttrs(element, context)}>
        <${content.charAt(0).toUpperCase() + content.slice(1)} isLayout={true} partialName="${name}" />
        `;
    },
    post: () => `</${tag}>`,
    imports: (element: HTMLElement, context: TranspilationContext) => {
      const hasCustomContent =
        element.childNodes.some(node => node.nodeType === NodeType.ELEMENT_NODE) &&
        !isOnlyWmParamChildren(element);
      if (hasCustomContent) {
        return [...componentImports];
      }

      const isPreview = context.get("preview") === true;
      if (isPreview) {
        return [...componentImports, ...partialContainerImport];
      }

      const content = element.getAttribute("content") || defaultContent;
      return [
        ...componentImports,
        {
          name: content.charAt(0).toUpperCase() + content.slice(1),
          from: `@/app/components/${content}/${content}`,
        },
      ];
    },
  };
}
