/**
 * Splits a CSS shorthand list on ASCII-whitespace at top level only — not inside
 * `()`, and not inside quoted strings. Handles backslash escapes in strings.
 *
 * Covers e.g. `var(--Spacing-0, 0) 0 0 0` (comma-spacing inside `var()`).
 */
export function splitCssShorthandOnSpaces(value: string): string[] {
  const s = value.trim();
  if (!s.length) return [];

  const tokens: string[] = [];
  let parenDepth = 0;
  let quote: "'" | '"' | null = null;
  let start = 0;
  let i = 0;

  while (i < s.length) {
    const ch = s[i];

    if (quote) {
      if (ch === "\\" && i + 1 < s.length) {
        i += 2;
        continue;
      }
      if (ch === quote) quote = null;
      i++;
      continue;
    }

    if (ch === "'" || ch === '"') {
      quote = ch;
      i++;
      continue;
    }

    if (ch === "(") {
      parenDepth++;
      i++;
      continue;
    }
    if (ch === ")") {
      parenDepth = Math.max(0, parenDepth - 1);
      i++;
      continue;
    }

    if (/\s/.test(ch) && parenDepth === 0) {
      if (i > start) tokens.push(s.slice(start, i));
      while (i < s.length && /\s/.test(s[i])) i++;
      start = i;
      continue;
    }

    i++;
  }

  if (i > start) tokens.push(s.slice(start, i));
  return tokens;
}
