import { HTMLElement } from "node-html-parser";

import { Import, transformAttrs, Transformer, TranspilationContext } from "../../transpile";
import { withPartialContainer, getPartialImports } from "../page/with-partial-container";
import { transformRepeatChildAttr } from "../utils";

export const imports: Import[] = [
  {
    name: "WmAccordionPane",
    from: "@wavemaker-ai/react-runtime/components/container/accordion/accordion-pane",
  },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    transformRepeatChildAttr(element, `fragment.item`, "$item");
    const { partialAttr } = withPartialContainer(element, context, { prop: "render" });

    element.setAttribute(
      "key",
      element.getAttribute("title") || element.getAttribute("name") || ""
    );
    const typeofdynamic = element.getAttribute("active");
    const name = element.getAttribute("name");
    if (typeofdynamic && name) {
      element.removeAttribute("name");
    }
    return `<WmAccordionPane ${typeofdynamic && name ? `name={ "accordion_" + $index + "${name}" }` : ""}  ${transformAttrs(element, context)} ${partialAttr}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "</WmAccordionPane>",
  imports: (element: HTMLElement, context: TranspilationContext) =>
    imports.concat(getPartialImports(element, context)),
} as Transformer;
