import { Import, Transformer, TranspilationContext, transformAttrs } from "../../transpile";
import { HTMLElement } from "node-html-parser";

export const imports: Import[] = [];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) =>
    `<WmPanelFooter  ${transformAttrs(element, context)}>`,
  post: (element: HTMLElement, context: TranspilationContext) => "</WmPanelFooter>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
