import { isString, isNumber } from "lodash";
import { addOptionalChaining } from "../utils.browser";

const isEvalExpression = (val: string): boolean => /^[^\.]+\.eval\(/.test(val);

/**
 * Processes a __MAP__ marker string and generates a .map() expression.
 * Format: __MAP__<arrayPath>__STRUCTURE__<structure>__PARENT__<parent>__ENDMAP__
 */
export const processMapMarker = (marker: string): string => {
  const match = marker.match(/^__MAP__(.+?)__STRUCTURE__(.+?)__PARENT__(.+?)__ENDMAP__$/);
  if (!match) return marker;

  const [, arrayPath, structureStr, parentValue] = match;
  const structure = JSON.parse(structureStr);
  const arrayProp = arrayPath.split(".").pop() || "";

  const buildMapBody = (obj: any, itemPath: string = "item"): string => {
    const parts: string[] = [];
    for (const [key, value] of Object.entries(obj)) {
      if (typeof value === "object" && value !== null) {
        if ((value as any).__isOverride) {
          const overrideValue = (value as any).value;
          const originalValue = (value as any).originalValue;
          const isFromSameSource = originalValue && originalValue.includes("[$i]");

          if (isFromSameSource) {
            const regex = new RegExp(`\\.${arrayProp}\\[\\$i\\]`);
            const m = originalValue.match(regex);
            if (m) {
              const splitIndex = originalValue.indexOf(m[0]) + m[0].length;
              let itemAccessPath = originalValue.substring(splitIndex);
              if (itemAccessPath) {
                if (itemAccessPath.startsWith(".")) {
                  itemAccessPath = itemAccessPath.substring(1);
                }
                if (itemAccessPath.startsWith("[")) {
                  parts.push(`"${key}":${itemPath}${itemAccessPath}`);
                } else {
                  parts.push(`"${key}":${itemPath}.${itemAccessPath}`);
                }
              } else {
                parts.push(`"${key}":${itemPath}`);
              }
            } else {
              parts.push(`"${key}":${formatValue(overrideValue)}`);
            }
          } else {
            if (isString(overrideValue) && isEvalExpression(overrideValue)) {
              const unwrapMatch = overrideValue.match(/\.eval\(\(\)\s*=>\s*(.+)\)$/);
              if (unwrapMatch) {
                parts.push(`"${key}":${unwrapMatch[1]}`);
              } else {
                parts.push(`"${key}":${formatValue(overrideValue)}`);
              }
            } else {
              parts.push(`"${key}":${formatValue(overrideValue)}`);
            }
          }
        } else {
          const nestedBody = buildMapBody(value, itemPath);
          parts.push(`"${key}":${nestedBody}`);
        }
      } else {
        parts.push(`"${key}":${formatValue(value)}`);
      }
    }
    return `{${parts.join(",")}}`;
  };

  const mapBody = buildMapBody(structure);
  const evalMatch = parentValue.match(/^(.+\.eval\(\(\)\s*=>\s*)(.+)\)$/);
  if (evalMatch) {
    const [, evalPrefix, evalBody] = evalMatch;
    return `${evalPrefix}${evalBody}.${arrayProp}.map(item=>(${mapBody})))`;
  }
  return `${parentValue}.${arrayProp}.map(item=>(${mapBody}))`;
};

/**
 * Formats a single value into a TypeScript/JS code string.
 */
export const formatValue = (val: any): string => {
  if (isString(val)) {
    if (val.startsWith("__MAP__")) {
      return processMapMarker(val);
    }
    if (isEvalExpression(val)) {
      return val;
    }
    return JSON.stringify(val);
  } else if (isNumber(val) || val === true || val === false || val === null) {
    return String(val);
  } else if (Array.isArray(val)) {
    return JSON.stringify(val);
  } else if (typeof val === "object" && val !== null) {
    return stringifyObject(val);
  }
  return JSON.stringify(val);
};

/**
 * Serializes a plain object into a TypeScript/JS object literal string.
 * Handles __base__ spread markers and __MAP__ markers.
 */
export const stringifyObject = (obj: any): string => {
  const parts: string[] = [];

  for (const [key, value] of Object.entries(obj)) {
    if (typeof value === "object" && value !== null && "__base__" in value) {
      const baseVal = (value as any)["__base__"];
      const nestedProps: any = {};
      const baseObject = (value as any)["__baseObject__"];
      const scopeVar = (value as any)["__scope__"];

      for (const [nestedKey, nestedVal] of Object.entries(value)) {
        if (
          nestedKey !== "__base__" &&
          nestedKey !== "__baseObject__" &&
          nestedKey !== "__scope__"
        ) {
          nestedProps[nestedKey] = nestedVal;
        }
      }

      if (baseObject && scopeVar && typeof baseObject === "object") {
        const objectToLiteral = (o: any): string =>
          Object.entries(o)
            .map(([k, v]) =>
              typeof v === "object" && v !== null && !Array.isArray(v)
                ? `"${k}":{${objectToLiteral(v)}}`
                : `"${k}":${JSON.stringify(v)}`
            )
            .join(",");

        const buildInlineEval = (obj: any, overrides: Record<string, any>): string => {
          const entries: string[] = [];
          for (const [k, v] of Object.entries(obj)) {
            if (v === undefined || v === null) continue;
            const overrideVal = overrides[k];
            if (
              overrideVal !== undefined &&
              typeof overrideVal === "object" &&
              overrideVal !== null &&
              !Array.isArray(overrideVal)
            ) {
              const overrideEntries = Object.entries(overrideVal)
                .map(([ok, ov]) => `"${ok}":${formatValue(ov)}`)
                .join(",");
              entries.push(
                `"${k}":{${objectToLiteral(v)},...${scopeVar}.eval(() => ({${overrideEntries}}))}`
              );
            } else if (overrideVal !== undefined) {
              entries.push(`"${k}":${formatValue(overrideVal)}`);
            } else if (typeof v === "object" && !Array.isArray(v)) {
              entries.push(`"${k}":{${objectToLiteral(v)}}`);
            } else {
              entries.push(`"${k}":${JSON.stringify(v)}`);
            }
          }
          return entries.join(",");
        };

        const body = buildInlineEval(baseObject, nestedProps);
        parts.push(`"${key}":${scopeVar}.eval(() => ({${body}}))`);
      } else {
        const baseFormatted = formatValue(baseVal);
        const baseSpread =
          isString(baseVal) && (baseVal.trim().startsWith("{") || baseVal.trim().startsWith("["))
            ? `JSON.parse(${baseFormatted})`
            : baseFormatted;

        let hasMapMarker = false;
        for (const nVal of Object.values(nestedProps)) {
          if (isString(nVal) && nVal.startsWith("__MAP__")) {
            hasMapMarker = true;
            break;
          }
        }

        if (hasMapMarker) {
          const processedProps: string[] = [`...${baseSpread}`];
          for (const [nKey, nVal] of Object.entries(nestedProps)) {
            if (isString(nVal) && nVal.startsWith("__MAP__")) {
              processedProps.push(`"${nKey}":${processMapMarker(nVal)}`);
            } else {
              processedProps.push(`"${nKey}":${formatValue(nVal)}`);
            }
          }
          parts.push(`"${key}":{${processedProps.join(",")}}`);
        } else {
          const nestedParts: string[] = [];
          for (const [nKey, nVal] of Object.entries(nestedProps)) {
            nestedParts.push(`"${nKey}":${formatValue(nVal)}`);
          }
          parts.push(`"${key}":{...${baseSpread},...{${nestedParts.join(",")}}}`);
        }
      }
    } else {
      parts.push(`"${key}":${formatValue(value)}`);
    }
  }

  return `{${parts.join(",")}}`;
};

/**
 * Serializes any input value into a TypeScript/JS code string.
 * Handles eval expressions, MAP markers, objects with __base__ spread, etc.
 */
export const stringify = (input: any): string => {
  if (input && typeof input === "object" && !Array.isArray(input)) {
    return stringifyObject(input);
  }
  // An eval with a trailing fallback (`Page.eval(() => x) || false`) misses the regex below.
  if (isString(input) && isEvalExpression(input)) {
    return input;
  }
  return JSON.stringify(input).replace(/"([a-zA-Z]+\.eval\(.*?\))"/g, (x: string) =>
    x.substring(1, x.length - 1).replace(/\\"/g, '"')
  );
};

/**
 * Serializes params for ModelVariable, converting actiontask values to arrow functions.
 */
export const stringifyModelParams = (input: any, scope: string): string => {
  if (input === undefined || input === null) {
    return stringify(input);
  }

  const hasActionTaskDeep = (val: any): boolean => {
    if (!val || typeof val !== "object") return false;
    if (Array.isArray(val)) return val.some(v => hasActionTaskDeep(v));
    for (const [k, v] of Object.entries(val)) {
      if (k === "actiontask") return true;
      if (v && typeof v === "object" && hasActionTaskDeep(v)) return true;
    }
    return false;
  };

  const ensureScopePrefix = (expr: string, scopeVar: string): string => {
    const trimmed = (expr || "").trim();
    if (!trimmed) return `${scopeVar}.Widgets`;
    if (trimmed.startsWith(`${scopeVar}.`)) return trimmed;
    return `${scopeVar}.${trimmed}`;
  };

  const convertObject = (obj: any): string => {
    const parts: string[] = [];
    for (const [key, value] of Object.entries(obj)) {
      if (key === "actiontask") {
        if (typeof value === "string") {
          const v = value.trim();
          if (v.startsWith("() =>") || v.startsWith("function")) {
            parts.push(`"${key}":${v}`);
          } else {
            const prefixed = ensureScopePrefix(v, scope);
            let optionalized = addOptionalChaining(prefixed);
            optionalized = optionalized?.replace(
              /(\?\.[a-zA-Z_$][a-zA-Z0-9_$]*)(\s*\()/g,
              "$1?.$2"
            );
            parts.push(`"${key}":() => ${optionalized}`);
          }
        } else {
          parts.push(`"${key}":${stringify(value)}`);
        }
      } else if (Array.isArray(value)) {
        const items = value.map(it => {
          if (it && typeof it === "object" && !Array.isArray(it) && hasActionTaskDeep(it)) {
            return convertObject(it);
          }
          return stringify(it);
        });
        parts.push(`"${key}":[${items.join(",")}]`);
      } else if (value && typeof value === "object") {
        if (hasActionTaskDeep(value)) {
          parts.push(`"${key}":${convertObject(value)}`);
        } else {
          parts.push(`"${key}":${stringify(value)}`);
        }
      } else {
        parts.push(`"${key}":${stringify(value)}`);
      }
    }
    return `{${parts.join(",")}}`;
  };

  if (Array.isArray(input)) {
    const items = input.map(it =>
      it && typeof it === "object" && !Array.isArray(it) ? convertObject(it) : stringify(it)
    );
    return `[${items.join(",")}]`;
  }
  if (typeof input === "object") {
    return convertObject(input);
  }
  return stringify(input);
};

/**
 * Wraps a string value in quotes; leaves numbers, booleans, and eval expressions as-is.
 */
export const quoteIfString = (arg: string): string => {
  if (arg === "") return `"${arg}"`;
  if (!isNaN(arg as any) || arg === "true" || arg === "false") return arg;
  if (isString(arg) && (isEvalExpression(arg) || arg.trim().startsWith("() =>"))) return arg;
  if (isString(arg) && !isEvalExpression(arg)) return JSON.stringify(arg);
  return arg;
};

/**
 * Quotes an object key if it contains a hyphen (for valid JS object literal syntax).
 */
export const quoteKeyIfHyphen = (str: string): string => {
  if (isString(str) && str.includes("-")) return JSON.stringify(str);
  return str;
};
