import { HTMLElement } from "node-html-parser";

import { Import, transformAttrs, Transformer, TranspilationContext } from "../../transpile";

export const imports: Import[] = [
  {
    name: "WmProgressBar",
    from: "@wavemaker-ai/react-runtime/components/basic/progress-bar",
  },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    return `<WmProgressBar ${transformAttrs(element, context)}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "</WmProgressBar>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
