import { useState, useRef, useCallback } from "react";
const useEditingState = () => {
  const [editingRowId, setEditingRowId] = useState(null);
  const [isAddingNewRow, setIsAddingNewRow] = useState(false);
  const [sessionKey, setSessionKey] = useState(0);
  const editingRowDataRef = useRef({});
  const newRowDataRef = useRef({});
  const incrementSessionKey = useCallback(() => {
    setSessionKey((prev) => prev + 1);
  }, []);
  const resetEditingData = useCallback(() => {
    editingRowDataRef.current = {};
    newRowDataRef.current = {};
  }, []);
  const isRowEditing = useCallback(
    (rowId) => {
      return editingRowId === rowId;
    },
    [editingRowId]
  );
  return {
    editingRowId,
    isAddingNewRow,
    sessionKey,
    editingRowDataRef,
    newRowDataRef,
    setEditingRowId,
    setIsAddingNewRow,
    incrementSessionKey,
    resetEditingData,
    isRowEditing
  };
};
export {
  useEditingState
};
