const spaceCache: Array<string> = [""];

export const createSpace = (num = 0): string => {
  if (spaceCache[num] == undefined) {
    spaceCache[num] = " " + createSpace(num - 1);
  }
  return spaceCache[num];
};

export const prependSpace = (input: string, num = 0): string => {
  const space = createSpace(num);
  return input
    .split("\n")
    .map(s => space + s)
    .join("\n");
};
