import { HTMLElement } from "node-html-parser";

import { Import, transformAttrs, Transformer, TranspilationContext } from "../../transpile";
import { withPartialContainer, getPartialImports } from "../page/with-partial-container";

export const imports: Import[] = [
  {
    name: "WmContainer",
    from: "@wavemaker-ai/react-runtime/components/container",
  },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const { partialAttr } = withPartialContainer(element, context, {
      prop: "renderPartial",
      removeName: true,
    });
    return `<WmContainer listener={fragment} ${transformAttrs(element, context)} ${partialAttr}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "</WmContainer>",
  imports: (element: HTMLElement, context: TranspilationContext) => {
    return imports.concat(getPartialImports(element, context));
  },
} as Transformer;
