import { HTMLElement } from "node-html-parser";

import {
  createExpression,
  Import,
  transformAttrs,
  Transformer,
  TranspilationContext,
} from "../../transpile";
import { extractDatasetInfo, getDatasourceExpr, getOnChangeExprforFormWidget } from "../utils";

export const imports: Import[] = [
  { name: "WmSearch", from: "@wavemaker-ai/react-runtime/components/basic/search" },
];

const getDatasetVariable = (element: HTMLElement) => {
  const dataset = element.getAttribute("dataset");
  if (dataset) {
    const variableArr = dataset.match(/(fragment)+\.Variables\.[^\.]+/g);
    if (variableArr && variableArr.length) {
      return variableArr[0];
    }
  }
};

const getUpdateRequiredExpr = (element: HTMLElement) => {
  let variable = getDatasetVariable(element);
  if (variable) {
    return `() => ${variable} && ${variable}?.serviceInfo?.parameters.length`;
  }
};

const getSearchSubmitExpr = (element: HTMLElement) => {
  let variable = getDatasetVariable(element);
  if (variable) {
    return `async (params, success, error) => {
        try {
          ${variable} && ${variable}.setInput(params);
          const result = await ${variable}.invoke();
          success(result?.data);
          return result?.data;
        } catch (err) {
          error(err);
        }
      }`;
  }
};

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    let getDisplayExpression =
      createExpression(element, "displayexpression") || createExpression(element, "displaylabel");
    if (getDisplayExpression) {
      element.removeAttribute("displayexpression");
      element.removeAttribute("displaylabel");
    }
    let displayimagesrc = element.getAttribute("displayimagesrc");
    let getDisplayimagesrc = null;
    if (
      displayimagesrc &&
      displayimagesrc.startsWith("bind:") &&
      !displayimagesrc.startsWith("bind:$formField")
    ) {
      getDisplayimagesrc = createExpression(element, "displayimagesrc");
      element.removeAttribute("displayimagesrc");
    }
    if (element.getAttribute("type") === "autocomplete") {
      const classname = element.getAttribute("class") || "";
      element.setAttribute("class", `app-autocomplete ${classname}`);
    }
    const onSelect = getOnChangeExprforFormWidget(element, "on-select", context);
    const isFormField = element.getAttribute("formfield") === "true";
    getDatasourceExpr(element);

    return `<WmSearch listener={fragment} ${isFormField ? " {...$formField}" : ""} ${extractDatasetInfo(element)} ${transformAttrs(element, context)}
      ${getDisplayExpression ? `getDisplayExpression=${getDisplayExpression} ` : ""}
      ${getDisplayimagesrc ? `displayimagesrc=${getDisplayimagesrc} ` : ``} ${onSelect ? `onSelect={${onSelect}}` : ""}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "</WmSearch>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
