import { HTMLElement } from "node-html-parser";

import {
  createComponent,
  Import,
  transformAttrs,
  Transformer,
  TranspilationContext,
} from "../../transpile";

export const imports: Import[] = [
  {
    name: "WmPageContent",
    from: "@wavemaker-ai/react-runtime/components/page/page-content",
  },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) =>
    `<WmPageContent ${transformAttrs(element, context)} >`,
  post: (element: HTMLElement, context: TranspilationContext) => "</WmPageContent>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
  createComponent: (element: HTMLElement, context: TranspilationContext) =>
    createComponent(element, context),
} as Transformer;
