import { HTMLElement } from "node-html-parser";

import { Import, transformAttrs, Transformer, TranspilationContext } from "../../../transpile";

export const imports: Import[] = [
  {
    name: "WmDynamicFields",
    from: "@wavemaker-ai/react-runtime/components/data/form/dynamic-fields",
  },
];

const getBeforeRenderEx = (element: HTMLElement) => {
  const beforeRender = element.getAttribute("on-beforerender");
  return beforeRender ? `($metadata, widget) =>{return ${beforeRender}}` : "";
};

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const beforeRender = getBeforeRenderEx(element);
    element.removeAttribute("on-beforerender");

    return `<WmDynamicFields listener={fragment} ${beforeRender ? `onBeforeRender={${beforeRender}}` : ""}  ${transformAttrs(element, context)}`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "/>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
