import { MultiDimensionStyleParser } from "./multi-dimension-style.parser";

export class PaddingParser extends MultiDimensionStyleParser {
  constructor() {
    super("padding");
  }

  parse(value: string) {
    const values = super.parseDimensions(value);
    return {
      paddingTop: values[0],
      paddingRight: values[1],
      paddingBottom: values[2],
      paddingLeft: values[3],
    };
  }
}
