import { HTMLElement } from "node-html-parser";

import {
  createComponent,
  Import,
  transformAttrs,
  Transformer,
  TranspilationContext,
} from "../../transpile";

export const imports: Import[] = [
  {
    name: "WmPartial",
    from: "@wavemaker-ai/react-runtime/components/page/partial",
  },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    return `<WmPartial iswidget="false" data-role="partial"  ${transformAttrs(element, context)} >`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "</WmPartial>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
  createComponent: (element: HTMLElement, context: TranspilationContext) =>
    createComponent(element, context),
} as Transformer;
