import { HTMLElement } from "node-html-parser";

import { transformRepeatChildData } from "../utils";
import {
  createComponent,
  Import,
  isHTMLElement,
  transformAttrs,
  Transformer,
  TranspilationContext,
} from "../../transpile";

export const imports: Import[] = [
  {
    name: "WmAccordion",
    from: "@wavemaker-ai/react-runtime/components/container/accordion",
  },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const widgetName = element.attrs["name"];
    let dataSet = element.getAttribute("dataset");
    if (dataSet && dataSet.startsWith("bind:") && element.getAttribute("type") === "dynamic") {
      dataSet = dataSet.substring(5);
      const template = element.childNodes.find(c => isHTMLElement(c));

      const accordionPane = template?.childNodes.find(c => isHTMLElement(c));
      if (accordionPane) {
        accordionPane.setAttribute("active", "bind:$item.active");
        accordionPane.setAttribute("toggle", "bind:$item.toggle");
      }

      transformRepeatChildData(
        template as HTMLElement,
        dataSet + "[0]",
        "repeat_item",
        true,
        widgetName
      );
      transformRepeatChildData(
        template as HTMLElement,
        dataSet + "[$i]",
        "repeat_item",
        true,
        widgetName
      );
      transformRepeatChildData(
        template as HTMLElement,
        dataSet + "[fragment.$i]",
        "repeat_item",
        true,
        widgetName
      );
      transformRepeatChildData(
        template as HTMLElement,
        dataSet + "[fragment.$i]",
        "repeat_item",
        true,
        widgetName
      );
      context.set("old_props", context.props);
      context.props = ["$item", "$index"];

      return `<WmAccordion listener={fragment} ${transformAttrs(element, context)} render={(($item:Record<string,any>,$index:number,data:Record<string,any>[])=>(`;
    }
    return `<WmAccordion listener={fragment} ${transformAttrs(element, context)}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => {
    let dataSet = element.getAttribute("dataset");
    if (dataSet && dataSet.startsWith("bind:") && element.getAttribute("type") === "dynamic") {
      context.props = context.get("old_props");
      return context.get("old_props") ? "))}/>" : "</WmAccordion>";
    }
    return "</WmAccordion>";
  },
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
  createComponent: (element: HTMLElement, context: TranspilationContext) => {
    context.props = [];
    return createComponent(element, context);
  },
} as Transformer;
