import { HTMLElement } from "node-html-parser";

import {
  Import,
  transformAttrs,
  createExpression,
  Transformer,
  TranspilationContext,
} from "../../transpile";
import { extractDatasetInfo } from "../utils";

export const imports: Import[] = [
  { name: "WmMenu", from: "@wavemaker-ai/react-runtime/components/navigation/menu" },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    // Handle itemlabel expression
    let itemlabelExpression;
    const itemlabel = element.getAttribute("itemlabel");
    if (itemlabel && itemlabel.startsWith("bind:")) {
      itemlabelExpression = createExpression(element, "itemlabel");
      if (itemlabelExpression) {
        element.removeAttribute("itemlabel");
      }
    }

    // Handle itemchildren expression
    let itemchildrenExpression;
    const itemchildren = element.getAttribute("itemchildren");
    if (itemchildren && itemchildren.startsWith("bind:")) {
      itemchildrenExpression = createExpression(element, "itemchildren");
      if (itemchildrenExpression) {
        element.removeAttribute("itemchildren");
      }
    }

    return `<WmMenu  ${extractDatasetInfo(element)} ${transformAttrs(element, context)} listener={fragment}
      ${itemlabelExpression ? `itemlabel=${itemlabelExpression}` : ""}
      ${itemchildrenExpression ? `itemchildren=${itemchildrenExpression}` : ""}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "</WmMenu>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
