import { HTMLElement } from "node-html-parser";

import {
  Import,
  isHTMLElement,
  Transformer,
  TranspilationContext,
  transformAttrs,
} from "../../transpile";

export const imports: Import[] = [
  {
    name: "WmNavbar",
    from: "@wavemaker-ai/react-runtime/components/navbar",
  },
];

// Helper function to find navbar-header element
const findNavbarHeader = (element: HTMLElement): HTMLElement | null => {
  for (const child of element.childNodes) {
    if (isHTMLElement(child)) {
      // Check if this is the container-fluid div
      if (child.classList?.contains("container-fluid")) {
        // Look for navbar-header inside container-fluid
        for (const containerChild of child.childNodes) {
          if (
            isHTMLElement(containerChild) &&
            containerChild.classList?.contains("navbar-header")
          ) {
            return containerChild;
          }
        }
      }
      // Also check direct children for navbar-header
      if (child.classList?.contains("navbar-header")) {
        return child;
      }
    }
  }
  return null;
};

// Extract brand/title from navbar-header
const extractBrandInfo = (
  navbarHeader: HTMLElement
): { title: string | null; href: string | null } => {
  let title: string | null = null;
  let href: string | null = null;

  for (const child of navbarHeader.childNodes) {
    if (
      isHTMLElement(child) &&
      child.tagName === "A" &&
      child.classList?.contains("navbar-brand")
    ) {
      href = child.getAttribute("href") || "#/";

      // Look for title span inside the anchor
      for (const brandChild of child.childNodes) {
        if (isHTMLElement(brandChild) && brandChild.classList?.contains("title")) {
          title = brandChild.textContent?.trim() || null;
          break;
        }
      }
      break;
    }
  }

  return { title, href };
};

// Remove navbar-header from the DOM so it doesn't get rendered as children
const removeNavbarHeader = (element: HTMLElement): void => {
  for (const child of element.childNodes) {
    if (isHTMLElement(child)) {
      // Check if this is the container-fluid div
      if (child.classList?.contains("container-fluid")) {
        // Look for and remove navbar-header inside container-fluid
        for (let i = child.childNodes.length - 1; i >= 0; i--) {
          const containerChild = child.childNodes[i];
          if (
            isHTMLElement(containerChild) &&
            containerChild.classList?.contains("navbar-header")
          ) {
            containerChild.remove();
            return;
          }
        }
      }
      // Also check direct children for navbar-header
      if (child.classList?.contains("navbar-header")) {
        child.remove();
        return;
      }
    }
  }
};

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const layout = element.getAttribute("layout");
    if (layout) {
      const className = layout === "stacked" ? "stackedNav " : "justifiedNav ";
      if (layout === "stacked") {
        element.setAttribute("class", className + (element.getAttribute("class") || ""));
      } else {
        element.setAttribute("class", className + (element.getAttribute("class") || ""));
      }
    }

    if (!element.hasAttribute("dataset")) {
      element.childNodes.forEach(n => {
        if (isHTMLElement(n) && n.tagName === "WM-NAV-ITEM") {
          n.setAttribute("defaultview", "true");
        }
      });
    }

    // Check if navbar-header exists in the structure and remove it to avoid duplicate rendering
    // The title and brand info are already handled by transformAttrs
    const navbarHeader = findNavbarHeader(element);
    if (navbarHeader) {
      // Lift the brand anchor's href onto `homelink` — the navbar's only link property (see the
      // Angular `wm.layouts.navbar` schema). It used to be written as `brandhref`, which no
      // widget property matches, so the runtime never received it.
      if (!element.hasAttribute("homelink")) {
        const { href } = extractBrandInfo(navbarHeader);
        if (href) {
          element.setAttribute("homelink", href);
        }
      }

      // Remove the navbar-header so it doesn't render as children
      removeNavbarHeader(element);
    }

    return `<WmNavbar 
      ${transformAttrs(element, context)}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "</WmNavbar>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
