import transformEx from "../transpile/bind.ex.transformer";
import { buildServiceClassName, toPascalCase } from "../services/schema-to-ts";
import { deriveMethodName } from "../services/doc-normalizer";
import { MethodArg } from "../services/method-emitter";
import { stringify } from "../transpile/serialize-variables";
import { CrudOperationTarget } from "../services/service.generator";
import {
  isEmpty,
  forEach,
  isBoolean,
  isNumber,
  isObject,
  isArray,
  clone,
  upperFirst,
  get,
  set,
} from "lodash";

function bindingValueIsStatic(value: any): boolean {
  const v = Array.isArray(value) ? value[0] : value;
  return !v || !(typeof v === "string" && v.startsWith("bind:"));
}

function hasDataSetBinding(value: any): boolean {
  if (typeof value === "string") return value.startsWith("bind:");
  return isObject(value) && Object.values(value).some(hasDataSetBinding);
}

export function shouldAutoUpdateVariable(variable: any): boolean {
  return !!(
    variable.autoUpdate ||
    ((variable.category === "wm.Variable" || variable.category === "wm.LiveVariable") &&
      variable.dataBinding &&
      variable.dataBinding.length) ||
    (variable.category === "wm.Variable" && hasDataSetBinding(variable.dataSet))
  );
}

function filterExpressionsAreStatic(filterExpressions: any): boolean {
  if (!filterExpressions?.rules) return true;

  const ruleIsStatic = (rule: any): boolean => {
    if (rule.rules) {
      return rule.rules.every(ruleIsStatic);
    }
    return bindingValueIsStatic(rule.value);
  };

  return filterExpressions.rules.every(ruleIsStatic);
}

function isStaticParamsVariable(variable: any): boolean {
  const db = variable.dataBinding;

  const entryIsStatic = (entry: any): boolean => bindingValueIsStatic(entry.value);

  if (db) {
    if (Array.isArray(db)) {
      if (!db.every(entryIsStatic)) return false;
    } else if (isObject(db) && !Array.isArray(db)) {
      const allOpsStatic = Object.values(db).every((opBindings: any) => {
        if (!Array.isArray(opBindings)) return true;
        return opBindings.every(entryIsStatic);
      });
      if (!allOpsStatic) return false;
    }
  }

  return filterExpressionsAreStatic(variable.filterExpressions);
}

// Converts plural entity name to singular: Countries→Country, Addresses→Address, Users→User
function simpleSingularize(plural: string): string {
  const lower = plural.toLowerCase();
  if (lower.endsWith("ies")) return plural.substring(0, plural.length - 3) + "y";
  if (lower.endsWith("es")) return plural.substring(0, plural.length - 2);
  if (lower.endsWith("s")) return plural.substring(0, plural.length - 1);
  return plural;
}

// Converts singular entity name to plural following English morphology rules:
// Employee→Employees, Country→Countries, Address→Addresses, Church→Churches, Day→Days
function simplePluralize(singular: string): string {
  if (!singular) return singular;
  const last = singular[singular.length - 1].toLowerCase();
  const prev = singular.length > 1 ? singular[singular.length - 2].toLowerCase() : null;
  const vowels = "aeiouy";
  if (last === "x" || last === "s") {
    return singular + "es";
  } else if (last === "y") {
    return prev !== null && vowels.includes(prev)
      ? singular + "s" // Day → Days
      : singular.slice(0, -1) + "ies"; // City → Cities
  } else if (last === "h") {
    return prev !== null && (prev === "c" || prev === "s")
      ? singular + "es" // Church→Churches, Dish→Dishes
      : singular + "s";
  } else {
    return singular + "s";
  }
}

function parseStaticJsonValue(value: string) {
  const trimmedValue = value.trim();
  if (!trimmedValue.startsWith("{") && !trimmedValue.startsWith("[")) {
    return value;
  }
  try {
    return JSON.parse(trimmedValue);
  } catch {
    return value;
  }
}

function transformDataItem(d: any, scope: string) {
  let v = isArray(d.value) ? d.value[0] : d.value;
  let arrayIndex: number | null = null;

  if (v) {
    if (v.startsWith && v.startsWith("bind:")) {
      // "value" : "bind:'Do you want to delete this product: \"'+Widgets.Cart_Details.selecteditem.productDetails.productName+'\" from your Cart'",
      const originalValue = v.substr(5);
      v = originalValue;

      // Check if the value contains array indexing like [$i] or [0]
      const arrayIndexMatch = v.match(/\[(\$i|\d+)\]/);
      if (arrayIndexMatch) {
        // Extract the index (convert $i to 0 for now, or use the number)
        arrayIndex = arrayIndexMatch[1] === "$i" ? 0 : parseInt(arrayIndexMatch[1], 10);
      }

      // Remove trailing semicolons and trim whitespace from binding expressions
      v = (v || "").trim().replace(/;+\s*$/, "");
      if (v === "null") {
        v = null;
      } else {
        const transformed = transformEx(v, scope, "attr").replace(/\\n/g, "");
        // If the expression starts with '{', it's an object literal and needs to be wrapped in ()
        // to distinguish it from a block statement in arrow functions
        if (transformed.trim().startsWith("{")) {
          v = `${scope}.eval(() => (${transformed}))`;
        } else {
          v = `${scope}.eval(() => ${transformed})`;
        }
      }
    } else if (typeof v === "string") {
      v = parseStaticJsonValue(v);
    } else if (d.type === "string") {
      v = `${v}`;
    }
  }
  return {
    name: d.target,
    value: v,
    arrayIndex: arrayIndex,
  };
}

function appendIfNotEmpty(input: string, str: string) {
  return input && input + "";
}

function checkEmptyObject(obj: any) {
  let isVariableEmpty = true;
  forEach(obj, (value: any) => {
    if (isEmpty(value) && !isBoolean(value) && !isNumber(value)) {
      return;
    }
    if (!isObject(value)) {
      isVariableEmpty = false;
    } else if (isArray(value)) {
      isVariableEmpty = isEmpty(value) || (value.length === 1 ? isEmpty(value[0]) : false);
    } else {
      isVariableEmpty = checkEmptyObject(value);
    }
    return isVariableEmpty;
  });
  return isVariableEmpty;
}

function transformDataSetBindings(dataSet: any, scope: string): any {
  if (typeof dataSet === "string" && dataSet.startsWith("bind:")) {
    let v = dataSet.substring(5);
    v = (v || "").trim().replace(/;+\s*$/, "");
    if (v === "null") {
      return null;
    } else {
      const transformed = transformEx(v, scope, "attr").replace(/\\n/g, "");
      if (transformed.trim().startsWith("{")) {
        return `${scope}.eval(() => (${transformed}))`;
      } else {
        return `${scope}.eval(() => ${transformed})`;
      }
    }
  } else if (isArray(dataSet)) {
    return dataSet.map((item: any) => transformDataSetBindings(item, scope));
  } else if (isObject(dataSet) && dataSet !== null) {
    const result: any = {};
    for (const [key, value] of Object.entries(dataSet)) {
      result[key] = transformDataSetBindings(value, scope);
    }
    return result;
  }
  return dataSet;
}

function transformVariable(variable: any, scope: string) {
  let params: any = {},
    filters: any = {};
  if (variable.category !== "wm.DeviceVariable") {
    if (isArray(variable.dataSet)) {
      if (variable.category === "wm.NavigationAction") {
        variable.dataSet.forEach((d: any) => {
          const { name, value } = transformDataItem(d, scope);
          set(params, name, value);
        });
      } else if (variable.category === "wm.Variable") {
        params = transformDataSetBindings(clone(variable.dataSet), scope);
      }
    } else if (isBoolean(variable.dataSet) || isNumber(variable.dataSet)) {
      if (variable.category === "wm.Variable") {
        params = variable.dataSet;
      }
    } else if (variable.dataSet) {
      Object.keys(variable.dataSet).forEach(k => {
        if (params[k] == undefined || params[k] == null) {
          set(params, k, get(variable.dataSet, k));
        }
      });
      if (variable.category === "wm.Variable") {
        params = transformDataSetBindings(params, scope);
      }
    }
  }
  if (variable.dataBinding) {
    if (Array.isArray(variable.dataBinding)) {
      // First pass: collect all bindings and identify conflicts

      const bindings: Array<{
        name: string;
        value: any;
        arrayIndex: number | null;
        originalValue: string;
      }> = [];
      const parentKeys = new Set<string>(); // Keys that have direct bindings
      const nestedKeys = new Map<
        string,
        Array<{ name: string; value: any; arrayIndex: number | null; originalValue: string }>
      >(); // Parent -> array of nested bindings

      variable.dataBinding?.forEach((d: any) => {
        // Capture the original bind value BEFORE transformation
        const originalValue =
          d.value && d.value.startsWith && d.value.startsWith("bind:")
            ? d.value.substr(5)
            : d.value;
        const { name, value, arrayIndex } = transformDataItem(d, scope);

        let finalValue = value;
        if (
          variable.dataSet &&
          !isArray(variable.dataSet) &&
          variable.dataSet.hasOwnProperty(name)
        ) {
          const defaultValue = get(variable.dataSet, name);
          // Only add fallback if:
          // 1. The binding is an expression (not a static value)
          // 2. There's a default value (including empty strings and arrays)
          if (d.value && d.value.startsWith && d.value.startsWith("bind:")) {
            // Format default value appropriately
            let formattedDefault: string;
            if (typeof defaultValue === "string") {
              formattedDefault = `"${defaultValue}"`;
            } else if (isArray(defaultValue)) {
              formattedDefault = JSON.stringify(defaultValue);
            } else if (isObject(defaultValue)) {
              formattedDefault = JSON.stringify(defaultValue);
            } else if (defaultValue === null) {
              formattedDefault = "null";
            } else if (defaultValue === undefined) {
              formattedDefault = "undefined";
            } else {
              formattedDefault = String(defaultValue);
            }
            // Append fallback: value || defaultValue
            finalValue = `${value} || ${formattedDefault}`;
          }
        }

        bindings.push({ name, value: finalValue, arrayIndex, originalValue });

        const parts = name.split(".");
        if (parts.length === 1) {
          // Direct binding for a key
          parentKeys.add(name);
        } else {
          // Nested binding
          const parentKey = parts[0];
          if (!nestedKeys.has(parentKey)) {
            nestedKeys.set(parentKey, []);
          }
          nestedKeys.get(parentKey)!.push({ name, value: finalValue, arrayIndex, originalValue });
        }
      });

      // Helper to check if nested bindings involve arrays
      const hasArrayBindings = (key: string): boolean => {
        const nested = nestedKeys.get(key);
        if (!nested) return false;
        // Check if any nested binding has an array index
        return nested.some(n => n.arrayIndex !== null);
      };

      // Helper to check if nested bindings are complex (deep nesting > 2 levels)
      const hasComplexNesting = (key: string): boolean => {
        const nested = nestedKeys.get(key);
        if (!nested) return false;
        // Check if any nested path has more than 2 levels (e.g., RequestBody.serviceQualificationItem.resource)
        return nested.some(n => n.name.split(".").length > 2);
      };

      // Helper to group array bindings by their array path
      const groupArrayBindings = (key: string) => {
        const nested = nestedKeys.get(key) || [];
        const arrayGroups = new Map<
          string,
          Array<{ path: string; value: any; originalValue: string }>
        >();

        // First, identify which paths have array bindings (have [$i] in their values)
        const arrayPaths = new Set<string>();
        nested.forEach(n => {
          if (n.arrayIndex !== null) {
            const parts = n.name.split(".");
            if (parts.length >= 3) {
              const arrayPath = `${parts[0]}.${parts[1]}`;
              arrayPaths.add(arrayPath);
            }
          }
        });

        // Now group ALL bindings that go through these array paths
        nested.forEach(n => {
          const parts = n.name.split(".");
          if (parts.length >= 3) {
            // Check if this path goes through any identified array path
            const potentialArrayPath = `${parts[0]}.${parts[1]}`;

            // Include if: either has arrayIndex OR goes through an array path
            if (n.arrayIndex !== null || arrayPaths.has(potentialArrayPath)) {
              if (!arrayGroups.has(potentialArrayPath)) {
                arrayGroups.set(potentialArrayPath, []);
              }
              // Remaining path after the array (e.g., resource.id from RequestBody.serviceQualificationItem.resource.id)
              const remainingPath = parts.slice(2).join(".");
              arrayGroups
                .get(potentialArrayPath)!
                .push({ path: remainingPath, value: n.value, originalValue: n.originalValue });
            }
          }
        });

        return arrayGroups;
      };

      // Helper to generate map expression for array bindings
      const generateMapExpression = (
        arrayPath: string,
        items: Array<{ path: string; value: any; originalValue: string }>,
        parentValue: any
      ): string => {
        // Build the nested object structure for map
        const structure: any = {};
        items.forEach(item => {
          set(structure, item.path, {
            __isOverride: true,
            value: item.value,
            originalValue: item.originalValue,
          });
        });

        // Generate map expression
        const arrayPathParts = arrayPath.split(".");
        const arraySourcePath = arrayPathParts.join(".");

        return `__MAP__${arraySourcePath}__STRUCTURE__${JSON.stringify(structure)}__PARENT__${parentValue}__ENDMAP__`;
      };

      // Second pass: process bindings based on conflicts
      bindings.forEach(({ name, value, arrayIndex, originalValue }) => {
        const parts = name.split(".");

        if (parts.length === 1) {
          // This is a direct binding
          const hasNestedBindings = nestedKeys.has(name);

          if (hasNestedBindings && !hasComplexNesting(name) && !hasArrayBindings(name)) {
            // Simple case: There are nested bindings but they're not deep and no arrays
            // We can safely merge with spread operator
            // Example: RequestBody -> RequestBody.state
            const parentValue = value;
            const parentObj: any = { __base__: parentValue };
            nestedKeys.get(name)!.forEach(nested => {
              const nestedParts = nested.name.split(".");
              if (nestedParts.length === 2 && nestedParts[0] === name) {
                parentObj[nestedParts[1]] = nested.value;
              }
            });
            set(params, name, parentObj);
          } else if (hasNestedBindings && (hasComplexNesting(name) || hasArrayBindings(name))) {
            // Complex case with arrays - use map expression
            const parentObj: any = { __base__: value };

            // Group array bindings and create map expressions
            const arrayGroups = groupArrayBindings(name);
            arrayGroups.forEach((items, arrayPath) => {
              const mapExpr = generateMapExpression(arrayPath, items, value);
              // Extract the array property name (last part of the path)
              const arrayProp = arrayPath.split(".").pop();
              if (arrayProp) {
                // Store map marker directly in parent object, not using set()
                parentObj[arrayProp] = mapExpr;
              }
            });

            // Handle all non-array nested bindings (including deep paths like RequestBody.payload.templateInput.year)
            // Exclude bindings that go through array paths (already handled by arrayGroups above)
            const arrayRelativePaths = Array.from(arrayGroups.keys()).map(ap =>
              ap.split(".").slice(1).join(".")
            );
            nestedKeys.get(name)!.forEach(nested => {
              if (nested.arrayIndex === null) {
                const nestedParts = nested.name.split(".");
                if (nestedParts[0] === name && nestedParts.length > 1) {
                  const relativePath = nestedParts.slice(1).join(".");
                  // Skip if this path goes through an array (e.g. serviceQualificationItem.resource.id)
                  const goesThroughArray = arrayRelativePaths.some(
                    rp => relativePath === rp || relativePath.startsWith(rp + ".")
                  );
                  if (!goesThroughArray) {
                    set(parentObj, relativePath, nested.value);
                  }
                }
              }
            });

            // For inline eval format: when no array bindings and base is JSON, store parsed base for stringify
            if (arrayGroups.size === 0 && originalValue && typeof originalValue === "string") {
              const trimmed = originalValue.trim();
              if ((trimmed.startsWith("{") || trimmed.startsWith("[")) && trimmed.length > 1) {
                try {
                  parentObj.__baseObject__ = JSON.parse(originalValue);
                  parentObj.__scope__ = scope;
                } catch {
                  // Ignore parse errors
                }
              }
            }

            // Set the parent object with all properties
            set(params, name, parentObj);
          } else {
            // No conflicts, just set the value
            set(params, name, value);
          }
        } else {
          // This is a nested binding - already handled in parent block for array cases
          const parentKey = parts[0];
          if (!parentKeys.has(parentKey)) {
            // No parent binding, set normally
            set(params, name, value);
          }
        }
      });

      if (params.dataBinding) {
        params = params.dataBinding;
      }
    } else if (
      variable.category === "wm.CrudVariable" &&
      isObject(variable.dataBinding) &&
      !isArray(variable.dataBinding)
    ) {
      // Transform dataBinding object for CrudVariable
      // Input: { list: [...], create: [...], update: [...], delete: [...] }
      // Output: dataBinding: () => ({ list: [...], create: [...], update: [...], delete: [...] })

      // Helper function to format value for JavaScript object literal
      const formatValue = (value: any): string => {
        if (value === null) {
          return "null";
        }
        if (value === undefined) {
          return "undefined";
        }
        if (typeof value === "string") {
          // If it's already a transformed expression (contains .eval), return as-is without quotes
          if (value.includes(".eval(")) {
            return value;
          }
          // Otherwise, quote it as a string
          return JSON.stringify(value);
        }
        if (typeof value === "number" || typeof value === "boolean") {
          return String(value);
        }
        return JSON.stringify(value);
      };

      // Build array of binding objects
      const buildBindingArray = (bindings: any[]): string => {
        return bindings
          .map((binding: any) => {
            const transformed = transformDataItem(binding, scope);
            const props: string[] = [];

            // Always include target
            props.push(`"target" : ${JSON.stringify(binding.target)}`);

            // Format value - use transformed value if it's an expression, otherwise use original
            let finalValue: any;
            if (transformed.value !== undefined && transformed.value !== null) {
              // If transformed value is a template literal (wrapped in backticks), extract the inner value
              if (
                typeof transformed.value === "string" &&
                transformed.value.startsWith("`") &&
                transformed.value.endsWith("`")
              ) {
                finalValue = transformed.value.slice(1, -1);
              } else if (
                typeof transformed.value === "string" &&
                transformed.value.includes(".eval(")
              ) {
                // It's a transformed expression, use as-is
                finalValue = transformed.value;
              } else {
                // Use transformed value, but check if we should preserve original type
                finalValue = transformed.value;
              }
            } else {
              finalValue = binding.value || "";
            }
            props.push(`"value" : ${formatValue(finalValue)}`);

            // Always include type
            props.push(`"type" : ${JSON.stringify(binding.type)}`);

            // Include isList if it exists
            if (binding.hasOwnProperty("isList")) {
              props.push(`"isList" : ${binding.isList}`);
            }

            return `{\n      ${props.join(`,\n      `)}\n    }`;
          })
          .join(" , ");
      };

      // Build the object string
      const objectParts: string[] = [];
      Object.keys(variable.dataBinding).forEach((operationKey: string) => {
        const operationBindings = variable.dataBinding[operationKey];
        if (isArray(operationBindings)) {
          objectParts.push(`"${operationKey}" : [ ${buildBindingArray(operationBindings)} ]`);
        } else {
          objectParts.push(`"${operationKey}" : ${formatValue(operationBindings)}`);
        }
      });

      // Store transformed dataBinding on variable object for use in transformCrudVariable
      // Don't add it to params so it doesn't end up in paramProvider
      variable._transformedDataBinding = `() => ({\n      ${objectParts.join(`,\n      `)}\n    })`;
      // Remove dataBinding from params if it exists to prevent it from going into paramProvider
      if (params.dataBinding) {
        delete params.dataBinding;
      }
    }
  }
  const filterProvider = (rules: any) => {
    rules?.forEach((r: any) => {
      if (r.rules) {
        filterProvider(r.rules);
      } else {
        const { name, value } = transformDataItem(r, scope);
        filters[name] = value;
      }
    });
  };

  if (variable.filterExpressions) {
    filterProvider(variable.filterExpressions.rules);
  }

  // Todo: these properties directly on variable are to be handled from studio
  if (variable.category === "wm.DeviceVariable" && variable.operation === "scanBarCode") {
    params["barcodeFormat"] = variable.barcodeFormat;
  }
  if (
    variable.category === "wm.DeviceVariable" &&
    variable.service === "file" &&
    variable.operation === "upload"
  ) {
    params["browse"] = !variable.localFile;
  }
  const obj: any = {
    name: variable.name,
    group: "variable",
    params: params,
    filters: filters,
    onSuccess: appendIfNotEmpty(transformEx(variable.onSuccess, scope, "event"), ";"),
    onError: appendIfNotEmpty(transformEx(variable.onError, scope, "event"), ";"),
  };
  if (variable.onCanUpdate) {
    obj.onCanUpdate = appendIfNotEmpty(transformEx(variable.onCanUpdate, scope, "event"), ";");
  }
  if (variable.onBeforeUpdate) {
    obj.onBeforeUpdate = appendIfNotEmpty(
      transformEx(variable.onBeforeUpdate, scope, "event"),
      ";"
    );
  }
  if (variable.onResult) {
    obj.onResult = appendIfNotEmpty(transformEx(variable.onResult, scope, "event"), ";");
  }
  if (variable.onOnline) {
    obj.onOnline = appendIfNotEmpty(transformEx(variable.onOnline, scope, "event"), ";");
  }
  if (variable.onOffline) {
    obj.onOffline = appendIfNotEmpty(transformEx(variable.onOffline, scope, "event"), ";");
  }
  if (variable.onBeforeDatasetReady) {
    obj.onBeforeDatasetReady = appendIfNotEmpty(
      transformEx(variable.onBeforeDatasetReady, scope, "event"),
      ";"
    );
  }
  if (variable.spinnerContext) {
    obj.spinnerContext = variable.spinnerContext;
    obj.spinnerMessage = variable.spinnerMessage;
  }
  if (variable.category === "wm.LoginAction" || variable.category === "wm.LogoutAction") {
    obj.useDefaultSuccessHandler = variable.useDefaultSuccessHandler;
  }
  return obj;
}

function transformModelVariable(variable: any, scope: string) {
  if (
    isArray(variable.dataSet) &&
    variable.dataSet.length === 1 &&
    checkEmptyObject(variable.dataSet[0])
  ) {
    variable.dataSet = [];
  }
  // delete only when isList and keep single object modal variable
  if (variable.isList && variable.dataBinding) {
    delete variable.dataBinding;
  }
  const tv: any = transformVariable(variable, scope);
  tv.classname = "ModelVariable";
  tv.twoWayBinding = variable.twoWayBinding;
  tv.isList = !!variable.isList;
  return tv;
}

const capitalizeFirstLetter = (str: string) => {
  return str.charAt(0).toUpperCase() + str.slice(1);
};

/** Matches the singleton export name emitted by service.generator.ts for a given service class. */
const getServiceInstanceName = (className: string) =>
  className.charAt(0).toLowerCase() + className.slice(1);

/**
 * The name a generated `*.variables.ts` uses to refer to a service singleton.
 *
 * The singleton a service file exports is named after its own class (e.g. `departmentService` in
 * `services/hrdb/DepartmentService.ts`) — the folder, not the name, says which backend service it
 * belongs to. But one generated variables file can import singletons from SEVERAL services at
 * once, and two services that share an entity name (an "Employee" in both hrdb and salesdb) would
 * then export identically-named singletons. So the local name is qualified with the owning
 * service id (`hrdbEmployeeService` / `salesdbEmployeeService`) and the import is aliased to it
 * (see templates/variables.template) — keeping the generated file's own export clean while every
 * import site stays unambiguous.
 */
function getServiceLocalName(serviceId: string | undefined, className: string): string {
  const instanceName = getServiceInstanceName(className);
  if (!serviceId) {
    return instanceName;
  }
  const prefix = toPascalCase(serviceId);
  const core = prefix.endsWith("Service") ? prefix.slice(0, -"Service".length) : prefix;
  // Already service-named (e.g. class SecurityService in service securityService) — the
  // qualified form would just double the word.
  if (className.startsWith(core)) {
    return instanceName;
  }
  return getServiceInstanceName(`${core}${className}`);
}

/**
 * Derives service class name from controller. Strip "Controller", separators, ensure PascalCase.
 * Matches generated API files (apiNameSuffix=Service).
 */
function getServiceClassName(prefix: string): string {
  if (!prefix || typeof prefix !== "string") return "Service";
  // Strip separators including underscore — OpenAPI generator also removes underscores
  // from tag names when computing class names (e.g. "Master_LOV" → "MasterLOV")
  const base = prefix.replace(/[\s/\\\-_]+/g, "").trim();
  if (!base) return "Service";
  let basePascal = capitalizeFirstLetter(base);
  if (basePascal.endsWith("Controller")) {
    basePascal = basePascal.slice(0, -"Controller".length);
  }
  if (!basePascal) return "Service";
  return basePascal.endsWith("Service") ? basePascal : basePascal + "Service";
}

/**
 * Some operationIds are free text with spaces or other separators
 * (e.g. "update Product Offer category", "create/update bulk rules") instead
 * of a valid identifier. camelCase them to match the generated API method name
 * (e.g. "updateProductOfferCategory"). Mirrors toCamelCaseIdentifier in
 * scripts/swagger-builder.js, which sanitizes the same values before codegen.
 */
function toCamelCaseIdentifier(name: string): string {
  if (typeof name !== "string" || !/[^a-zA-Z0-9]/.test(name)) return name;
  const words = name.split(/[^a-zA-Z0-9]+/).filter(Boolean);
  if (!words.length) return name;
  let result = words
    .map((word, i) => (i === 0 ? word : word.charAt(0).toUpperCase() + word.slice(1)))
    .join("");
  if (/^[0-9]/.test(result)) result = "_" + result;
  return result;
}

/**
 * Mirrors doc-normalizer.ts's hasMultipleDistinctTags()-gated OpenAPIService behavior: a
 * connector whose spec never tagged operations meaningfully (every operation shares one tag,
 * often the generic placeholder "default") gets lumped into one class named after the service
 * itself; a connector with real distinct per-entity tags (e.g. "Department"/"Employee") splits
 * into one class per entity, same as any other service type. `variable.controller` already
 * carries that same signal here — WM sets it to the literal "default" placeholder for the
 * lumped case (mirroring the doc's own generic tag) and to the real entity name otherwise — so
 * this can be decided without needing the underlying designtime doc at variable-transform time.
 */
function resolveServiceTag(
  serviceId: string,
  controller: string | undefined,
  serviceType: string | undefined
): string {
  const isLumpedOpenApiService =
    serviceType === "OpenAPIService" && (!controller || controller.toLowerCase() === "default");
  const base = isLumpedOpenApiService
    ? serviceId.endsWith("Service")
      ? serviceId.slice(0, -"Service".length)
      : serviceId
    : controller || serviceId;
  // Real designtime tags (mirrored onto variable.controller) are often not valid identifiers
  // as-is (e.g. "Manage - Category", "Query - Entity Lock" — spaces and hyphens straight from a
  // human-authored Swagger tag). A bare capitalize-first-letter leaves those characters in
  // place, producing an invalid JS/TS class/instance name for invokeHttp to call into. Must use
  // the exact same toPascalCase() doc-normalizer.ts uses when it computes the SAME tag on the
  // generation side, or the two computations disagree on the class name.
  return base ? toPascalCase(base) : base;
}

/**
 * Returns serviceFile and invokeFnName for both ServiceVariable and LiveVariable.
 * - ServiceVariable: uses controller + operation (e.g. EmployeeService.countEmployees)
 * - LiveVariable: uses type + operation mapping (read→filterDepartments, create→createDepartment, etc.)
 */
function formatServiceDetails(
  variable: any
): { formattedServiceName: string; invokeFnName: string } | null {
  if (variable.operationId) {
    // Use variable.service as the authoritative service identifier so that service names
    // containing underscores (e.g. "Master_LOV") are handled correctly.
    // Fallback: split operationId on first "_" (legacy behaviour for variables without service field).
    const serviceName: string | undefined = variable.service;
    let prefix: string;
    let invokeFnName: string;

    if (serviceName) {
      prefix = serviceName;
      // Always rederive via the EXACT same deriveMethodName() doc-normalizer.ts uses on the
      // generation side, with the same candidates (service id, and the operation's own
      // controller/tag in both its raw "<Controller>Controller" and WM-cleaned forms) — this
      // can never drift from what was actually generated, unlike trusting variable.operation
      // (WM's own bare-action-name guess) or hand-rolling a narrower prefix-stripping rule here:
      // - JavaService/SoapService operationIds carry a "<Controller>_" tag layer that must be
      //   fully stripped (e.g. "GetLoggedInUserController_getUser" -> "getUser").
      // - OpenAPIService operationIds can carry BOTH a service-id AND controller/tag layer that
      //   must both be stripped (e.g. "hrdbSwagger_DepartmentController_getDepartment" ->
      //   "getDepartment").
      // - RestService single-operation connectors bake the service's own id in as their tag —
      //   deriveMethodName() only collapses a DOUBLED prefix to one copy rather than stripping
      //   it away (e.g. "swagger_swagger_invoke" -> "swaggerInvoke"), so two different
      //   connectors don't collide on one generic action name; a genuinely single-prefixed one
      //   (e.g. "CreateContractSpecification_invoke") still strips fully, to "invoke".
      const controllerRaw = variable.controller ? `${variable.controller}Controller` : undefined;
      const prefixCandidates = [serviceName, variable.controller, controllerRaw].filter(
        Boolean
      ) as string[];
      invokeFnName = deriveMethodName(variable.operationId, prefixCandidates);
    } else {
      const sepIdx = variable.operationId.indexOf("_");
      prefix = sepIdx >= 0 ? variable.operationId.substring(0, sepIdx) : variable.operationId;
      invokeFnName =
        sepIdx >= 0 ? variable.operationId.substring(sepIdx + 1) : variable.operationId;
    }

    // Some operationIds are free text with spaces or other separators
    // (e.g. "update Product Offer category", "create/update bulk rules"),
    // which isn't a valid JS identifier as-is. The generated API method name
    // camelCases these (e.g. "updateProductOfferCategory"), so do the same
    // here to keep the invoked method name in sync.
    invokeFnName = toCamelCaseIdentifier(invokeFnName);

    // variable.service is the backend service id (e.g. "hrdb", "hrdbSwagger") — the same value
    // service.generator.ts's collected.serviceName carries. Prefer the (service, controller)
    // pair when available (reliable, WM-Studio-provided, and required so two different backend
    // services sharing a controller/entity name don't collide on one class) — fall back to the
    // legacy operationId-derived `prefix` only for older variables with no `service` field.
    const formattedServiceName = variable.service
      ? buildServiceClassName(
          variable.service,
          resolveServiceTag(variable.service, variable.controller, variable.serviceType)
        )
      : getServiceClassName(prefix);

    return {
      formattedServiceName,
      invokeFnName,
    };
  }

  // LiveVariable: has type and operation, maps to API function names
  if (variable.type && variable.operation) {
    const entity = variable.type;
    // Normalize to singular first (entity may arrive as singular or plural from WaveMaker).
    // Then re-pluralize for read so the method name is always the correct plural form.
    // e.g. "Employee" → singular="Employee" → plural="Employees" → filterEmployees
    // e.g. "Addresses" → singular="Address" → plural="Addresses" → filterAddresses
    const singular = simpleSingularize(entity);
    const plural = simplePluralize(singular);
    const operationMap: Record<string, string> = {
      read: `filter${plural}`,
      insert: `create${singular}`,
      update: `edit${singular}`,
      delete: `delete${singular}`,
    };
    const invokeFnName = operationMap[variable.operation];
    if (!invokeFnName) return null;

    // variable.liveSource is the owning DataService's id (e.g. "hrdb", "salesdb") — same
    // rationale as ServiceVariable above: prefix so two DataServices sharing an entity name
    // (e.g. both have "Employee") don't collide on one generated class.
    const formattedServiceName = variable.liveSource
      ? buildServiceClassName(variable.liveSource, capitalizeFirstLetter(entity))
      : capitalizeFirstLetter(entity + "Service");

    return {
      formattedServiceName,
      invokeFnName,
    };
  }

  return null;
}

/**
 * A variable's backing service is only real if its OWN service id actually generated it.
 *
 * validServiceClassNames is a flat, service-id-blind set of bare class names (see
 * app.generator.ts's getValidServiceClassNames — it walks all of services/ and regexes out
 * `export class X`, dropping which folder/service id each class came from). Two different
 * services can generate the identically-named class — buildServiceClassName("hrdb", "User") and
 * buildServiceClassName("hrdbSwagger", "User") both produce "UserService" — so
 * `validServiceClassNames.has("UserService")` says nothing about whether THIS variable's own
 * service id is the one that generated it. A variable naming the wrong service id (e.g. a
 * LiveVariable's liveSource that doesn't match any actually-generated service, but collides by
 * class name with one that does) would otherwise slip past this check.
 *
 * servicePathByOperation's keys are `${serviceId}::${operation}` — already scoped by the real
 * service id — so prefer asking "did THIS service id generate anything at all" when it's
 * available, falling back to the old class-name check only where it isn't (direct unit tests).
 */
function isServiceAvailable(
  serviceId: string | undefined,
  className: string | undefined,
  validServiceClassNames?: Set<string>,
  servicePathByOperation?: Map<string, string>
) {
  if (servicePathByOperation && serviceId) {
    const prefix = `${serviceId}::`;
    for (const key of servicePathByOperation.keys()) {
      if (key.startsWith(prefix)) {
        return true;
      }
    }
    return false;
  }
  return !validServiceClassNames || !className || validServiceClassNames.has(className);
}

/**
 * The key an argument's value actually arrives under in the params object the runtime hands
 * `invokeHttp`.
 *
 * For a ServiceVariable that's the swagger parameter's own name — `inputFields` is keyed by
 * exactly those. A LiveVariable never populates `inputFields` with its DB operation's fields:
 * LiveVariableManager builds its own `dbOperationOptions` and that object is what reaches
 * `invokeHttp`, keyed by the runtime's OWN names (see VARIABLE_URLS.DATABASE in
 * @wavemaker-ai/variables' variables.constants.ts and getEntityData()'s dbOperationOptions):
 *   - `page` / `size` / `sort` — same names, handled by the pageable branch above.
 *   - `data` — the request payload. For a filter/search read this is the query fragment the
 *     manager pre-builds as `"q=<query>"` (posted form-urlencoded, matching the backend's
 *     `consumes = "application/x-www-form-urlencoded"`); for insert/update it's the entity.
 *     Either way it is NEVER keyed by the swagger name (`q`, or the entity name for a body), so
 *     reading the swagger name here would silently always yield `undefined` — dropping every
 *     filter on a LiveVariable read.
 *   - `id` — the primary key for update/delete by id.
 */
/**
 * The expression the invokeHttp glue uses to source one positional argument from the runtime's
 * flat `params` object. `page`/`size`/`sort` collapse into one `Pageable` literal; everything else
 * reads its key. Values pass through as they arrive — base.service.ts's serializers strip any
 * `<name>=` prefix @wavemaker-ai/variables baked in, since they already hold the wire name.
 */
function callArgExpression(
  arg: MethodArg,
  isLiveVariable: boolean,
  isBodyTypeQueryOrProcedure = false
): string {
  // A query/procedure variable (controller QueryExecution|ProcedureExecution + post|put) does not
  // put its body under the swagger param's name: ServiceVariableUtils calls processRequestBody(),
  // which assembles the body from that param's CHILD fields — so inputFields is FLAT
  // ({USERNAME, PASSWORD, ...}) with no `CreateUserRequest` key. Reading the swagger name there
  // yields undefined and the request goes out with no body.
  if (isBodyTypeQueryOrProcedure && arg.source.kind === "body") {
    return "params";
  }
  if (arg.source.kind === "pageable") {
    const props = arg.source.paramNames
      .map(wireName => {
        const prop = wireName === "sort" ? "sort" : wireName === "size" ? "pageSize" : "pageNumber";
        return `${prop}: params?.[${JSON.stringify(wireName)}]`;
      })
      .join(", ");
    return `{ ${props} }`;
  }
  return `params?.[${JSON.stringify(liveVariableParamKey(arg, isLiveVariable))}]`;
}

/**
 * Sets the fields templates/variables.template's `invokeHttp` glue needs to call a generated
 * service method whose signature mirrors the backend operation's own declared parameters (see
 * src/services/method-emitter.ts): one positional argument per parameter, in declared order.
 *
 * `tv.callArgs` is a list of ready-to-emit JS expressions, each sourcing one argument from the
 * flat params object the WM runtime hands `invokeHttp` — including reconstructing the single
 * `pageable` object the backend binds page/size/sort into. `tv.serviceImportPath` is where the
 * owning singleton lives, now that each service has its own folder and a class name alone no
 * longer determines its path.
 *
 * Both come from the tables the generator itself wrote while emitting these exact methods, so a
 * call site can never name an argument the generated method doesn't have. When the lookup isn't
 * available (service generation didn't run — e.g. direct unit tests) `callArgs` stays undefined
 * and the template falls back to passing the params object straight through.
 */
function applyServiceCallShape(
  tv: any,
  lookupKey: string,
  methodArgsByOperation?: Map<string, MethodArg[]>,
  servicePathByOperation?: Map<string, string>,
  isLiveVariable = false,
  isBodyTypeQueryOrProcedure = false
) {
  const importPath = servicePathByOperation?.get(lookupKey);
  if (importPath) {
    tv.serviceImportPath = importPath;
    // The path comes from the generator itself, so it is authoritative about WHICH class owns this
    // operation — more so than the variable's own `controller`, which can be stale (a real case:
    // a variable claims `controller: "Manage - Category"` for an operation the designtime doc
    // actually tags "Manage - Product Offer Group Category"). Re-derive the class and its exported
    // singleton from the resolved path so the import names always match the file being imported;
    // otherwise we emit `import { manageCategoryService } from '.../ManageProductOfferGroupCategoryService'`
    // — a module that has no such export.
    const resolvedClassName = importPath.split("/").pop();
    if (resolvedClassName && resolvedClassName !== tv.serviceFileClass) {
      tv.serviceFile = resolvedClassName;
      tv.serviceFileClass = resolvedClassName;
      tv.serviceExportName = getServiceInstanceName(resolvedClassName);
      tv.serviceInstanceName = getServiceLocalName(tv.service ?? tv.liveSource, resolvedClassName);
    }
  }
  const args = methodArgsByOperation?.get(lookupKey);
  if (!args) {
    return;
  }
  // Handlebars treats an EMPTY array as falsy, so `{{#if callArgs}}` cannot distinguish "this
  // operation takes no arguments" from "no lookup was available". A zero-arg method (e.g.
  // `sample(ctx?)`) then fell through to the `(params, ctx)` fallback and was called with two
  // arguments — a compile error. This flag records that the args ARE known, whatever their count.
  tv.hasResolvedCallArgs = true;
  // page/size/sort arrive under those exact names for BOTH variable kinds — LiveVariable's
  // manager builds them into its dbOperationOptions, and a ServiceVariable's inputFields keys
  // them by the swagger param names, which are also page/size/sort.
  tv.callArgs = args.map(arg => callArgExpression(arg, isLiveVariable, isBodyTypeQueryOrProcedure));
}
function liveVariableParamKey(arg: MethodArg, isLiveVariable: boolean): string {
  const swaggerName = (arg.source as { paramName: string }).paramName;
  if (!isLiveVariable) {
    return swaggerName;
  }
  switch (arg.source.kind) {
    case "query":
      // The only query param a LiveVariable operation declares besides the pageable trio is the
      // filter query (`q`), which the manager delivers in `data`, already "q="-prefixed and
      // unwrapped back to a bare value by the runtime's normalizeInvokeHttpParams().
      return swaggerName === "q" ? "data" : swaggerName;
    case "body":
    case "formData":
      return "data";
    case "path":
      // A LiveVariable's by-id operations receive the key as `id`, whatever the entity calls its
      // primary key column (deptId, empId, ...).
      return "id";
    default:
      return swaggerName;
  }
}

function transformServiceVariable(
  variable: any,
  scope: string,
  validServiceClassNames?: Set<string>,
  methodArgsByOperation?: Map<string, MethodArg[]>,
  methodNameByOperation?: Map<string, string>,
  servicePathByOperation?: Map<string, string>
) {
  // A variable whose service was never generated (no swagger definition, service removed, ...)
  // is still emitted — just without an invokeHttp. useHttp's send() falls back to its own axios
  // instance when `variable.invokeHttp == undefined`, so the call still goes out the pre-codegen
  // way instead of the variable disappearing from the page.
  const serviceDetails = formatServiceDetails(variable);
  let skipInvokeHttp = false;
  if (
    !isServiceAvailable(
      variable.service,
      serviceDetails?.formattedServiceName,
      validServiceClassNames,
      servicePathByOperation
    )
  ) {
    console.warn(
      `ServiceVariable "${variable.name}" references service "${variable.service}" ` +
        `(${serviceDetails?.formattedServiceName}), which was not generated. Emitting the ` +
        `variable without an invokeHttp — the runtime falls back to its own transport.`
    );
    skipInvokeHttp = true;
  }
  // The service CLASS existing isn't enough — the specific OPERATION must exist too. A project's
  // variable JSON can name an operationId the designtime doc no longer exposes (a real case: a
  // variable kept an operationId for an endpoint since removed from the backend, while its
  // service and controller are still perfectly valid). Generating for it produced a call to a
  // method that doesn't exist AND, because the per-operation lookup missed, an import path with
  // the service folder blank (`@/services//XService`) — a build break rather than a clear signal.
  // When the lookup tables are available (they aren't in direct unit tests) and this operation
  // isn't in them, treat it exactly like a missing service and skip the variable.
  const operationKey = `${variable.service}::${variable.operationId}`;
  if (servicePathByOperation && !servicePathByOperation.has(operationKey)) {
    console.warn(
      `ServiceVariable "${variable.name}" references operation "${variable.operationId}" on ` +
        `service "${variable.service}", which has no such operation. Emitting the variable ` +
        `without an invokeHttp — the runtime falls back to its own transport.`
    );
    skipInvokeHttp = true;
  }
  const tv: any = transformVariable(variable, scope);
  tv.classname = "ServiceVariable";
  // Gates the service import AND the invokeHttp block in the template: with no
  // generated method to call, emitting either would not compile.
  tv.hasInvokeHttp = !skipInvokeHttp;
  tv.operationId = variable.operationId;
  tv.isList = !!variable.isList;
  tv.inFlightBehavior = variable.inFlightBehavior;
  tv.service = variable.service;
  tv.operation = variable.operation;
  tv.operationType = variable.operationType;
  tv.maxResults = variable.maxResults;
  tv._context = variable._context;
  tv.serviceType = variable.serviceType;
  tv.controller = variable.controller;
  tv.autoUpdate = variable.autoUpdate;
  tv.orderBy = variable.orderBy;
  tv.isStaticParams = isStaticParamsVariable(variable);
  // No bind: expression in dataBinding — nothing for paramProvider to evaluate, so the static
  // { target: value } object moves to dataBinding instead.
  if (
    isArray(variable.dataBinding) &&
    variable.dataBinding.length &&
    variable.dataBinding.every((d: any) => bindingValueIsStatic(d.value))
  ) {
    tv.dataBinding = stringify(tv.params);
    tv.params = {};
  }
  tv.serviceFile = serviceDetails?.formattedServiceName;
  tv.serviceFileClass = serviceDetails?.formattedServiceName;
  // `serviceInstanceName` is the name used at the call site (and aliased to on import);
  // `serviceExportName` is what the service file actually exports.
  tv.serviceExportName =
    serviceDetails && getServiceInstanceName(serviceDetails.formattedServiceName);
  tv.serviceInstanceName =
    serviceDetails && getServiceLocalName(variable.service, serviceDetails.formattedServiceName);
  // Prefer the actual generated method name (looked up by the exact same key
  // service.generator.ts built it with) over re-deriving it from variable.operationId via
  // formatServiceDetails/deriveMethodName: WM doesn't always record a variable's operationId as
  // the designtime doc's raw operationId verbatim (see NormalizedOperation.operationIdAliases),
  // so blindly re-running the same stripping rules on a shorter/differently-prefixed alias can
  // land on a name the generated class doesn't actually have (e.g. a doc-side "doubled prefix"
  // operationId that collapses to "fooBar" on the generation side, but whose variable-side alias
  // has only one prefix layer and over-strips down to bare "bar"). Falls back to the re-derived
  // name only when the lookup can't help (service generation didn't run, e.g. direct unit tests).
  const lookupKey = `${variable.service}::${variable.operationId}`;
  tv.invokeFnName = methodNameByOperation?.get(lookupKey) ?? serviceDetails?.invokeFnName;
  // Mirrors ServiceVariableUtils' isBodyTypeQueryOrProcedure: a query/procedure variable's body
  // is assembled from the body param's child fields, so its params object is flat.
  const isBodyTypeQueryOrProcedure =
    ["QueryExecution", "ProcedureExecution"].includes(variable.controller) &&
    ["put", "post"].includes(variable.operationType);
  applyServiceCallShape(
    tv,
    lookupKey,
    methodArgsByOperation,
    servicePathByOperation,
    false,
    isBodyTypeQueryOrProcedure
  );
  return tv;
}

function transformNavigationAction(variable: any, scope: string) {
  const tv: any = transformVariable(variable, scope);
  tv.classname = "NavigationAction";
  tv.group = "action";
  tv.operation = variable.operation;
  tv.params = isArray(tv.params) && tv.params.length == 0 ? {} : tv.params;
  if (!tv.params["pageName"] && variable.pageName) {
    tv.params["pageName"] = variable.pageName;
  }
  return tv;
}

function transformTimerAction(variable: any, scope: string) {
  const tv: any = transformVariable(variable, scope);
  tv.classname = "TimerAction";
  tv.group = "action";
  tv.repeating = variable.repeating;
  tv.delay = variable.delay;
  if (variable.onTimerFire) {
    tv.onTimerFire = appendIfNotEmpty(transformEx(variable.onTimerFire, scope, "event"), ";");
  }
  return tv;
}

function transformNotificationAction(variable: any, scope: string, imports: string[]) {
  const tv: any = transformVariable(variable, scope);
  tv.classname = "NotificationAction";
  tv.group = "action";
  tv.operation = variable.operation;
  const bindings = Array.isArray(variable.dataBinding) ? variable.dataBinding : [];
  const getBinding = (target: string) => bindings.find((b: any) => b.target === target);
  const contentBinding = getBinding("content");
  const rendersPartial = contentBinding
    ? contentBinding.value === "page"
    : variable.operation !== "toast";
  const partialContent = rendersPartial ? getBinding("page") : null;
  if (variable.onOk || variable.onClick) {
    tv.onOk = appendIfNotEmpty(transformEx(variable.onOk || variable.onClick, scope, "event"), ";");
  }
  if (variable.onCancel) {
    tv.onCancel = appendIfNotEmpty(transformEx(variable.onCancel, scope, "event"), ";");
  }
  if (variable.onClose || variable.onHide) {
    tv.onClose = appendIfNotEmpty(
      transformEx(variable.onClose || variable.onHide, scope, "event"),
      ";"
    );
  }
  if (variable.operation === "alert" || variable.operation === "confirm") {
    const owner = scope === "App" ? "App" : scope;
    const widgetName = `Common${upperFirst(variable.operation)}Dialog`;
    if (owner === "App") {
      tv.showDialog = `App.openActionDialog(options,"${widgetName}");`;
    } else {
      tv.showDialog = `${owner}.App.openActionDialog(options,"${widgetName}");`;
    }
  }
  if (partialContent) {
    const partialName =
      partialContent.value.charAt(0).toUpperCase() + partialContent.value.slice(1);
    const importItem = `import ${partialName} from "@/app/components/${partialContent.value}/${partialContent.value}";`;
    if (!imports.includes(importItem)) {
      imports.push(importItem);
    }

    tv.partialContent = { component: partialName };
  }

  return tv;
}

function transformDeviceVariable(variable: any, scope: string, appUrl?: string) {
  if (
    isArray(variable.dataSet) &&
    variable.dataSet.length === 1 &&
    checkEmptyObject(variable.dataSet[0])
  ) {
    variable.dataSet = [];
  }
  const tv: any = transformVariable(variable, scope);
  tv.classname = "DeviceVariable";
  tv.operation = variable.operation;
  tv.service = variable.service;
  if (variable.service === "file") {
    tv.params.serverUrl = `${scope}.eval(() => ${scope}.appConfig.url)`;
  }
  return tv;
}

function transformLoginVariable(variable: any, scope: any) {
  const tv: any = transformVariable(variable, scope);
  tv.classname = "LoginAction";
  tv.group = "action";
  return tv;
}

function transformLogoutVariable(variable: any, scope: any) {
  const tv: any = transformVariable(variable, scope);
  tv.classname = "LogoutAction";
  tv.group = "action";
  tv.redirectTo = variable.redirectTo;
  return tv;
}

/**
 * The `${serviceName}::${operationIdAlias}` key of the operation whose GENERATED method is named
 * `methodName` on service `serviceName`. LiveVariables identify their operation by that derived
 * method name rather than by a doc operationId (they have none), so this reverses the
 * methodNameByOperation table to reach the other per-operation lookups keyed the same way.
 */
function findOperationKeyByMethodName(
  serviceName: string | undefined,
  methodName: string | undefined,
  methodNameByOperation?: Map<string, string>
): string | undefined {
  if (!serviceName || !methodName || !methodNameByOperation) {
    return undefined;
  }
  const prefix = `${serviceName}::`;
  for (const [key, name] of methodNameByOperation) {
    if (name === methodName && key.startsWith(prefix)) {
      return key;
    }
  }
  return undefined;
}

/**
 * Fallback for when findOperationKeyByMethodName's guessed name (built via
 * simpleSingularize/simplePluralize) doesn't match anything real: those are an English-stemming
 * HEURISTIC, and WM entity names aren't always actual English plurals to begin with — an entity
 * literally named "AllTypes" has no distinct singular in WM's own generated methods at all
 * (`findAllTypes`, `createAllTypes`, `filterAllTypes`, `deleteAllTypes` all keep "AllTypes"
 * unchanged), so the stemmer's round-trip ("AllTypes" -> "AllTyp" -> "AllTyps") produces a name
 * nothing was ever generated as, and the reverse lookup silently misses.
 *
 * WM's own raw operationId for a Data Service entity operation is always
 * `<entity>Controller_<verb><NameVariant>` — the verb always comes right after the tag,
 * regardless of what spelling variant WM chose for NameVariant. Searching by that verb prefix
 * against the RAW (un-derived) key finds the real operation without having to guess the spelling
 * variant at all. Among ties (e.g. an association method like `findAssociatedEmployees` also
 * starting with "find"), the shortest key wins — the plain CRUD operation, not one with an extra
 * qualifier tacked on.
 */
function findLiveOperationKeyByVerb(
  liveSource: string | undefined,
  entity: string | undefined,
  verbTokens: string[],
  methodNameByOperation?: Map<string, string>
): string | undefined {
  if (!liveSource || !entity || !methodNameByOperation) {
    return undefined;
  }
  const tagPrefix = `${liveSource}::${entity}Controller_`;
  let best: string | undefined;
  for (const key of methodNameByOperation.keys()) {
    if (!key.startsWith(tagPrefix)) continue;
    const verbAndName = key.slice(tagPrefix.length);
    if (!verbTokens.some(verb => verbAndName.startsWith(verb))) continue;
    if (!best || key.length < best.length) {
      best = key;
    }
  }
  return best;
}

/** WM's own verb token for each DataService action — the literal prefix its raw operationId's tail (after `<Entity>Controller_`) always starts with, independent of the entity's own singular/plural spelling. */
const LIVE_OPERATION_VERBS: Record<string, string[]> = {
  readTableData: ["find"],
  searchTableDataWithQuery: ["filter"],
  searchTableData: ["search"],
  insertTableData: ["create"],
  updateTableData: ["edit"],
  deleteTableData: ["delete"],
};

/** Which DataService action formatServiceDetails' operationMap maps each `variable.operation` value to — mirrors that map's own verb choice (read -> filter/searchTableDataWithQuery, not find/readTableData) so the fallback resolves the SAME operation the guessed name was aiming for. */
const LIVE_DEFAULT_ACTION_BY_OPERATION: Record<string, string> = {
  read: "searchTableDataWithQuery",
  insert: "insertTableData",
  update: "updateTableData",
  delete: "deleteTableData",
};

function transformLiveVariable(
  variable: any,
  scope: any,
  validServiceClassNames?: Set<string>,
  methodArgsByOperation?: Map<string, MethodArg[]>,
  methodNameByOperation?: Map<string, string>,
  servicePathByOperation?: Map<string, string>
) {
  const serviceDetails = formatServiceDetails(variable);
  let skipInvokeHttp = false;
  if (
    serviceDetails &&
    !isServiceAvailable(
      variable.liveSource,
      serviceDetails.formattedServiceName,
      validServiceClassNames,
      servicePathByOperation
    )
  ) {
    console.warn(
      `LiveVariable "${variable.name}" targets entity "${variable.type}" on liveSource ` +
        `"${variable.liveSource}" (${serviceDetails.formattedServiceName}), which was not ` +
        `generated. Emitting the variable without an invokeHttp — the runtime falls back to its ` +
        `own transport.`
    );
    skipInvokeHttp = true;
  }
  const tv: any = transformVariable(variable, scope);
  tv.classname = "LiveVariable";
  // Gates the service import AND the invokeHttp block in the template: with no
  // generated method to call, emitting either would not compile.
  tv.hasInvokeHttp = !skipInvokeHttp;
  tv.isList = !!variable.isList;
  tv.inFlightBehavior = variable.inFlightBehavior;
  tv.maxResults = variable.maxResults;
  tv._context = variable._context;
  tv.operation = variable.operation;
  tv.type = variable.type;
  tv.autoUpdate = variable.autoUpdate;
  tv.orderBy = variable.orderBy;
  tv.liveSource = variable.liveSource;
  tv.category = variable.category;
  tv.tableName = variable.tableName;
  tv.tableType = variable.tableType;
  tv.relatedTables = variable.relatedTables;
  tv.filterExpressions = variable.filterExpressions;
  tv._id = variable._id;
  tv.isStaticParams = isStaticParamsVariable(variable);
  if (serviceDetails) {
    tv.serviceFile = serviceDetails.formattedServiceName;
    tv.serviceFileClass = serviceDetails.formattedServiceName;
    tv.serviceExportName = getServiceInstanceName(serviceDetails.formattedServiceName);
    tv.serviceInstanceName = getServiceLocalName(
      variable.liveSource,
      serviceDetails.formattedServiceName
    );
    tv.invokeFnName = serviceDetails.invokeFnName;
    // A LiveVariable has no raw `operationId` to key the sidecar lookups with — its method name
    // is derived from its operation instead (read -> filterDepartments, insert ->
    // createDepartment, ...). Resolve the same tables by that derived METHOD NAME, which the
    // generator also indexes (see findOperationKeyByMethodName), so a LiveVariable's generated
    // call gets the same correct positional arguments a ServiceVariable's does.
    let lookupKey = findOperationKeyByMethodName(
      variable.liveSource,
      serviceDetails.invokeFnName,
      methodNameByOperation
    );
    // The guessed name above is an English-stemming heuristic and can miss for entity names that
    // aren't real English plurals (see findLiveOperationKeyByVerb) — fall back to a verb-prefix
    // search against the raw operationId, which needs no such guess.
    if (!lookupKey) {
      lookupKey = findLiveOperationKeyByVerb(
        variable.liveSource,
        variable.type,
        LIVE_OPERATION_VERBS[LIVE_DEFAULT_ACTION_BY_OPERATION[variable.operation]] ?? [],
        methodNameByOperation
      );
    }
    if (lookupKey) {
      // The fallback resolves the operation independently of the guessed name, so the guess
      // itself may still be wrong — realign tv.invokeFnName to the actual generated method name
      // rather than leaving the mismatched guess in place (this is the value applyServiceCallShape
      // uses at the top level when liveTargets ends up empty and the template falls back to it).
      tv.invokeFnName = methodNameByOperation?.get(lookupKey) ?? tv.invokeFnName;
      applyServiceCallShape(
        tv,
        lookupKey,
        methodArgsByOperation,
        servicePathByOperation,
        true // LiveVariable — its params object is keyed by the runtime's own DB-operation names
      );
    }
    // `variable.operation` is only the DEFAULT operation — the one `.invoke()` runs. Every
    // LiveVariable carries all four record methods (see live-variable.ts's DataSource.Operation
    // switch), and a table bound to it as `datasource` calls insert/update/delete on THAT
    // variable, not on some other one. Emitting only the default meant a grid edit on a
    // `read` variable ran filterX with the row data. So resolve all four and let the glue
    // dispatch on the DB operation the manager passes in `params.operation`.
    tv.liveTargets = buildLiveTargets(
      variable,
      methodArgsByOperation,
      methodNameByOperation,
      servicePathByOperation
    );
  }
  return tv;
}

/**
 * A LiveVariable's invokeHttp targets, one per DB operation the runtime can ask it for.
 *
 * Keyed by the manager's own action names (`params.operation`, set in
 * live-variable.manager.ts). Only the operations whose method actually generated are included, so
 * a service missing (say) a delete endpoint simply has no `delete` case rather than a call to a
 * method that does not exist.
 */
function buildLiveTargets(
  variable: any,
  methodArgsByOperation?: Map<string, MethodArg[]>,
  methodNameByOperation?: Map<string, string>,
  servicePathByOperation?: Map<string, string>
) {
  const entity = variable.type;
  if (!entity) {
    return undefined;
  }
  const singular = simpleSingularize(entity);
  const plural = simplePluralize(singular);
  // The manager's action -> the generated method for it. Each action is a DISTINCT backend
  // endpoint with its own body shape, so they cannot share one method:
  //   readTableData / searchTableDataWithQuery -> POST /<entity>/filter, body `q=<query string>`
  //   searchTableData          -> POST /<entity>/search, body a QueryFilter[] ARRAY
  // Collapsing any two of these sent the wrong body to the wrong route and silently matched
  // nothing.
  const byAction: [string, string][] = [
    // readTableData's template is `GET /<entity>?page=&size=&:sort` — the collection GET, which
    // the generator names find<Plural>. filter<Plural> is the POST /filter twin and belongs only
    // to the query-bearing actions.
    ["readTableData", `find${plural}`],
    ["searchTableDataWithQuery", `filter${plural}`],
    ["searchTableData", `search${plural}ByQueryFilters`],
    ["insertTableData", `create${singular}`],
    ["updateTableData", `edit${singular}`],
    ["deleteTableData", `delete${singular}`],
  ];

  // All four methods for one entity are emitted onto ONE class (the entity's own service), and a
  // LiveVariable is pinned to a single liveSource — so every target shares the variable's own
  // import and instance. Only the method name and its argument list differ per action.
  const targets: any[] = [];
  for (const [action, guessedMethodName] of byAction) {
    let lookupKey = findOperationKeyByMethodName(
      variable.liveSource,
      guessedMethodName,
      methodNameByOperation
    );
    // Same English-stemming-guess-can-miss situation as transformLiveVariable's default target
    // above — fall back to a verb-prefix search that needs no singular/plural guess at all.
    if (!lookupKey) {
      lookupKey = findLiveOperationKeyByVerb(
        variable.liveSource,
        entity,
        LIVE_OPERATION_VERBS[action] ?? [],
        methodNameByOperation
      );
    }
    if (!lookupKey || (servicePathByOperation && !servicePathByOperation.has(lookupKey))) {
      continue; // that operation was not generated for this entity
    }
    // The fallback resolves independently of the guess, so use the actual generated method name
    // (methodNameByOperation's own value for this key) rather than the possibly-wrong guess.
    const methodName = methodNameByOperation?.get(lookupKey) ?? guessedMethodName;
    const shape: any = {};
    applyServiceCallShape(shape, lookupKey, methodArgsByOperation, servicePathByOperation, true);
    targets.push({
      action,
      invokeFnName: methodName,
      callArgs: shape.callArgs ?? [],
      hasResolvedCallArgs: !!shape.hasResolvedCallArgs,
    });
  }
  return targets.length ? targets : undefined;
}

/**
 * A CrudVariable's invokeHttp targets, keyed by operationType.
 *
 * Unlike a ServiceVariable (one fixed operation), a CrudVariable names a GROUP whose member is
 * chosen per call, so the glue dispatches on the operation the runtime records for that call.
 * Each entry carries everything the call needs: the singleton to import, its local alias, the
 * method, and how to source each positional argument.
 */
function buildCrudTargets(
  variable: any,
  crudOperationsById?: Map<string, Record<string, CrudOperationTarget>>
) {
  const group = crudOperationsById?.get(variable.crudOperationId);
  if (!group) {
    return undefined;
  }
  const targets = Object.entries(group).map(([operationType, target]) => {
    const className = target.importPath.split("/").pop()!;
    return {
      operationType,
      importPath: target.importPath,
      serviceExportName: getServiceInstanceName(className),
      serviceInstanceName: getServiceLocalName(variable.service, className),
      invokeFnName: target.methodName,
      // A CrudVariable is never a LiveVariable, so params are keyed by the swagger names.
      callArgs: target.args.map(arg => callArgExpression(arg, false)),
    };
  });
  return targets.length ? targets : undefined;
}

function transformCrudVariable(
  variable: any,
  scope: string,
  crudOperationsById?: Map<string, Record<string, CrudOperationTarget>>
) {
  const tv: any = transformVariable(variable, scope);
  tv._id = variable._id;
  tv.name = variable.name;
  tv.owner = variable.owner;
  tv.category = variable.category;
  tv.type = variable.type;
  tv.service = variable.service;
  tv.operation = variable.operation;
  tv.operationId = variable.operationId;
  tv.crudOperationId = variable.crudOperationId;
  tv.operationType = variable.operationType;
  tv.serviceType = variable.serviceType;
  tv.dataSet = variable.dataSet;
  tv.isList = variable.isList;
  tv.maxResults = variable.maxResults;
  tv.startUpdate = variable.startUpdate;
  tv.autoUpdate = variable.autoUpdate;
  tv.inFlightBehavior = variable.inFlightBehavior;
  tv.transformationRequired = variable.transformationRequired;
  tv.saveInPhonegap = variable.saveInPhonegap;
  tv.controller = variable.controller;
  // Use transformed dataBinding if available, otherwise use original
  tv.dataBinding = variable._transformedDataBinding || variable.dataBinding;
  tv.classname = "CrudVariable";
  tv.group = "variable";
  tv.crudTargets = buildCrudTargets(variable, crudOperationsById);
  tv.isStaticParams = isStaticParamsVariable(variable);
  return tv;
}

export default (
  variable: any,
  scope: string,
  appUrl: string,
  imports: string[],
  validServiceClassNames?: Set<string>,
  methodArgsByOperation?: Map<string, MethodArg[]>,
  methodNameByOperation?: Map<string, string>,
  servicePathByOperation?: Map<string, string>,
  crudOperationsById?: Map<string, Record<string, CrudOperationTarget>>
) => {
  switch (variable.category) {
    case "wm.Variable":
      return transformModelVariable(variable, scope);
    case "wm.ServiceVariable":
      return transformServiceVariable(
        variable,
        scope,
        validServiceClassNames,
        methodArgsByOperation,
        methodNameByOperation,
        servicePathByOperation
      );
    case "wm.NavigationAction":
      return transformNavigationAction(variable, scope);
    case "wm.TimerAction":
      return transformTimerAction(variable, scope);
    case "wm.NotificationAction":
      return transformNotificationAction(variable, scope, imports);
    case "wm.DeviceVariable":
      return transformDeviceVariable(variable, scope, appUrl);
    case "wm.LoginAction":
      return transformLoginVariable(variable, scope);
    case "wm.LogoutAction":
      return transformLogoutVariable(variable, scope);
    case "wm.LiveVariable":
      return transformLiveVariable(
        variable,
        scope,
        validServiceClassNames,
        methodArgsByOperation,
        methodNameByOperation,
        servicePathByOperation
      );
    case "wm.CrudVariable":
      return transformCrudVariable(variable, scope, crudOperationsById);
  }
  return null;
};
