import { HTMLElement } from "node-html-parser";

import {
  Import,
  isHTMLElement,
  Transformer,
  TranspilationContext,
  transformAttrs,
} from "../../transpile";
import { FRAGMENT_SCOPED_NAMES } from "../../bind.ex.transformer";

export const imports: Import[] = [
  {
    name: "WmNav",
    from: "@wavemaker-ai/react-runtime/components/navbar/nav",
  },
];

const createNavItemLabelExpression = (element: HTMLElement): string | undefined => {
  let itemlabel = element.getAttribute("itemlabel");

  if (!itemlabel) {
    return undefined;
  }

  let expression: string;

  // Check if it's a bind expression
  if (itemlabel.startsWith("bind:")) {
    // Remove the "bind:" prefix
    expression = itemlabel.substring(5);

    // Replace fragment.<name> with item.<name> wherever it appears in the
    expression = expression.replace(/fragment\.([a-zA-Z_$][a-zA-Z0-9_$]*)/g, (match, name) =>
      FRAGMENT_SCOPED_NAMES.includes(name) ? match : `item.${name}`
    );
  } else {
    // Plain string value - convert to item[string]
    expression = `item.${itemlabel}`;
  }

  // Return the arrow function expression with TypeScript type annotation
  return `{(item: any) => (${expression})}`;
};

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const layout = element.getAttribute("layout");
    if (layout) {
      const className = layout === "stacked" ? "stackedNav " : "justifiedNav ";
      if (layout === "stacked") {
        element.setAttribute("class", className + (element.getAttribute("class") || ""));
      } else {
        element.setAttribute("class", className + (element.getAttribute("class") || ""));
      }
    }

    if (!element.hasAttribute("dataset")) {
      element.childNodes.forEach(n => {
        if (isHTMLElement(n) && n.tagName === "WM-NAV-ITEM") {
          n.setAttribute("defaultview", "true");
        }
      });
    }

    let itemlabelExpression;
    const itemlabel = element.getAttribute("itemlabel");
    if (itemlabel) {
      itemlabelExpression = createNavItemLabelExpression(element);
      if (itemlabelExpression) {
        element.removeAttribute("itemlabel");
      }
    }

    return `<WmNav 
    listener={fragment}
      ${transformAttrs(element, context)}
      ${itemlabelExpression ? `itemlabel=${itemlabelExpression}` : ""}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "</WmNav>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
