import { HTMLElement } from "node-html-parser";

import { Import, Transformer, TranspilationContext } from "../../transpile";
import { buildPartialMarkup } from "./build-partial-markup";

export const imports: Import[] = [
  {
    name: "WmPartialContainer",
    from: "@wavemaker-ai/react-runtime/components/page/partial-container",
  },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) =>
    buildPartialMarkup(element, context, "WmPartialContainer"),
  post: (element: HTMLElement, context: TranspilationContext) => "",
  imports: (element: HTMLElement, context: TranspilationContext) =>
    element.hasAttribute("content") ? imports : [],
} as Transformer;
