import { HTMLElement } from "node-html-parser";

import { Import, transformAttrs, Transformer, TranspilationContext } from "../../transpile";

export const imports: Import[] = [
  {
    name: "WmFileupload",
    from: "@wavemaker-ai/react-runtime/components/input/fileupload",
  },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const isFormField = element.getAttribute("formfield") === "true";

    if (element.getAttribute("on-select")) {
      const datasource = element.getAttribute("on-select")?.split(".invoke")[0];
      if (datasource && datasource.includes("Variables")) {
        element.setAttribute("datasource", datasource.replace(/[;,]+\s*$/, "").replace(/\?$/, ""));
      }
    }

    if (element.getAttribute("on-delete")) {
      const deletedatasource = element.getAttribute("on-delete")?.split(".invoke")[0];
      if (deletedatasource && deletedatasource.includes("Variables")) {
        element.setAttribute(
          "deletedatasource",
          deletedatasource.replace(/[;,]+\s*$/, "").replace(/\?$/, "")
        );
      }
    }

    return `<WmFileupload ${isFormField ? " {...$formField}" : ""} listener={fragment}  ${transformAttrs(element, context)}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "</WmFileupload>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
