import { fromUnicode } from "../components/utils";
import { StyleParser } from "./style.parser";

export class BackgroundImageParser extends StyleParser {
  constructor() {
    super("backgroundImage");
  }

  parse(url: string): any {
    if (url) {
      url = fromUnicode(url);
    }
    const style = {} as any;
    style[this.styleName] = url ? `url(${fromUnicode(url)})` : `url(${url})`;
    return style;
  }
}
