import { Import, Transformer, TranspilationContext, transformAttrs } from "../../transpile";
import { HTMLElement } from "node-html-parser";
import { withPartialContainer, getPartialImports } from "../page/with-partial-container";

export const imports: Import[] = [
  {
    name: "WmPanel, {WmPanelFooter}",
    from: "@wavemaker-ai/react-runtime/components/container/panel",
  },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const { partialAttr } = withPartialContainer(element, context, { prop: "renderPartial" });
    return `<WmPanel listener={fragment}  ${transformAttrs(element, context)} ${partialAttr}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "</WmPanel>",
  imports: (element: HTMLElement, context: TranspilationContext) =>
    imports.concat(getPartialImports(element, context)),
} as Transformer;
