import { MultiDimensionStyleParser } from "./multi-dimension-style.parser";

export class MarginParser extends MultiDimensionStyleParser {
  constructor() {
    super("");
  }

  parse(value: string) {
    const values = super.parseDimensions(value);
    return {
      marginTop: values[0],
      marginRight: values[1],
      marginBottom: values[2],
      marginLeft: values[3],
    };
  }
}
