import { HTMLElement } from "node-html-parser";

import {
  Import,
  isHTMLElement,
  transformAttrs,
  Transformer,
  TranspilationContext,
} from "../../transpile";

export const imports: Import[] = [
  {
    name: "WmNavItem",
    from: "@wavemaker-ai/react-runtime/components/navbar/nav-item",
  },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    element.childNodes.forEach(n => {
      if (isHTMLElement(n) && n.tagName === "WM-ANCHOR") {
        n.setAttribute("class", "navAnchorItem " + (n.getAttribute("class") || ""));
      }
    });

    return `<WmNavItem
      ${transformAttrs(element, context)}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "</WmNavItem>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
