import { HTMLElement } from "node-html-parser";

import { Import, transformAttrs, Transformer, TranspilationContext } from "../../../transpile";
import { LAYOUT_ATTR_NAMES } from "../../../widget-inline-style-constants";

export const imports: Import[] = [];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const name = element.getAttribute("name");
    return `<React.Fragment key={'list_item' + $index + '_' + '${name}'} >`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => {
    // Strip layout attrs after children are processed so they can read parent direction.
    for (const name of LAYOUT_ATTR_NAMES) {
      element.removeAttribute(name);
    }
    element.removeAttribute("width");
    element.removeAttribute("height");
    return "</React.Fragment>";
  },
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
