import { HTMLElement } from "node-html-parser";

import {
  Import,
  parse,
  transformAttrs,
  Transformer,
  TranspilationContext,
  createComponent,
} from "../../transpile";
import { FormWidgetType, setDefaultPlaceholder, DATASET_WIDGETS } from "./form/util";
import { getAttribute } from "./form/field-widget-shared";
import { getDatasourceExpr } from "../utils";

export const imports: Import[] = [
  {
    name: "WmLiveFilterField",
    from: "@wavemaker-ai/react-runtime/components/data/form/form-field",
  },
];

const getStyleProps = (element: HTMLElement) => {
  const attributes = [
    "fontsize",
    "fontweight",
    "color",
    "textalign",
    "fontfamily",
    "textdecoration",
    "fontstyle",
  ];
  return attributes.reduce((propsString, attr) => {
    const value = getAttribute(element, attr);
    if (value !== undefined) {
      propsString += `${attr}=${value} `;
    }
    return propsString;
  }, "");
};

const extractField = (element: HTMLElement, context: TranspilationContext, filterElement: any) => {
  const widgetType = getAttribute(element, "widget") || "text";
  const widgetName =
    getAttribute(element, "key") || getAttribute(element, "name") || "text" + "_filterWidget";
  const isRange = element.getAttribute("is-range") === "true";

  const result = getFilterWidgetTemplate(
    widgetType,
    widgetName,
    element,
    getAttribute(filterElement, "filterdata"),
    false
  );

  // For any widget with is-range=true, create a second max widget
  if (isRange) {
    const maxField = getFilterWidgetTemplate(
      widgetType,
      widgetName,
      element,
      getAttribute(filterElement, "filterdata"),
      true
    );
    return {
      ...result,
      maxField: maxField.field,
    };
  }

  return result;
};

const getFilterWidgetTemplate = (
  widgetType: string,
  widgetName: string,
  element: HTMLElement,
  filterDataVariable: any,
  isMaxWidget: boolean = false
) => {
  widgetName = widgetName.replace(".", "_");
  const inputName = getAttribute(element, "key")?.split(".")?.at(-1);

  // Only show label for first widget (not max widget)
  var labelMarkup =
    !isMaxWidget && getAttribute(element, "displayname")
      ? `<wm-label 
    required="bind:$formField.required"
    htmlFor="${inputName}"
    caption="bind:$formField.displayname"
    notag="true"
    class="app-label control-label filterfield-label"
    conditionalclass="bind:$formField.captionCls + ' ' + $formField.invalidCls"
    name="${widgetName}_filterLabel"></wm-label>`
      : "";

  const onFocus = getAttribute(element, "on-focus");
  if (onFocus) {
    element.removeAttribute("on-focus");
  }
  const onBlur = getAttribute(element, "on-blur");
  if (onBlur) {
    element.removeAttribute("on-blur");
  }
  const onTap = getAttribute(element, "on-tap");
  if (onTap) {
    element.removeAttribute("on-tap");
  }
  const placeholderAttr = isMaxWidget ? "maxplaceholder" : "placeholder";
  const placeholder = getAttribute(element, placeholderAttr);
  if (placeholder && !isMaxWidget) {
    element.removeAttribute("placeholder");
  }
  const filterfieldName = getAttribute(element, "name");

  // For max widget, add "_maxWidget" suffix to name and use maxvalue
  const widgetNameSuffix = isMaxWidget ? "_maxWidget" : "";
  const datavalueBinding = isMaxWidget
    ? "bind:$formField.maxDataValue ?? $formField.maxdefaultvalue"
    : "bind:$formField.datavalue ?? $formField.defaultvalue";
  const isMaxWidgetProp = isMaxWidget ? "isMaxWidget={true}" : "";

  var commonFields = `name="${filterfieldName}_formWidget${widgetNameSuffix}"
                      formfield="true"
                      datavalue="${datavalueBinding}"
                      conditionalclass="bind:$formField.widgetCls"
                      ${placeholder ? 'placeholder="' + placeholder + '"' : ""}
                      ${onFocus ? "on-focus=" + onFocus : ""}
                      ${onBlur ? "on-blur=" + onBlur : ""}
                      ${isMaxWidgetProp} `;
  var widgetMarkup = getWidgetMarkup(widgetType, widgetName, commonFields, element);
  let currentNode = element.parentNode;
  while (currentNode) {
    if (
      currentNode.rawTagName === "wm-livefilter" ||
      currentNode.getAttribute("type") === "dynamic"
    ) {
      break;
    }
    currentNode = currentNode.parentNode;
  }

  return {
    label: labelMarkup ? (parse(labelMarkup).firstChild as HTMLElement) : null,
    field: parse(widgetMarkup).firstChild as HTMLElement,
  };
};

const getWidgetMarkup = (
  widgetType: string,
  widgetName: string,
  commonFields: string,
  element: HTMLElement
) => {
  let tmpl = "";
  const getDisplayExpr =
    element.getAttribute("displayexpression") || element.getAttribute("displaylabel");
  // Replace single quotes with &apos; to prevent breaking the attribute
  const displayExp = getDisplayExpr
    ? `displayexpression='${getDisplayExpr.replace(/'/g, "&apos;")}'`
    : "";
  const filterFieldTags = ["text", "password", "number", "currency", "textarea"];
  let currentNode = element.parentNode;
  while (currentNode) {
    if (
      currentNode.rawTagName === "wm-livefilter" ||
      currentNode.getAttribute("type") === "dynamic"
    ) {
      break;
    }
    currentNode = currentNode.parentNode;
  }
  const isFloatingFilter = currentNode.getAttribute("captionposition") === "floating";
  const floatinglabel =
    filterFieldTags.includes(widgetType) && isFloatingFilter
      ? `floatinglabel="${element.getAttribute("displayname")?.replace(/"/g, "&quot;")}"`
      : "";
  const dateTimeDialogTags = ["date", "time", "datetime"];
  const isDateTimeTag = dateTimeDialogTags.includes(widgetType);
  // * date picker modal customization
  const dateheadertitle =
    isDateTimeTag && element.getAttribute("dateheadertitle")
      ? `dateheadertitle="${element.getAttribute("dateheadertitle")?.replace(/"/g, "&quot;")}"`
      : "";
  const dateconfirmationtitle =
    isDateTimeTag && element.getAttribute("dateconfirmationtitle")
      ? `dateconfirmationtitle="${element.getAttribute("dateconfirmationtitle")?.replace(/"/g, "&quot;")}"`
      : "";
  const datecanceltitle =
    isDateTimeTag && element.getAttribute("datecanceltitle")
      ? `datecanceltitle="${element.getAttribute("datecanceltitle")?.replace(/"/g, "&quot;")}"`
      : "";

  // * time picker modal customization
  const timeheadertitle =
    isDateTimeTag && element.getAttribute("timeheadertitle")
      ? `timeheadertitle="${element.getAttribute("timeheadertitle")?.replace(/"/g, "&quot;")}"`
      : "";
  const timeconfirmationtitle =
    isDateTimeTag && element.getAttribute("timeconfirmationtitle")
      ? `timeconfirmationtitle="${element.getAttribute("timeconfirmationtitle")?.replace(/"/g, "&quot;")}"`
      : "";
  const timecanceltitle =
    isDateTimeTag && element.getAttribute("timecanceltitle")
      ? `timecanceltitle="${element.getAttribute("timecanceltitle")?.replace(/"/g, "&quot;")}"`
      : "";

  const outputformat = element.getAttribute("outputformat")
    ? `outputformat="${element.getAttribute("outputformat")?.replace(/"/g, "&quot;")}"`
    : ``;

  switch (widgetType) {
    case "text":
    case "password":
      let inputtype = widgetType === "password" ? "password" : getAttribute(element, "inputtype");
      inputtype = inputtype ? `type=${inputtype}` : "";
      tmpl = `<wm-text ${inputtype} ${commonFields} 
                updateon="bind:$formField.updateon"
                maxchars="bind:$formField.maxchars"
                ${getStyleProps(element)}
                ></wm-text>`;
      break;
    case "textarea":
      tmpl = `<wm-textarea ${commonFields}
                updateon="bind:$formField.updateon || 'blur'"
                maxchars="bind:$formField.maxchars"
                ${floatinglabel}>
                ${getStyleProps(element)}
              </wm-textarea>`;
      break;
    case "number":
      tmpl = `<wm-number ${commonFields}
                updateon="bind:$formField.updateon || 'blur'"
                minvalue="bind:$formField.minvalue"
                maxvalue="bind:$formField.maxvalue"
                displayValue="bind:$formField.displayValue"
                ${floatinglabel}>
              </wm-number>`;
      break;
    case "currency":
      tmpl = `<wm-currency ${commonFields}
                  updateon="bind:$formField.updateon || 'blur'"
                  minvalue="bind:$formField.minvalue"
                  maxvalue="bind:$formField.maxvalue"
                  ${floatinglabel}>
                </wm-currency>`;
      break;
    case "select":
      tmpl = `<wm-select ${commonFields} ${displayExp}
                dataset="bind:$formField.dataset"
                displayfield="bind:$formField.displayfield"
                datafield="bind:$formField.datafield"
              ></wm-select>`;
      break;
    case "autocomplete":
      const datasource = getDatasourceExpr(element);
      // Fall back to the key attribute's value only when searchkey isn't already set -
      // key is the form-binding path (e.g. "Employee.department"), not a field on the bound
      // dataset's entity, and must not clobber an explicitly-configured searchkey.
      const searchkeyAttribute = element.getAttribute("searchkey") || element.getAttribute("key");
      if (searchkeyAttribute) {
        element.setAttribute("searchkey", searchkeyAttribute);
      }

      tmpl = `<wm-search ${commonFields} ${displayExp}
                type="autocomplete"
                limit="bind:$formField.limit"
                displayimagesrc="bind:$formField.displayimagesrc"
                searchkey="bind:$formField.searchkey"
                showclear="bind:$formField.showclear || false"
                dataset="bind:$formField.dataset"
                displayfield="bind:$formField.displaylabel"
                datafield="bind:$formField.datafield"
                 ${datasource ? `datasource="${datasource}"` : ""}
                ></wm-search>`;
      break;
    case "chips":
      tmpl = `<wm-chips ${commonFields} ${displayExp}
                minchars="bind:$formField.minchars || 1"
                maxsize="bind:$formField.maxsize"
                displayimagesrc="bind:$formField.displayimagesrc"
                searchkey="bind:$formField.searchkey"
                dataset="bind:$formField.dataset || 'Option 1, Option 2, Option 3'"
                displayfield="bind:$formField.displayfield"
                datafield="bind:$formField.datafield"
                ></wm-chips>`;
      break;
    case "checkbox":
      tmpl = `<wm-checkbox ${commonFields}
                  caption="bind:$formField.caption"
                  checkedvalue="bind:$formField.checkedvalue || true"
                  uncheckedvalue="bind:$formField.uncheckedvalue || false">
              </wm-checkbox>`;
      break;
    case "checkboxset":
      tmpl = `<wm-checkboxset ${commonFields} ${displayExp}
                dataset="bind:$formField.dataset || 'Option 1, Option 2, Option 3'"
                displayfield="bind:$formField.displayfield"
                datafield="bind:$formField.datafield"
              ></wm-checkboxset>`;
      break;
    case "toggle":
      tmpl = `<wm-checkbox ${commonFields}
                type="toggle"
                checkedvalue="bind:$formField.checkedvalue || true"
                uncheckedvalue="bind:$formField.uncheckedvalue || false">
              </wm-checkbox>`;
      break;
    case "iconbutton-toggle":
      tmpl = `<wm-checkbox ${commonFields}
                type="button"
                checkedvalue="bind:$formField.checkedvalue || true"
                uncheckedvalue="bind:$formField.uncheckedvalue || false">
              </wm-checkbox>`;
      break;
    case "switch":
      tmpl = `<wm-switch ${commonFields} ${displayExp}
                dataset="bind:$formField.dataset || 'yes, no, maybe'"
                displayfield="bind:$formField.displayfield"
                datafield="bind:$formField.datafield"
              ></wm-switch>`;
      break;
    case "radioset":
      tmpl = `<wm-radioset ${commonFields} ${displayExp}
                dataset="bind:$formField.dataset || 'Option 1, Option 2, Option 3'"
                displayfield="bind:$formField.displayfield"
                datafield="bind:$formField.datafield"
              ></wm-radioset>`;
      break;
    case "date":
      tmpl += `<wm-date ${commonFields}
                mindate="bind:$formField.mindate"
                maxdate="bind:$formField.maxdate"
                datepattern="bind:$formField.datepattern"
                ${outputformat}
                ${dateheadertitle}
                ${dateconfirmationtitle}
                ${datecanceltitle}
                ></wm-date>`;
      break;
    case "datetime":
    case "timestamp":
      tmpl = `<wm-datetime ${commonFields}
                mindate="bind:$formField.mindate"
                maxdate="bind:$formField.maxdate"
                datepattern="bind:$formField.datepattern"
                ${outputformat}
                ${dateheadertitle}
                ${dateconfirmationtitle}
                ${datecanceltitle}
                ${timeheadertitle}
                ${timeconfirmationtitle}
                ${timecanceltitle}
                ></wm-datetime>`;
      break;
    case "time":
      tmpl += `<wm-time ${commonFields} 
                timepattern="bind:$formField.timepattern"
                ${outputformat}
                ${timeheadertitle}
                ${timeconfirmationtitle}
                ${timecanceltitle}
                ></wm-time>`;
      break;
    case "slider":
      tmpl += `<wm-slider ${commonFields} 
                minvalue="bind:$formField.minvalue || 0"
                maxvalue="bind:$formField.maxvalue || 100"
                step="bind:$formField.step || 1"
                ></wm-slider>`;
      break;
    case "rating":
      let showcaptions = getAttribute(element, "showcaptions");
      showcaptions = showcaptions ? `showcaptions="bind:$formField.showcaptions"` : "";
      tmpl += `<wm-rating ${commonFields} ${displayExp}
                ${getAttribute(element, "dataset") ? 'dataset="bind:$formField.dataset"' : ""}
                displayfield="bind:$formField.displayfield || 'value'"
                datafield="bind:$formField.datafield || 'key'"
                ${showcaptions}
                maxvalue="bind:$formField.maxvalue || 5"
                ></wm-rating>`;
      break;
    case "fileupload":
    case "file":
      const onSelect = getAttribute(element, "on-select");
      const onDelete = getAttribute(element, "on-delete");

      tmpl = `<wm-fileupload ${commonFields} 
                ${onSelect ? 'on-select="onSelect"' : ""}
                ${onDelete ? 'on-delete="onDelete"' : ""}
      ></wm-fileupload>`;
      break;
    case "upload":
      const onSelectUpload = getAttribute(element, "on-select");
      const onDeleteUpload = getAttribute(element, "on-delete");

      tmpl = `<wm-upload ${commonFields} 
                ${onSelectUpload ? 'on-select="onSelect"' : ""}
                ${onDeleteUpload ? 'on-delete="onDelete"' : ""}
      ></wm-upload>`;
      break;
    case "richtext":
      tmpl = `<wm-richtexteditor ${commonFields} ${displayExp}
              ></wm-richtexteditor>`;
      break;
    case "colorpicker":
      tmpl = `<wm-colorpicker ${commonFields}
                updateon="bind:$formField.updateon || 'blur'"
                ${floatinglabel}>
              </wm-colorpicker>`;
      break;
    default:
      if (widgetType.toLowerCase().includes("wmx")) {
        // widgetType = "wmx-MultiSelect"
        const fromAttr = widgetType?.split("-").at(-1);
        const hyphenatedToComponentName = (str: string) =>
          str
            .split("-")
            .map(segment => segment.charAt(0).toUpperCase() + segment.slice(1))
            .join("") || "";
        const componentName =
          hyphenatedToComponentName((fromAttr || "customwidget").trim()) || "Customwidget";
        tmpl = `<wmx-component componentname="${componentName}" ${commonFields} ${displayExp}></wmx-component>`;
      }
      break;
  }
  return tmpl;
};

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const widgetType = (getAttribute(element, "widget") as FormWidgetType) || FormWidgetType.TEXT;
    let currentNode = element.parentNode;
    while (currentNode) {
      if (
        currentNode.rawTagName === "wm-livefilter" ||
        currentNode.getAttribute("type") === "dynamic"
      ) {
        break;
      }
      currentNode = currentNode.parentNode;
    }
    let filterName, filterScope, control;
    if (currentNode.getAttribute("type") === "dynamic") {
      filterName = currentNode.getAttribute("dynamicFilter");
      filterScope = `filterScope={() => fragment.Widgets.${filterName}}`;
    } else {
      filterName = currentNode.getAttribute("name");
    }

    if (DATASET_WIDGETS.includes(widgetType) || widgetType.toLowerCase().includes("wmx")) {
      if (element.attrs["primary-key"]) {
        element.setAttribute("primaryKey", element.attrs["primary-key"]);
      }
      element.removeAttribute("primary-key");
      if (element.attrs["is-related"]) {
        element.setAttribute("isRelated", element.attrs["is-related"]);
      }
      element.removeAttribute("is-related");
      if (element.getAttribute("dataset")) {
        element.setAttribute("isDataSetBound", "true");
      }

      // If dataset is not present, inherit from parent wm-liveform suggested by @bhadhavya_vakiti
      if (!element.getAttribute("dataset") && currentNode?.rawTagName === "wm-liveform") {
        const parentDataset = currentNode.getAttribute("dataset");
        if (parentDataset) {
          element.setAttribute("dataset", parentDataset);
        }
      }

      if (element.getAttribute("dataset")) {
        element.setAttribute("isDataSetBound", "true");
      }

      // Set default displayfield and datafield to name attribute if not provided
      const nameAttribute = element.getAttribute("name");
      if (nameAttribute) {
        if (!element.hasAttribute("displayfield")) {
          element.setAttribute("displayfield", nameAttribute);
        }
        if (!element.hasAttribute("datafield")) {
          element.setAttribute("datafield", nameAttribute);
        }
      }
    }

    const formField = extractField(element, context, currentNode);
    if (formField.label) {
      element.childNodes.push(formField.label);
    }
    element.childNodes.push(formField.field);

    // For number widget with is-range=true, add the max widget
    if ((formField as any).maxField) {
      element.childNodes.push((formField as any).maxField);
    }

    element.removeAttribute("datavalue");
    element.removeAttribute("height");

    // Convert is-range to isRange
    const isRangeValue = element.getAttribute("is-range");
    if (isRangeValue) {
      element.setAttribute("isRange", isRangeValue);
      element.removeAttribute("is-range");
    }

    const childDatasetNode = currentNode.getAttribute("childdatasetnode");
    if (childDatasetNode) {
      element.setAttribute("formKey", childDatasetNode + "." + element.attrs["name"]);
    } else {
      element.setAttribute("formKey", element.attrs["key"] || element.attrs["name"]);
    }
    element.removeAttribute("key");
    if (isRangeValue === "true") {
      setDefaultPlaceholder(element, widgetType, 0);
      setDefaultPlaceholder(element, widgetType, 1);
    } else {
      setDefaultPlaceholder(element, widgetType, 2);
    }
    const fieldcolumn = element.getAttribute("field");
    element.removeAttribute("field");

    if (filterName) {
      element.setAttribute("filterName", filterName);
      element.setAttribute("formName", filterName);
    }

    return `<WmLiveFilterField  ${filterScope || ""} field="true" ${fieldcolumn ? `fieldcol="${fieldcolumn}"` : ""}    ${transformAttrs(element, context)} renderFormFields={($formField) => (<>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "</>)}></WmLiveFilterField>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
  createComponent: (element: HTMLElement, context: TranspilationContext) =>
    createComponent(element, context),
} as Transformer;
