import { HTMLElement } from "node-html-parser";

import {
  createExpression,
  Import,
  transformAttrs,
  Transformer,
  TranspilationContext,
} from "../../transpile";

export const imports: Import[] = [
  { name: "WmSlider", from: "@wavemaker-ai/react-runtime/components/input/slider" },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    let getDisplayExpression = createExpression(element, "displayexpression");
    if (getDisplayExpression) {
      element.removeAttribute("displayexpression");
      element.removeAttribute("displayfield");
    }

    let getToolTipExpression = createExpression(element, "tooltipexpression");
    if (getToolTipExpression) {
      element.removeAttribute("tooltipexpression");
    }
    const isFormField = element.getAttribute("formfield") === "true";

    return `<WmSlider ${isFormField ? " {...$formField}" : ""} listener={fragment}
      ${transformAttrs(element, context)} 
      ${getDisplayExpression ? `getDisplayExpression=${getDisplayExpression}` : ""}
      ${getToolTipExpression ? `getToolTipExpression=${getToolTipExpression}` : ""}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "</WmSlider>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
