import { HTMLElement } from "node-html-parser";
import { Import, TranspilationContext } from "../../transpile";
import PartialContainerTransformer from "./partial-container.transformer";

interface WithPartialContainerOptions {
  prop: "renderPartial" | "render";
  removeName?: boolean;
  extraParams?: string;
}

export function withPartialContainer(
  element: HTMLElement,
  context: TranspilationContext,
  options: WithPartialContainerOptions
): { partialAttr: string; extraImports: Import[] } {
  let partial = PartialContainerTransformer.pre(element, context) || "";
  const extraImports = PartialContainerTransformer.imports(element, context);
  if (partial) {
    if (options.removeName) {
      element.removeAttribute("name");
    }
    const params = options.extraParams
      ? `props:Record<string, any>, onLoad:(widget?: any)=>void, ${options.extraParams}`
      : "props:Record<string, any>, onLoad:(widget?: any)=>void";
    partial = `${options.prop}={(${params}) => (${partial})}`;
  }
  return { partialAttr: partial, extraImports };
}

export function getPartialImports(element: HTMLElement, context: TranspilationContext): Import[] {
  return PartialContainerTransformer.imports(element, context);
}
