import { DimensionStyleParser } from "./dimension-style.parser";

export abstract class MultiDimensionStyleParser extends DimensionStyleParser {
  constructor(styleName: string) {
    super(styleName);
  }

  parseDimensions(value: string): any {
    const splits = value.split(" ").map(v => {
      if (v != "unset") {
        return super.parse(v)[this.styleName];
      }
      return null;
    });
    if (splits.length === 1) {
      splits[1] = splits[0];
      splits[2] = splits[0];
      splits[3] = splits[0];
    } else if (splits.length === 2) {
      splits[2] = splits[0];
      splits[3] = splits[1];
    }
    return splits;
  }
}
