import { StyleParser } from "./style.parser";

const alignValues = {
  left: "flex-start",
  right: "flex-end",
  center: "center",
} as any;

export class HorizontalAlignParser extends StyleParser {
  constructor() {
    super("");
  }

  parse(value: string) {
    return {
      textAlign: value,
      flexDirection: "row",
      justifyContent: alignValues[value],
      flexWrap: "wrap",
    };
  }
}
