import { HTMLElement } from "node-html-parser";
import isString from "lodash/isString";

import {
  Import,
  isHTMLElement,
  transformAttrs,
  Transformer,
  TranspilationContext,
} from "../../transpile";
import { getParentNode } from "../utils";

export const imports: Import[] = [
  {
    name: "WmDialogActions",
    from: "@wavemaker-ai/react-runtime/components/dialogs/dialog-actions",
  },
];

const applyAttr = (e: HTMLElement, replace: RegExp | string, replaceWith: string) => {
  Object.keys(e.attrs).forEach(k => {
    const v = e.getAttribute(k);
    if (isString(v)) {
      e.setAttribute(k, v.replace(replace, replaceWith));
    }
  });
  e.childNodes.forEach(c => isHTMLElement(c) && applyAttr(c, replace, replaceWith));
};

const DIALOG_TAGS = [
  "wm-dialog",
  "wm-logindialog",
  "wm-alertdialog",
  "wm-confirmdialog",
  "wm-iframedialog",
  "wm-pagedialog",
];

const isInsideDialog = (element: HTMLElement) => !!getParentNode(element, DIALOG_TAGS);

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    if (!isInsideDialog(element)) {
      // remove all the children of the element
      Array.from(element.childNodes).forEach((child: any) => {
        element.removeChild(child);
      });
      return ``;
    }
    const widgetName = getParentNode(element, DIALOG_TAGS);
    if (widgetName) {
      applyAttr(
        element,
        new RegExp("closeDialog(\\?\\.)?\\(\\)", "g"),
        `Widgets?.${widgetName}?.close?.()`
      );
    }

    return `<WmDialogActions   ${transformAttrs(element, context)}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => {
    if (!isInsideDialog(element)) {
      return ``;
    }
    return "</WmDialogActions>";
  },
  imports: (element: HTMLElement, context: TranspilationContext) => {
    if (!isInsideDialog(element)) {
      return [];
    }
    return imports;
  },
} as Transformer;
