import { isEmpty } from "lodash";
import { HTMLElement } from "node-html-parser";

import { Import, transformAttrs, Transformer, TranspilationContext } from "../../../transpile";
import { findElement } from "../../utils";

export const imports: Import[] = [
  {
    name: "WmLayoutgrid",
    from: "@wavemaker-ai/react-runtime/components/container/layout-grid",
  },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) =>
    `<WmLayoutgrid iswidget="false" ${transformAttrs(element, context)}>`,
  post: (element: HTMLElement, context: TranspilationContext) => "</WmLayoutgrid>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
