import {
  FILL_SIZE_STYLE_PROPS,
  FILL_STYLED_WIDGET_TAGS,
  LITERAL_FILL_WIDGET_TAGS,
} from "../widget-inline-style-constants";
import { NumericalStyleParser } from "./numeric-style.parser";

export class DimensionStyleParser extends NumericalStyleParser {
  constructor(styleName: string) {
    super(styleName);
  }

  parse(value: string, element?: any): any {
    if (value === "auto") {
      const style = {} as any;
      style[this.styleName] = value;
      return style;
    } else if (value === "fill") {
      const style = {} as any;
      const tag = element?.rawTagName;
      if (FILL_SIZE_STYLE_PROPS.has(this.styleName) && !FILL_STYLED_WIDGET_TAGS.has(tag)) {
        // appliing nothing for width/height="fill" on other widgets.
        return style;
      }
      if (this.styleName === "width") {
        style[this.styleName] = "100%";
      }
      if (this.styleName === "height") {
        style[this.styleName] = LITERAL_FILL_WIDGET_TAGS.has(tag) ? value : "100%";
      }
      return style;
    } else if (value === "hug") {
      const style = {} as any;
      style[this.styleName] = "fit-content";
      return style;
    } else if (value && value.endsWith("%")) {
      const style = {} as any;
      style[this.styleName] = value;
      return style;
    } else if (value && (value.endsWith("vw") || value.endsWith("vh"))) {
      const style = {} as any;
      style[this.styleName] = value;
      return style;
    } else if (
      value &&
      (value.endsWith("em") ||
        value.endsWith("rem") ||
        value.endsWith("px") ||
        value.endsWith("pt") ||
        value.endsWith("pc") ||
        value.endsWith("in") ||
        value.endsWith("cm") ||
        value.endsWith("mm"))
    ) {
      const style = {} as any;
      style[this.styleName] = value;
      return style;
    } else if (value && value === "fill") {
      const style = {} as any;
      style[this.styleName] = "100%";
      return style;
    }
    return super.parse(value);
  }
}
