/**
 * Per-document cleanup + tag grouping for one collected designtime doc (Swagger 2 shape).
 * Unlike the old swagger-builder.js, this never merges across documents — it only cleans up
 * one doc's own tags/operationIds and groups its own paths by tag, ready for one generated
 * service class per tag.
 */

import { toPascalCase } from "./schema-to-ts";

export interface NormalizedOperation {
  pathTemplate: string;
  httpMethod: string;
  operation: any;
  // The operationId as it appears in the doc, before deriveMethodName() cleans it up. Same string
  // WM stores on a variable's own `operationId`, so it keys the per-operation lookups.
  rawOperationId: string;
  // Every shorter operationId form reachable by stripping one prefix layer at a time. WM does not
  // always record the doc's raw operationId verbatim on a variable (a doubled prefix like
  // "foo_foo_invoke" is commonly stored as "foo_invoke"), so lookups register under all of these.
  operationIdAliases: string[];
}

/** Raw operationId plus every form reachable by repeatedly stripping one `${prefix}_` layer. */
function computeOperationIdAliases(rawOperationId: string, prefixCandidates: string[]): string[] {
  const aliases = new Set<string>([rawOperationId]);
  const queue = [rawOperationId];
  while (queue.length) {
    const current = queue.shift()!;
    for (const prefix of prefixCandidates) {
      if (!prefix || !current.startsWith(`${prefix}_`)) continue;
      const stripped = current.slice(prefix.length + 1);
      if (stripped && !aliases.has(stripped)) {
        aliases.add(stripped);
        queue.push(stripped);
      }
    }
  }
  return Array.from(aliases);
}

export interface NormalizedDoc {
  basePath: string;
  host?: string;
  schemes?: string[];
  proxyWeb: boolean;
  definitions: Record<string, any>;
  operationsByTag: Map<string, NormalizedOperation[]>;
}

const HTTP_METHOD_PRIORITY: Record<string, number> = {
  get: 0,
  post: 1,
  put: 2,
  patch: 3,
  delete: 4,
  options: 5,
  head: 6,
};

function toCamelCaseIdentifier(name: string): string {
  if (typeof name !== "string" || !/[^a-zA-Z0-9]/.test(name)) return name;
  const words = name.split(/[^a-zA-Z0-9]+/).filter(Boolean);
  if (!words.length) return name;
  let result = words.map((w, i) => (i === 0 ? w : w.charAt(0).toUpperCase() + w.slice(1))).join("");
  if (/^[0-9]/.test(result)) result = "_" + result;
  return result;
}

/** Strips a trailing "Controller" suffix, then a trailing "Service" suffix (the class emitter re-adds "Service" exactly once). */
export function normalizeTagName(tagName: string): string {
  let name = tagName;
  if (name.endsWith("Controller")) {
    name = name.slice(0, -"Controller".length) || tagName;
  }
  if (name.endsWith("Service")) {
    name = name.slice(0, -"Service".length) || name;
  }
  return name;
}

/**
 * Reduces a raw operationId (e.g. "hrdbSwagger_DepartmentController_exportDepartments") to the
 * bare action name ("exportDepartments").
 *
 * Two WM conventions: prefixes stack (so stripping repeats), and the SAME segment can appear
 * doubled ("X_X_removeCategory"). A doubled prefix is collapsed to ONE copy rather than stripped,
 * because a plain "X_removeCategory" sibling in the same tag would otherwise collide with it.
 */
export function deriveMethodName(rawOperationId: string, prefixCandidates: string[]): string {
  if (!rawOperationId) return "";

  for (const prefix of prefixCandidates) {
    if (!prefix) continue;
    const doubled = `${prefix}_${prefix}_`;
    if (rawOperationId.startsWith(doubled)) {
      return toCamelCaseIdentifier(rawOperationId.slice(prefix.length + 1));
    }
  }

  let operationId = rawOperationId;
  let strippedSomething = true;
  while (strippedSomething) {
    strippedSomething = false;
    for (const prefix of prefixCandidates) {
      if (prefix && operationId.startsWith(`${prefix}_`)) {
        operationId = operationId.slice(prefix.length + 1);
        strippedSomething = true;
        break;
      }
    }
  }
  return toCamelCaseIdentifier(operationId);
}

/**
 * Whether an OpenAPIService doc's operations should split per tag or lump into one class named
 * after the service. Docs re-exposing a real backend have meaningful per-entity tags and should
 * split; lightweight wrappers tag everything the same (often "default"), where splitting would
 * only rename the single class. Decided from the doc's own tag count.
 */
function hasMultipleDistinctTags(doc: any, serviceId: string): boolean {
  const distinctTags = new Set<string>();
  Object.values<any>(doc.paths || {}).forEach(methods => {
    Object.values<any>(methods).forEach(operation => {
      if (operation && typeof operation === "object") {
        distinctTags.add((operation.tags && operation.tags[0]) || serviceId);
        if (distinctTags.size > 1) return;
      }
    });
  });
  return distinctTags.size > 1;
}

export function normalizeDoc(doc: any, serviceName: string): NormalizedDoc {
  const info = doc.info || {};
  const serviceType = info["x-WM-SERVICE_TYPE"];
  const serviceId = info["x-WM-SERVICE_ID"] || serviceName;
  const proxyWeb = info["x-WM-USE_PROXY_FOR_WEB"] !== false;
  const splitOpenApiServiceByTag =
    serviceType === "OpenAPIService" && hasMultipleDistinctTags(doc, serviceId);

  // tag -> methodName -> chosen operation. A Map (not a plain array) so a same-named GET/POST
  // pair for one logical action (WM's "fall back to POST when the query string is too long for
  // GET" convention) can be deduped/replaced in place instead of both surviving into the output.
  const byTag = new Map<string, Map<string, NormalizedOperation>>();

  Object.entries<any>(doc.paths || {}).forEach(([pathTemplate, methods]) => {
    const orderedMethods = Object.entries<any>(methods).sort(
      ([a], [b]) => (HTTP_METHOD_PRIORITY[a] ?? 99) - (HTTP_METHOD_PRIORITY[b] ?? 99)
    );

    orderedMethods.forEach(([httpMethod, operation]) => {
      if (!operation || typeof operation !== "object") return;

      let tag: string;
      let rawTag: string;
      if (serviceType === "OpenAPIService" && !splitOpenApiServiceByTag) {
        rawTag = serviceId;
        tag = serviceId.endsWith("Service") ? serviceId.slice(0, -"Service".length) : serviceId;
      } else {
        rawTag = (operation.tags && operation.tags[0]) || serviceId;
        tag = normalizeTagName(rawTag);
      }
      // Real tags are often not valid identifiers ("Manage - Category"), and this drives a class
      // name — variable.transformer's resolveServiceTag() must sanitize the same way.
      tag = toPascalCase(tag);

      // A lumped OpenAPIService doc groups by service id, but its operationIds still commonly bake
      // the per-op tag on as an extra layer — include it as a stripping candidate for method names.
      const opRawTag: string | undefined = operation.tags && operation.tags[0];
      const opTag = opRawTag ? normalizeTagName(opRawTag) : undefined;
      const prefixCandidates = [rawTag, tag, serviceId, opRawTag, opTag].filter(
        Boolean
      ) as string[];

      const rawOperationId = operation.operationId || "";
      const methodName = deriveMethodName(rawOperationId, prefixCandidates);
      const entry: NormalizedOperation = {
        pathTemplate,
        httpMethod,
        operation: { ...operation, operationId: methodName },
        rawOperationId,
        operationIdAliases: computeOperationIdAliases(rawOperationId, prefixCandidates),
      };

      if (!byTag.has(tag)) {
        byTag.set(tag, new Map());
      }
      const tagMethods = byTag.get(tag)!;
      const existing = tagMethods.get(methodName);

      if (existing) {
        // Same method name from another verb (WM emits a GET and POST twin for one action).
        // Methods are visited GET-first, so prefer POST only for export-style actions.
        if (
          /^export/i.test(methodName) &&
          httpMethod === "post" &&
          existing.httpMethod !== "post"
        ) {
          tagMethods.set(methodName, entry);
        }
        return;
      }

      tagMethods.set(methodName, entry);
    });
  });

  const operationsByTag = new Map<string, NormalizedOperation[]>();
  byTag.forEach((methods, tag) => operationsByTag.set(tag, Array.from(methods.values())));

  return {
    basePath: doc.basePath || "",
    host: doc.host,
    schemes: doc.schemes,
    proxyWeb,
    definitions: doc.definitions || {},
    operationsByTag,
  };
}
