import { HTMLElement } from "node-html-parser";
import { encode } from "html-entities";

import { inferTypeAndParseProperty } from "../utils";
import { parse, isHTMLElement, transformAttrs, TranspilationContext } from "../../transpile";
import { isRowBoundExpression, transformTableRowCurrentItemExpression } from "../data/table/utils";

const ignoredAttributes = ["name", "show", "content", "class", "styles"];

export function buildPartialMarkup(
  element: HTMLElement,
  context: TranspilationContext,
  componentName: string
): string {
  const content = element.attributes["content"];
  const name = element.attributes["name"];
  if (!content) {
    return "";
  }

  const params = {} as any;
  if (!element.hasAttribute("is-table-row")) {
    Object.keys(element.attrs).forEach(k => {
      if (!ignoredAttributes.includes(k)) {
        params[k] = element.attrs[k];
      }
    });
  }

  const watch: string[] = [];
  const typedParams = new Set<string>();
  const rowBoundParamParts: string[] = [];
  const isTableRow = element.hasAttribute("is-table-row");
  element.childNodes
    .filter(node => isHTMLElement(node) && node.tagName === "WM-PARAM")
    .forEach(node => {
      const e = node as HTMLElement;
      const name = e.getAttribute("name") || "";
      let value = e.getAttribute("value") || "";
      const type = e.getAttribute("type") || "";
      if (value.includes("currentItem")) {
        const match = value.match(/currentItem\..+/);
        if (match) {
          value = `bind:${match[0]}`;
        }
      }
      if (isTableRow && isRowBoundExpression(value)) {
        rowBoundParamParts.push(`${name}={${transformTableRowCurrentItemExpression(value)}}`);
      } else {
        params[name] = value;
      }
      if (type && ["string", "boolean", "number"].includes(type)) {
        typedParams.add(name);
      }
      watch.push(name);
    });

  const syntheticTag = componentName
    .replace(/([A-Z])/g, "-$1")
    .toLowerCase()
    .replace(/^-/, "");

  let paramStr = Object.keys(params)
    .filter(k => k !== "on-load")
    .map(k => `${k}="${encode(params[k])}"`)
    .join(" ");
  const typeAwareInfer = (name: string, valWithQuotes: string) => {
    if (typedParams.has(name)) {
      return valWithQuotes;
    }
    return inferTypeAndParseProperty(name, valWithQuotes);
  };
  paramStr = transformAttrs(
    parse(`<${syntheticTag} ${paramStr}/>`).firstChild as HTMLElement,
    context,
    typeAwareInfer
  );
  if (rowBoundParamParts.length > 0) {
    paramStr += ` ${rowBoundParamParts.join(" ")}`;
  }
  paramStr += ` content={props.content}`;
  if (context.isPartOfPrefab) {
    paramStr += " prefab={fragment.prefab}";
    paramStr += "prefabName={fragment.prefabName}";
    paramStr += "Prefab={stateProxy}";
  }

  return `<${componentName} ${watch.length > 0 ? `params={${JSON.stringify(watch)}}` : ""}  onLoad={onLoad} ${paramStr} partialName={'${name}'} listener={props.listener} />`;
}
