import { HTMLElement } from "node-html-parser";

import profile from "../../../profiles/profile";
import {
  createComponent,
  Transformer,
  transformAttrs,
  TranspilationContext,
  Import,
} from "../../transpile";
import { inferTypeAndParseProperty, getParentNode } from "../utils";

const capitalize = (str: string | undefined) => {
  return str
    ? str
        .split("-")
        .map(s => s.charAt(0).toUpperCase() + s.substring(1))
        .join("")
    : str;
};

const getParentForm = (element: HTMLElement) => {
  let currentNode = element.parentNode;
  while (currentNode) {
    if (currentNode.rawTagName === "wm-form" || currentNode.rawTagName === "wm-liveform") {
      return currentNode.getAttribute("name") || "";
    }
    currentNode = currentNode.parentNode;
  }
  return "";
};

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const prefabName = capitalize(element.getAttribute("prefabname"));
    const widgetname = capitalize(element.getAttribute("widgetname"));
    const name = capitalize(element.getAttribute("name"));

    // Check if prefab is inside a form and set parentForm attribute
    const parentForm = getParentForm(element);
    if (parentForm) {
      element.setAttribute("parentForm", parentForm);
    }

    // Check if prefab is inside a list and set parent list attributes
    const parentListName = getParentNode(element, "wm-list");
    if (parentListName) {
      element.setAttribute("parentListName", parentListName);
      element.setAttribute("isParentList", "true");
    }
    const isPreview = context.get("preview") === true;
    if (isPreview) {
      return `<WmPrefabContent prefab={true} ${transformAttrs(element, context, inferTypeAndParseProperty)} ${parentListName ? `formArrayIndex={$index}` : ""}>`;
    }

    if (widgetname) {
      return `<Wm${widgetname}  ${transformAttrs(element, context, inferTypeAndParseProperty)} ${parentListName ? `formArrayIndex={$index}` : ""}>`;
    }
    return `<Wm${prefabName}Prefab prefab={true} ${transformAttrs(element, context, inferTypeAndParseProperty)} ${parentListName ? `formArrayIndex={$index}` : ""}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => {
    const isPreview = context.get("preview") === true;
    if (isPreview) {
      return `</WmPrefabContent>`;
    }
    const prefabName = capitalize(element.getAttribute("prefabname"));
    const widgetname = capitalize(element.getAttribute("widgetname"));
    if (widgetname) {
      return `</Wm${widgetname}>`;
    }
    return `</Wm${prefabName}Prefab>`;
  },
  imports: (element: HTMLElement, context: TranspilationContext) => {
    const isPreview = context.get("preview") === true;

    const prefabName = element.getAttribute("prefabname");
    const widgetname = element.getAttribute("widgetname");
    const widgetmodule = element.getAttribute("widgetmodule");
    const imports = [] as Import[];
    if (widgetname && !isPreview) {
      imports.push({ name: "Wm" + capitalize(widgetname), from: widgetmodule } as Import);
    } else if (!isPreview) {
      imports.push({
        name: "Wm" + capitalize(prefabName) + "Prefab",
        from: `@/app/prefabs/${prefabName}/Main/Main`,
        lazy: profile.lazyloadPrefabs,
      });
    }
    return imports;
  },
  createComponent: (element: HTMLElement, context: TranspilationContext) =>
    createComponent(element, context),
  prefabs: (element: HTMLElement, context: TranspilationContext) => {
    const prefabname = element.getAttribute("prefabname");
    if (prefabname) {
      return [prefabname];
    }
    return [];
  },
} as Transformer;
