import { HTMLElement } from "node-html-parser";

import { Import, transformAttrs, Transformer, TranspilationContext } from "../../transpile";
import { transformFormat } from "../utils";

export const imports: Import[] = [
  {
    name: "WmCurrency",
    from: "@wavemaker-ai/react-runtime/components/input/currency",
  },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    // const replaceFnName = "getCurrencySymbol";
    // transformFormat(element, "currency", replaceFnName);
    const isFormField = element.getAttribute("formfield") === "true";
    return `<WmCurrency ${isFormField ? " {...$formField}" : ""}  listener={fragment}  ${transformAttrs(element, context)}>`;
  },
  post: (element: HTMLElement) => "</WmCurrency>",
  imports: (element: HTMLElement) => imports,
} as Transformer;
