import { isEmpty, isNil, merge } from "lodash";
import { HTMLElement } from "node-html-parser";
import { StyleParser } from "./style/style.parser";
import { DimensionStyleParser } from "./style/dimension-style.parser";
import { MarginParser } from "./style/margin.parser";
import { PaddingParser } from "./style/padding.parser";
import { BorderWidthParser } from "./style/border-width.parser";
import { NumericalStyleParser } from "./style/numeric-style.parser";
import { HorizontalAlignParser } from "./style/horizontal-align.parser";
import { BackgroundImageParser } from "./style/background-image.parser";

const StyleProps = new Map<string, StyleParser>([
  ["backgroundimage", new BackgroundImageParser()],
  ["backgroundsize", new StyleParser("backgroundSize")],
  ["backgroundrepeat", new StyleParser("backgroundRepeat")],
  ["backgroundresizemode", new StyleParser("backgroundResizeMode")],
  ["backgroundposition", new StyleParser("backgroundPosition")],
  ["backgroundattachment", new StyleParser("backgroundAttachment")],
  ["backgroundcolor", new StyleParser("backgroundColor")],
  ["bordercolor", new StyleParser("borderColor")],
  ["borderradius", new DimensionStyleParser("borderRadius")],
  ["borderstyle", new StyleParser("borderStyle")],
  ["borderwidth", new BorderWidthParser("borderWidth")],
  ["borderbottomwidth", new DimensionStyleParser("borderBottomWidth")],
  ["borderleftwidth", new DimensionStyleParser("borderLeftWidth")],
  ["borderrightwidth", new DimensionStyleParser("borderRightWidth")],
  ["bordertopwidth", new DimensionStyleParser("borderTopWidth")],
  ["color", new StyleParser("color")],
  //['cursor', ''],
  //['display', ''],
  ["fontsize", new DimensionStyleParser("fontSize")],
  ["fontunit", new StyleParser("fontUnit")],
  ["fontfamily", new StyleParser("fontFamily")],
  ["fontstyle", new StyleParser("fontStyle")],
  ["fontvariant", new StyleParser("fontVariant")],
  ["fontweight", new StyleParser("fontWeight")],
  ["height", new DimensionStyleParser("height")],
  ["horizontalalign", new DimensionStyleParser("horizontalAlign")],
  ["lineheight", new DimensionStyleParser("lineHeight")],
  ["margin", new MarginParser()],
  ["marginbottom", new DimensionStyleParser("marginBottom")],
  ["marginleft", new DimensionStyleParser("marginLeft")],
  ["marginheight", new DimensionStyleParser("marginHeight")],
  ["marginwidth", new DimensionStyleParser("marginWidth")],
  ["frameborder", new DimensionStyleParser("frameBorder")],
  ["marginright", new DimensionStyleParser("marginRight")],
  ["margintop", new DimensionStyleParser("marginTop")],
  ["opacity", new NumericalStyleParser("opacity")],
  ["overflow", new StyleParser("overflow")],
  ["padding", new PaddingParser()],
  ["paddingbottom", new DimensionStyleParser("paddingBottom")],
  ["paddingleft", new DimensionStyleParser("paddingLeft")],
  ["paddingright", new DimensionStyleParser("paddingRight")],
  ["paddingtop", new DimensionStyleParser("paddingTop")],
  //['picturesource', ''],
  ["textalign", new StyleParser("textAlign")],
  ["textdecoration", new StyleParser("textDecorationLine")],
  ["horizontalalign", new HorizontalAlignParser()],
  ["verticalalign", new StyleParser("textAlignVertical")],
  //['visibility', ''],
  //['whitespace', ''],
  ["width", new DimensionStyleParser("width")],
  //['wordbreak', ''],
  ["zindex", new NumericalStyleParser("zIndex")],
]);

const TextStyleProps = [
  "color",
  "fontSize",
  "fontFamily",
  "fontStyle",
  "fontVariant",
  "fontWeight",
  "lineHeight",
  "textAlign",
  "textDecorationLine",
  "textAlignVertical",
];

export default (element: HTMLElement, isStyleProperty?: (styleProp: string) => boolean) => {
  const style: any = {};
  const textStyle: any = {};
  let fontUnit = "";
  StyleProps.forEach((parser, k) => {
    if (!!element.hasAttribute(k) && isStyleProperty && isStyleProperty(k)) {
      const value = element.getAttribute(k);
      // Keep width/height="fill" on the element so autolayout attribute-selector
      // CSS (e.g. div[direction="row"] > [width="fill"]) can still match it.
      const isFillDimension = (k === "width" || k === "height") && value === "fill";
      if (!isFillDimension) {
        element.removeAttribute(k);
      }
      if (value) {
        if (value.startsWith("bind:")) {
          if (k === "backgroundimage" && value.startsWith('bind:"') && value.endsWith('"')) {
            const literal = value.substring(6, value.length - 1);
            merge(style, parser.parse(literal, element));
          } else {
            style[parser.styleName || k] = value;
          }
        } else {
          if (k === "fontunit") {
            fontUnit = value;
          } else {
            merge(style, parser.parse(value, element));
          }
        }
      }
    }
  });

  if (style.fontSize && fontUnit) {
    style.fontSize = `${style.fontSize}${fontUnit}`;
  }
  Object.keys(style).forEach(k => {
    if (isNil(style[k])) {
      delete style[k];
    }
  });
  if (isEmpty(style)) {
    return null;
  }
  if (style["borderStyle"] === "none") {
    delete style["borderStyle"];
  }
  const styles: any = style;
  return styles;
};
