import { HTMLElement } from "node-html-parser";

import {
  createExpression,
  Import,
  transformAttrs,
  Transformer,
  TranspilationContext,
} from "../../transpile";
import { extractDatasetInfo, getDatasourceExpr } from "../utils";

export const imports: Import[] = [
  { name: "WmChips", from: "@wavemaker-ai/react-runtime/components/input/chips" },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const isFormField = element.getAttribute("formfield") === "true";
    let getDisplayExpression;
    getDisplayExpression = createExpression(element, "displayexpression");
    if (getDisplayExpression) {
      element.removeAttribute("displayexpression");
    }

    getDatasourceExpr(element);

    return `<WmChips listener={fragment} ${isFormField ? " {...$formField}" : ""} ${getDisplayExpression ? `displayexpression=${getDisplayExpression}` : ""} ${extractDatasetInfo(element)}  ${transformAttrs(element, context)}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "</WmChips>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
