import { HTMLElement } from "node-html-parser";

import { Transformer } from "../../transpile";

const toCamelCase = (name: string) =>
  name.replace(/-([a-z])/g, (_, letter) => letter.toUpperCase());

const attrs = (element: HTMLElement) =>
  Object.entries(element.attributes)
    .map(([name, value]) => {
      if (name.startsWith("on-")) {
        return `on${name.substring(3).replace(/-/g, "")}={($event) => { ${value.replace(/;+$/, "")} }}`;
      }
      if (value.startsWith("bind:")) return `${toCamelCase(name)}={${value.substring(5)}}`;
      return `${name}=${JSON.stringify(value)}`;
    })
    .join(" ");

export default {
  pre: (element: HTMLElement, context) => {
    const tagName = element.tagName.toLowerCase();
    if (context.data?.preview) {
      return `<${tagName} ${attrs(element)}>`;
    }
    return `<WebComponent tagname=${JSON.stringify(tagName)} ${attrs(element)} />`;
  },
  post: (element: HTMLElement, context) =>
    context.data?.preview ? `</${element.tagName.toLowerCase()}>` : "",
  imports: (element: HTMLElement, context) =>
    context.data?.preview ? [] : [{ name: "WebComponent", from: "@/app/helper/web-component" }],
} as Transformer;
