import { HTMLElement } from "node-html-parser";

import { Import, transformAttrs, Transformer, TranspilationContext } from "../../transpile";

export const imports: Import[] = [
  {
    name: "WmPicture",
    from: "@wavemaker-ai/react-runtime/components/basic/picture",
  },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const attr = element.getAttribute("picturesource");
    if (attr && attr.startsWith("bind:")) {
      element.setAttribute("picturesource", attr.replace(/[;,]+\s*$/, ""));
    }
    return `<WmPicture listener={fragment} ${transformAttrs(element, context)}  ${context.isPartOfPrefab ? " prefabName={fragment.prefabName}" : ""} >`;
  },

  post: (element: HTMLElement, context: TranspilationContext) => "</WmPicture>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
