import { HTMLElement } from "node-html-parser";

import {
  createComponent,
  createExpression,
  Import,
  isHTMLElement,
  transformAttrs,
  Transformer,
  TranspilationContext,
  transpileElement,
} from "../../transpile";
import { transformRepeatChildData } from "../utils";

export const imports: Import[] = [
  { name: "WmWizard", from: "@wavemaker-ai/react-runtime/components/container/wizard" },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    let i = 0;
    element.childNodes.forEach(c => {
      if (isHTMLElement(c)) {
        c.setAttribute("index", "" + i++);
      }
    });

    let menudataexpr = createExpression(element, "menudataexpr");
    if (menudataexpr) {
      element.removeAttribute("menudataexpr");
    }

    // Handle dynamic type with dataset
    const isDynamic = element.getAttribute("type") === "dynamic";
    const dataSet = element.getAttribute("dataset");

    if (isDynamic && dataSet && dataSet.startsWith("bind:")) {
      const dataSetValue = dataSet.substring(5);
      const template = element.childNodes.find(c => isHTMLElement(c));

      if (template) {
        const wizardActionNodes = element.childNodes.filter(
          (node: any) => isHTMLElement(node) && node.rawTagName === "wm-wizardaction"
        ) as HTMLElement[];
        if (wizardActionNodes && wizardActionNodes.length) {
          wizardActionNodes.forEach(n => {
            n.remove();
          });
          context.set("wizard_action_nodes", wizardActionNodes);
        }

        // Transform repeat child data for dynamic wizard steps
        transformRepeatChildData(template as HTMLElement, dataSetValue + "[0]", "repeat_item");
        transformRepeatChildData(template as HTMLElement, dataSetValue + "[$i]", "repeat_item");
        transformRepeatChildData(
          template as HTMLElement,
          dataSetValue + "[fragment.$i]",
          "repeat_item"
        );

        // Store old props and set new props for dynamic rendering
        context.set("old_props", context.props);
        context.props = ["$item", "$index"];

        return `<WmWizard listener={fragment} ${transformAttrs(element, context)} 
          ${menudataexpr ? `getmenudataexpression=${menudataexpr}` : ""}
          render={(($item:Record<string,any>,$index:number,data:Record<string,any>[])=>(`;
      }
    }

    return `<WmWizard listener={fragment} ${transformAttrs(element, context)} 
      ${menudataexpr ? `getmenudataexpression=${menudataexpr}` : ""}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => {
    const dataSet = element.getAttribute("dataset");
    if (element.getAttribute("type") === "dynamic" && dataSet && dataSet.startsWith("bind:")) {
      context.props = context.get("old_props");
      const wizardActionNodes = (context.get("wizard_action_nodes") || []) as HTMLElement[];
      let actionsMarkup = "";
      if (wizardActionNodes && wizardActionNodes.length) {
        wizardActionNodes.forEach(node => {
          const tr = transpileElement(node as any, context.isPartOfPrefab, true, context);
          context.result.imports.push(...tr.imports);
          context.result.partials.push(...tr.partials);
          context.result.prefabs.push(...tr.prefabs);
          context.result.components = { ...context.result.components, ...tr.components };
          actionsMarkup += tr.markup;
        });
      }
      return `))}>${actionsMarkup}</WmWizard>`;
    }
    return "</WmWizard>";
  },
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
  createComponent: (element: HTMLElement, context: TranspilationContext) => {
    if (!context.data.listCount) {
      context.props = context.get("old_props") || [];
    }
    const componentMarkup = createComponent(element, context);
    context.props = [];
    return componentMarkup;
  },
} as Transformer;
