import { assignIn } from "lodash";

export interface Profile {
  generateWeb: boolean;
  /**
   * Whether this build generates WMX components into the target.
   *
   * Off for web previews: the preview builder copies the component sources,
   * installs their dependencies and runs esbuild itself, all into the same
   * wmx-components/ directory. Doing it here as well is duplicated work on
   * every save.
   */
  generateWmxComponents: boolean;
  /**
   * Whether pages sharing a layout are grouped under a Next route group, so the
   * shared header/nav lives in one layout.tsx instead of in every page.
   *
   * Off for web previews. A preview never loads the generated app -- the browser
   * renders from page.min.json -- so the grouping buys nothing there, while
   * costing an extra full transpile of every page's markup just to detect
   * layouts. It also makes a page's output PATH depend on how many other pages
   * share its layout, so adding or removing a page moves existing pages and
   * leaves their previous output behind.
   */
  groupPagesByLayout: boolean;
  copyResources: boolean;
  lazyloadPages: boolean;
  lazyloadPartials: boolean;
  lazyloadPrefabs: boolean;
  linkNodeModules: boolean;
  useLocalMetadata: boolean;
  targetPlatform: "web" | "native";
}

/**
 * Default profile
 */
const DefaultProfile = {
  generateWeb: false,
  generateWmxComponents: true,
  groupPagesByLayout: true,
  copyResources: true,
  lazyloadPages: true,
  lazyloadPartials: true,
  lazyloadPrefabs: true,
  linkNodeModules: false,
  useLocalMetadata: true,
  targetPlatform: "native",
} as Profile;

const profile = {
  ...DefaultProfile,
} as Profile;

export const setProfile = (p: Profile) => assignIn(profile, DefaultProfile, p);

export default profile;
