const getExistingImportUrls = (layoutContent: string): Set<string> => {
  const existingUrls = new Set<string>();
  try {
    const parsed = parseHtml(layoutContent);

    const traverseNodes = (node: any) => {
      if (node.nodeType === NodeType.ELEMENT_NODE) {
        const tagName = node.tagName?.toLowerCase();
        if (tagName === "script" || tagName === "link") {
          const url = node.getAttribute("src") || node.getAttribute("href") || "";
          if (url) {
            existingUrls.add(url);
          }
        }
        if (node.childNodes) {
          node.childNodes.forEach((child: any) => {
            traverseNodes(child);
          });
        }
      }
    };

    parsed.childNodes.forEach((node: any) => {
      traverseNodes(node);
    });
  } catch (error) {
    // If parsing fails, return empty set
  }
  return existingUrls;
};

/**
 * HTML attribute names that need to be converted for JSX compatibility
 */
const HTML_TO_JSX_ATTR_MAP: Record<string, string> = {
  class: "className",
  for: "htmlFor",
  tabindex: "tabIndex",
  readonly: "readOnly",
  autofocus: "autoFocus",
  autoplay: "autoPlay",
  crossorigin: "crossOrigin",
  maxlength: "maxLength",
  minlength: "minLength",
  spellcheck: "spellCheck",
};

/**
 * Void elements that must be self-closing in JSX
 */
const VOID_ELEMENTS = new Set([
  "area",
  "base",
  "br",
  "col",
  "embed",
  "hr",
  "img",
  "input",
  "link",
  "meta",
  "param",
  "source",
  "track",
  "wbr",
]);

/**
 * Converts CSS style string to React style object format
 * Example: "color:#ffffff; font-size:14px" -> {color:"#ffffff",fontSize:"14px"}
 */
export const convertStyleStringToObject = (styleString: string): string => {
  if (!styleString || styleString.trim() === "") {
    return "{}";
  }
  const styleObject: Record<string, string> = {};
  styleString.split(";").forEach(rule => {
    const colonIndex = rule.indexOf(":");
    if (colonIndex > 0) {
      const property = rule.substring(0, colonIndex).trim();
      const value = rule.substring(colonIndex + 1).trim();
      if (property && value) {
        const camelCaseProperty = property.replace(/-([a-z])/g, (_, letter) =>
          letter.toUpperCase()
        );
        styleObject[camelCaseProperty] = value;
      }
    }
  });
  return JSON.stringify(styleObject);
};

/**
 * Converts HTML string to JSX-compatible format (class->className, style->style object, etc.)
 * @param htmlString The HTML string to convert
 * @returns JSX-compatible string
 */
export const htmlToJsx = (htmlString: string): string => {
  if (!htmlString || typeof htmlString !== "string") {
    return "";
  }

  try {
    const parsed = parseHtml(htmlString);

    const nodeToJsx = (node: any): string => {
      if (node.nodeType === NodeType.TEXT_NODE) {
        return node.text || "";
      }
      if (node.nodeType !== NodeType.ELEMENT_NODE) {
        return "";
      }

      const tagName = node.tagName?.toLowerCase() || "div";
      const isVoid = VOID_ELEMENTS.has(tagName);

      const attrs: string[] = [];
      const attributes = node.attributes || node.attrs || {};
      if (Object.keys(attributes).length > 0) {
        for (const [attr, value] of Object.entries(attributes)) {
          if (value == null || value === "") continue;
          const attrLower = attr.toLowerCase();
          if (attrLower === "class") {
            attrs.push(`className="${value}"`);
          } else if (attrLower === "style") {
            attrs.push(`style={${convertStyleStringToObject(value as string)}}`);
          } else {
            const jsxAttr = HTML_TO_JSX_ATTR_MAP[attrLower] || attr;
            attrs.push(`${jsxAttr}="${value}"`);
          }
        }
      }

      const attrsStr = attrs.length ? " " + attrs.join(" ") : "";

      if (isVoid) {
        return `<${tagName}${attrsStr} />`;
      }

      let children = "";
      if (node.childNodes?.length) {
        children = node.childNodes.map((child: any) => nodeToJsx(child)).join("");
      }
      return `<${tagName}${attrsStr}>${children}</${tagName}>`;
    };

    return parsed.childNodes.map((node: any) => nodeToJsx(node)).join("");
  } catch (error) {
    console.error("Error converting HTML to JSX:", error);
    return "";
  }
};

/**
 * Extracts the interactive-container div from HTML (with full structure including children)
 * @param htmlString The HTML string to parse
 * @returns The outerHTML of the interactive-container div, or empty string if not found
 */
export const extractInteractiveContainerDiv = (htmlString: string): string => {
  if (!htmlString || typeof htmlString !== "string") {
    return "";
  }

  try {
    const parsed = parseHtml(htmlString);

    const findInteractiveContainer = (node: any): any => {
      if (node.nodeType === NodeType.ELEMENT_NODE) {
        const tagName = node.tagName?.toLowerCase();
        if (tagName === "div") {
          const className = node.getAttribute("class") || "";
          if (className.split(/\s+/).includes("interactive-container")) {
            return node;
          }
        }
        if (node.childNodes) {
          for (const child of node.childNodes) {
            const found = findInteractiveContainer(child);
            if (found) return found;
          }
        }
      }
      return null;
    };

    for (const node of parsed.childNodes) {
      const div = findInteractiveContainer(node);
      if (div) {
        return div.outerHTML;
      }
    }
  } catch (error) {
    console.error("Error extracting interactive-container div:", error);
  }
  return "";
};

/**
 * Extracts only <script> and <link> tags from an HTML string that:
 * - Retains every script and CDN link
 * - Are NOT already present in the layout file
 * @param htmlString The HTML string to parse
 * @param layoutContent Optional layout file content to check for existing imports
 * @returns A string containing only the extracted <script> and <link> tags
 */
export type HtmlHeadAsset =
  | { kind: "tag"; jsx: string }
  | { kind: "inline-script"; content: string; attributes: string };

/**
 * Collects user-owned head assets in their source order. Inline JavaScript is
 * deliberately returned as data: callers must write it to a .js asset instead
 * of interpolating it into TSX, where braces would be parsed as JSX.
 */
export const extractHtmlHeadAssets = (
  htmlString: string,
  layoutContent?: string
): HtmlHeadAsset[] => {
  if (!htmlString || typeof htmlString !== "string") {
    return [];
  }

  try {
    const parsed = parseHtml(htmlString);
    const extractedTags: HtmlHeadAsset[] = [];
    const bootstrapScripts = new Set(
      parsed.querySelectorAll?.(
        'script[src$="/wm-loader.min.js"], script[src$="/wm-libs.min.js"], script[src$="/wm-loader.js"], script[src$="/wm-libs.js"], script[src$="/wm-react-loader.min.js"], script[src$="/wm-react-loader.js"], script[src$="/wmProperties.js"], script[src$="/wmx-components.min.js"]'
      ) || []
    );

    // Get existing URLs from layout if provided
    const existingUrls = layoutContent ? getExistingImportUrls(layoutContent) : new Set<string>();

    // Patterns to identify jQuery and Angular libraries
    const jqueryPatterns = [/jquery/i, /\bjq\b/i, /jquery-ui/i, /jquery\.min/i];

    const angularPatterns = [/angular/i, /ng-/i, /angularjs/i, /@angular/i];

    // Function to check if a URL is from jQuery or Angular
    const isJQueryOrAngular = (url: string): boolean => {
      if (!url) return false;

      const lowerUrl = url.toLowerCase();
      return (
        jqueryPatterns.some(pattern => pattern.test(lowerUrl)) ||
        angularPatterns.some(pattern => pattern.test(lowerUrl))
      );
    };

    // Function to check if a URL is a CDN path (http:// or https://)
    const isCdnPath = (url: string): boolean => {
      if (!url) return false;
      return url.startsWith("http://") || url.startsWith("https://");
    };

    const toLocalScriptJsx = (node: any, url: string): string => {
      const resourcePath = url.replace(/^\.\//, "").replace(/^\//, "");
      const source = node.outerHTML.replace(
        /\bsrc\s*=\s*(["']).*?\1/i,
        `src={\`\${configs.appConfig.basePath}${resourcePath}\`}`
      );
      return source;
    };

    // Function to recursively traverse nodes
    const traverseNodes = (node: any) => {
      if (node.nodeType === NodeType.ELEMENT_NODE) {
        const tagName = node.tagName?.toLowerCase();

        // Extract script and link tags
        if (tagName === "script" || tagName === "link") {
          if (bootstrapScripts.has(node)) return;
          // Get the URL from src (for script) or href (for link)
          const url = node.getAttribute("src") || node.getAttribute("href") || "";

          const isScript = tagName === "script" && !!url;
          const isInlineScript =
            tagName === "script" &&
            !url &&
            node.getAttribute("type")?.toLowerCase() !== "application/ld+json" &&
            !!node.innerHTML?.trim();
          const isRemoteUserAsset = tagName === "link" && isCdnPath(url) && !isJQueryOrAngular(url);

          if (isInlineScript) {
            extractedTags.push({
              kind: "inline-script",
              content: node.innerHTML,
              attributes: node.rawAttrs || "",
            });
          } else if ((isScript || isRemoteUserAsset) && !existingUrls.has(url)) {
            // Convert to JSX-compatible format (self-closing for link tags only)
            let jsxTag = isScript && !isCdnPath(url) ? toLocalScriptJsx(node, url) : node.outerHTML;

            // For link tags, ensure they are self-closing for JSX compatibility
            if (tagName === "link") {
              // Remove any closing tag </link>
              jsxTag = jsxTag.replace(/\s*<\/link>/gi, "");

              // If it doesn't end with />, make it self-closing
              if (!jsxTag.trim().endsWith("/>")) {
                // Replace the closing > with />
                jsxTag = jsxTag.replace(/>\s*$/, " />");
              }
            }
            extractedTags.push({ kind: "tag", jsx: jsxTag });
          }
        }

        // Recursively process child nodes
        if (node.childNodes) {
          node.childNodes.forEach((child: any) => {
            traverseNodes(child);
          });
        }
      }
    };

    // Traverse all nodes in the parsed HTML
    parsed.childNodes.forEach((node: any) => {
      traverseNodes(node);
    });

    return extractedTags;
  } catch (error) {
    console.error("Error extracting script and link tags:", error);
    return [];
  }
};

export const extractScriptAndLinkTags = (htmlString: string, layoutContent?: string): string =>
  extractHtmlHeadAssets(htmlString, layoutContent)
    .filter((asset): asset is Extract<HtmlHeadAsset, { kind: "tag" }> => asset.kind === "tag")
    .map(asset => asset.jsx)
    .join("\n");
