import { Import, Transformer, TranspilationContext, transformAttrs } from "../../transpile";
import { HTMLElement } from "node-html-parser";

export const imports: Import[] = [
  {
    name: "WmWizardAction",
    from: "@wavemaker-ai/react-runtime/components/container/wizard/wizard-action",
  },
];

// Find the nearest parent wm-wizard element name; fallback to action name
function getNearestWizardName(element: HTMLElement): string | undefined {
  let current: HTMLElement | null = (element.parentNode as HTMLElement) || null;
  if (current?.tagName?.toLowerCase() === "wm-wizard") {
    const n = current.getAttribute("name");
    if (n) {
      return n;
    }
  }
  return undefined;
}

// Navigation/state APIs must use the renderActions `actions` callback (wizard context).
// Label/config APIs still use fragment.Widgets.<wizardName> (synced via listener.onChange).
function prefixWizardApiReferences(root: HTMLElement, wizardRefName: string) {
  const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const wizardActionApiNames = [
    "done",
    "next",
    "previous",
    "prev",
    "cancel",
    "skip",
    "disableNext",
    "disablePrevious",
    "disableDone",
    "hasNextStep",
    "hasPreviousStep",
    "hasNoNextStep",
  ];
  const wizardConfigApiNames = [
    "cancelable",
    "skippable",
    "nextbtnlabel",
    "previousbtnlabel",
    "donebtnlabel",
    "cancelbtnlabel",
    "actionsalignment",
  ];
  const actionApiPart = wizardActionApiNames.map(escapeRe).join("|");
  const configApiPart = wizardConfigApiNames.map(escapeRe).join("|");
  const reActionOptional = new RegExp(`fragment\\?\\.(${actionApiPart})\\b`, "g");
  const reActionPlain = new RegExp(`fragment\\.(${actionApiPart})\\b`, "g");
  const reActionBind = new RegExp(`bind:fragment\\.(${actionApiPart})\\b`, "g");
  const reConfigOptional = new RegExp(`fragment\\?\\.(${configApiPart})\\b`, "g");
  const reConfigPlain = new RegExp(`fragment\\.(${configApiPart})\\b`, "g");
  const reConfigBind = new RegExp(`bind:fragment\\.(${configApiPart})\\b`, "g");

  const rewrite = (val: string) => {
    if (!val) return val;
    let v = val;
    v = v.replace(reActionBind, "bind:actions?.$1");
    v = v.replace(reActionOptional, "actions?.$1");
    v = v.replace(reActionPlain, "actions.$1");
    v = v.replace(reConfigBind, `bind:fragment?.Widgets?.${wizardRefName}?.$1`);
    v = v.replace(reConfigOptional, `fragment?.Widgets?.${wizardRefName}?.$1`);
    v = v.replace(reConfigPlain, `fragment?.Widgets?.${wizardRefName}?.$1`);
    // Add optional chaining on wizard method calls to avoid runtime errors when missing
    const actionsPathRe = /(actions)\.([a-zA-Z_$][\w$]*)\(/g;
    v = v.replace(actionsPathRe, (_m, base: string, method: string) => {
      return `${base}?.${method}?.(`;
    });
    const widgetPathRe = new RegExp(
      `(fragment\\?\\.Widgets\\?\\.${escapeRe(wizardRefName)})\\.([a-zA-Z_$][\\w$]*)\\(`,
      "g"
    );
    v = v.replace(widgetPathRe, (_m, base: string, method: string) => {
      return `${base}?.${method}?.(`;
    });
    const method = v.split("?.");
    if (method && method[3] && wizardConfigApiNames.includes(method[3])) {
      return v.slice(0, v.lastIndexOf("?"));
    }
    return v;
  };

  const walk = (node: HTMLElement) => {
    // Rewrite attributes on this node
    Object.keys(node.attributes).forEach(attrName => {
      const oldVal = node.getAttribute(attrName);
      if (!oldVal) return;
      const newVal = rewrite(oldVal);
      if (newVal !== oldVal) {
        node.setAttribute(attrName, newVal);
      }
    });
    // Recurse
    node.childNodes.forEach(c => {
      if (c && (c as any).tagName) {
        walk(c as HTMLElement);
      }
    });
  };

  walk(root);
}

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const wizardName = getNearestWizardName(element) || element.getAttribute("name") || "";
    let actionsalignment = "";
    if (wizardName) {
      prefixWizardApiReferences(element, wizardName);
      actionsalignment = `actionsalignment={fragment?.Widgets?.${wizardName}?.actionsalignment}`;
    }
    // Same pattern as wm-list: pre opens render callback + fragment, post closes callback, prop, opening tag, and component.
    return `<WmWizardAction listener={fragment} ${actionsalignment ? actionsalignment : ""}  ${transformAttrs(element, context)}
renderActions={(actions: any) => (<>`;
  },
  post: (_element: HTMLElement, _context: TranspilationContext) => `</>
)}
>
</WmWizardAction>`,
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
