import registerTransformers from "./components/transform-register";
import transformVariable from "../variables/variable.transformer";

let registered = false;

function ensureRegistered(): void {
  if (!registered) {
    registerTransformers();
    registered = true;
  }
}

export interface TranspiledVariableDefinitions {
  variables: any[];
  actions: any[];
  imports: string[];
}

/**
 * Transforms raw variable JSON definitions into transpiled variable config objects.
 * Pure functional — no Handlebars, no file generation.
 *
 * Use this in the dynamic runtime to get the same bind:/paramProvider/event handling
 * as the codegen without pulling in the Handlebars template engine.
 */
export function transpileVariableDefinitions(
  variables: Record<string, any> | undefined,
  appUrl: string,
  scope: string
): TranspiledVariableDefinitions {
  ensureRegistered();
  const imports: string[] = [];
  const transformed = Object.values(variables ?? {})
    .map((v: any) => transformVariable(v, scope, appUrl, imports))
    .filter(v => !!v);

  return {
    variables: transformed.filter(v => v.group === "variable"),
    actions: transformed.filter(v => v.group === "action"),
    imports,
  };
}
