import { HTMLElement } from "node-html-parser";
import {
  addOptionalChaining,
  addOptionalChainingToPropertyPath,
  convertHyphenatedPropsToBracketNotation,
} from "../../../../utils.browser";
import transformEx, { resolveFormatContext } from "../../../bind.ex.transformer";

const CUSTOM_PIPE_REGEX = /(custom(\s*:))/;

export function checkIsCustomPipeExpression(exp: string): boolean {
  return CUSTOM_PIPE_REGEX.test(exp);
}

export function findNearestElement(element: HTMLElement, tagName: string): string | undefined {
  let current: HTMLElement | null = element.parentNode as HTMLElement | null;
  const target = tagName.toLowerCase();

  while (current) {
    if (current.tagName?.toLowerCase() === target) {
      return current.getAttribute("name") ?? undefined;
    }
    current = current.parentNode as HTMLElement | null;
  }

  return undefined;
}

export function convertActionToClickHandler(
  actionAttr: string,
  tableName?: string,
  liveTableName?: string
): string {
  const statements = actionAttr
    .split(";")
    .map(s => s.trim())
    .filter(Boolean);

  const converted = statements.map(statement => {
    // Convert hyphenated property paths to bracket notation (e.g. Actions.goToPage_test-page -> Actions["goToPage_test-page"])
    statement = convertHyphenatedPropsToBracketNotation(statement);
    // Replace $event with event
    let cleaned = statement.replace(/\$event/g, "event");

    // If it's just a native event call, return as is
    if (cleaned.startsWith("event.")) return cleaned;

    // Global scope: Variables/Fn/Actions
    if (
      cleaned.startsWith("Actions") ||
      cleaned.startsWith("Variables") ||
      cleaned.startsWith("Widgets")
    ) {
      return `fragment.${cleaned}`;
    }

    // Function call
    if (cleaned.includes("(")) {
      const funcName = cleaned.split("(")[0];

      // e.g., Table1_customHandler(event)
      if (tableName && funcName.startsWith(`${tableName}_`)) {
        return `fragment.${cleaned}`;
      }

      // If function uses (event), transform to (event, widget, row)
      if (cleaned.includes("(event)")) {
        cleaned = cleaned.replace("(event)", "(event, widget, row)");
      }

      if (funcName.endsWith("addNewRow") || funcName.endsWith("editRow")) {
        const scopeName = liveTableName || tableName;
        if (scopeName) {
          return `fragment.Widgets.${scopeName}.${cleaned}`;
        }
      }

      if (funcName.endsWith("deleteRow") && tableName) {
        return `fragment.Widgets.${tableName}.${cleaned}`;
      }

      return `fragment.${cleaned}`;
    }

    // Fallback - treat as plain fragment call
    return `fragment.${cleaned}`;
  });

  return `onClick={(event, widget, row) => {\n  ${converted.join("\n  ")}\n}}`;
}

/**
 * Transforms table column class expressions by:
 * 1. Replacing fragment.row/fragment?.row with rowData
 * 2. Replacing standalone row. and row[ with rowData.
 * 3. Applying optional chaining to property access
 * 4. Removing optional chaining between method names and parentheses
 * 5. Normalizing double quotes to single quotes in string literals
 *
 * @param expression - The expression string to transform
 * @returns The transformed expression string
 */
export function isRowBoundExpression(value: string): boolean {
  if (!value || typeof value !== "string") return false;
  const exp = value.startsWith("bind:") ? value.substring(5).trim() : value;
  return /fragment\??\.row/.test(exp) || /\brow\./.test(exp) || /\brow\[/.test(exp);
}

export function transformTableRowPropExpression(expression: string): string {
  if (!expression) return "";
  let transformed = expression.replace(/fragment\??\.row/g, "row");
  transformed = transformed.replace(/\brow\./g, "row?.");
  transformed = transformed.replace(/\brow\[/g, "row?.[");
  transformed = addOptionalChaining(transformed);
  transformed = transformed.replace(/row\?\?\./g, "row?.");
  transformed = transformed.replace(/(\w+)\?\.\s*\(/g, "$1(");
  return transformed;
}

export function transformTableRowCurrentItemExpression(expression: string): string {
  if (!expression) return "";
  const raw = expression.startsWith("bind:") ? expression.substring(5).trim() : expression;
  let transformed = raw.replace(/fragment\??\.row/g, "currentItem");
  transformed = transformed.replace(/\brow\./g, "currentItem?.");
  transformed = transformed.replace(/\brow\[/g, "currentItem?.[");
  transformed = addOptionalChaining(transformed);
  transformed = transformed.replace(/currentItem\?\?\./g, "currentItem?.");
  transformed = transformed.replace(/(\w+)\?\.\s*\(/g, "$1(");
  return transformed;
}

const TABLE_ROW_PROPS_SKIP_ATTRS = new Set([
  "name",
  "class",
  "className",
  "content",
  "widget-type",
  "display-name",
  "displayName",
  "rowType",
  "is-table-row",
  "styles",
  "style",
]);

export function buildTableRowProps(element: HTMLElement): string {
  const parts: string[] = [];
  const toRemove: string[] = [];

  for (const name of Object.keys(element.attributes)) {
    if (TABLE_ROW_PROPS_SKIP_ATTRS.has(name)) continue;
    const value = element.attributes[name];
    if (!isRowBoundExpression(value)) continue;

    const exp = transformTableRowPropExpression(value.substring(5).trim());
    if (name === "show") {
      parts.push(`show: (${exp} || false)`);
    } else {
      parts.push(`${name}: ${exp}`);
    }
    toRemove.push(name);
  }

  toRemove.forEach(attr => element.removeAttribute(attr));
  if (parts.length === 0) return "";
  return `tableRowProps={(row: any) => ({${parts.join(", ")}})}`;
}

export function transformTableColumnClassExpression(expression: string): string {
  if (!expression) return "";

  // Replace fragment.row, fragment?.row with rowData
  let transformed = expression.replace(/fragment\??\.row/g, "rowData");

  // Replace standalone row. (word boundary to avoid matching "error" or "arrow")
  transformed = transformed.replace(/\brow\./g, "rowData.");

  // Replace standalone row[ (bracket notation, word boundary to avoid matching "arrow")
  transformed = transformed.replace(/\brow\[/g, "rowData[");

  // Apply optional chaining
  transformed = addOptionalChaining(transformed);

  // Remove optional chaining only between method name and parentheses (e.g., getProperty?.( -> getProperty()
  // Keep optional chaining on the object (e.g., rowData?.getProperty stays as is)
  transformed = transformed.replace(/(\w+)\?\.\s*\(/g, "$1(");

  // Normalize double quotes to single quotes in string literals
  transformed = transformed.replace(/"([^"]*)"/g, "'$1'");

  return transformed;
}

/**
 * Builds a React cell expression from table column format attributes.
 * Mirrors Angular table-column.build.ts getFormatExpression().
 */
export function getFormatCellExpression(
  element: HTMLElement,
  context?: { get?: (key: string) => unknown }
): string | null {
  const binding = element.getAttribute("binding");
  if (!binding || binding === "rowOperations") {
    return null;
  }

  let formatPattern =
    element.getAttribute("custompipeformat") || element.getAttribute("formatpattern");
  if (!formatPattern || formatPattern === "None") {
    return null;
  }

  const columnValue = `row.getProperty('${binding}')`;
  let pipeExpression = "";

  // getFormatExpression() switch — built-in patterns pull their
  // arguments from their own dedicated attributes (currencypattern, fractionsize, ...).
  switch (formatPattern) {
    case "toCurrency": {
      const currencyPattern = element.getAttribute("currencypattern");
      if (currencyPattern) {
        const fractionSize = element.getAttribute("fractionsize");
        pipeExpression = fractionSize
          ? `${columnValue} | toCurrency: '${currencyPattern}': ${fractionSize}`
          : `${columnValue} | toCurrency: '${currencyPattern}'`;
      }
      break;
    }
    case "numberToString": {
      const fractionSize = element.getAttribute("fractionsize");
      if (fractionSize) {
        pipeExpression = `${columnValue} | numberToString: '${fractionSize}'`;
      }
      break;
    }
    case "stringToNumber":
      pipeExpression = `${columnValue} | stringToNumber`;
      break;
    case "timeFromNow":
      pipeExpression = `${columnValue} | timeFromNow`;
      break;
    case "prefix": {
      const prefix = element.getAttribute("prefix");
      if (prefix) {
        pipeExpression = `${columnValue} | prefix: '${prefix}'`;
      }
      break;
    }
    case "suffix": {
      const suffix = element.getAttribute("suffix");
      if (suffix) {
        pipeExpression = `${columnValue} | suffix: '${suffix}'`;
      }
      break;
    }
    default:
      if (checkIsCustomPipeExpression(formatPattern)) {
        pipeExpression = `${columnValue} | ${formatPattern} : row`;
      }
      break;
  }

  if (!pipeExpression) {
    return null;
  }

  let transformed = transformEx(pipeExpression, "fragment", "attr");
  transformed = transformed.replace(/fragment\??\.row/g, "rowData");
  transformed = transformed.replace(/\brow\./g, "rowData.");
  transformed = transformed.replace(/\brow\b(?![a-zA-Z_$0-9])/g, "rowData");
  transformed = resolveFormatContext(transformed, context);
  transformed = addOptionalChaining(transformed);
  transformed = transformed.replace(/(\w+)\?\.\s*\(/g, "$1(");

  return transformed;
}

/**
 * A `dataset` binding that resolves to a variable's `dataSet`, decomposed into the
 * pieces the table needs to derive `datasource` / `binddataset`.
 */
export interface VariableDataSetBinding {
  /** Scope path in dot notation: `Variables` | `App.activePage.Variables` | `App.Variables`. */
  scopePath: string;
  /** Variable-instance expression with optional chaining, e.g. `fragment?.Variables?.[fragment?.x]`. */
  datasourceExpr: string;
  /** Variable name when the key is static (dot access or a quoted literal); undefined when computed. */
  variableName?: string;
}

/** `Variables` reachable locally, on the active page, or on the app — with or without `?.`. */
const VARIABLES_SCOPE_PREFIX =
  /^bind:fragment(?:\?\.|\.)((?:App(?:\?\.|\.)(?:activePage(?:\?\.|\.))?)?Variables)/;

/** Index of the `]` closing the `[` at `start`, honouring nesting and quoted strings; -1 if unbalanced. */
function findClosingBracket(value: string, start: number): number {
  let depth = 0;
  let quote: string | null = null;
  for (let i = start; i < value.length; i++) {
    const ch = value[i];
    if (quote) {
      if (ch === "\\") i++;
      else if (ch === quote) quote = null;
      continue;
    }
    if (ch === "'" || ch === '"' || ch === "`") {
      quote = ch;
    } else if (ch === "[") {
      depth++;
    } else if (ch === "]") {
      depth--;
      if (depth === 0) return i;
    }
  }
  return -1;
}

/**
 * Parses a post-preTranspile `dataset` value that points at a variable's `dataSet`, so the table
 * can derive a matching `datasource`/`binddataset` and run server-side pagination. Without this a
 * table bound via `App.activePage` falls back to client-side pagination of only the loaded server
 * page, diverging from the page's own server-side table.
 *
 * Handles both a static key (`Variables.orders.dataSet`, `Variables["orders"].dataSet`) and a
 * computed one (`Variables[fragment.pageParams.dataSetName].dataSet`) — the latter is how a
 * partial/prefab binds to a variable chosen at runtime. Any suffix after `.dataSet` (`.content`,
 * `[0]`, …) is allowed; the returned expression stays pointed at the variable itself.
 */
export function parseVariableDataSetBinding(value: string): VariableDataSetBinding | undefined {
  const prefix = VARIABLES_SCOPE_PREFIX.exec(value);
  if (!prefix) {
    return undefined;
  }
  const scopePath = prefix[1].replace(/\?\./g, ".");
  let index = prefix[0].length;

  // Consume the separator, if any: `Variables.name`, `Variables?.name`, `Variables[expr]`.
  let sawSeparator = false;
  if (value.startsWith("?.", index)) {
    index += 2;
    sawSeparator = true;
  } else if (value[index] === ".") {
    index += 1;
    sawSeparator = true;
  }

  let accessor: string;
  let variableName: string | undefined;
  if (value[index] === "[") {
    const close = findClosingBracket(value, index);
    if (close < 0) {
      return undefined;
    }
    const key = value.slice(index + 1, close).trim();
    accessor = `[${key}]`;
    // A quoted literal key is as static as dot access — keep treating it as a known name.
    const quote = key[0];
    const isQuotedLiteral =
      (quote === "'" || quote === '"') && key.length > 1 && key[key.length - 1] === quote;
    variableName = isQuotedLiteral ? key.slice(1, -1) : undefined;
    index = close + 1;
  } else {
    const identifier = /^[A-Za-z_$][A-Za-z0-9_$]*/.exec(value.slice(index));
    if (!identifier || !sawSeparator) {
      return undefined;
    }
    accessor = `.${identifier[0]}`;
    variableName = identifier[0];
    index += identifier[0].length;
  }

  // The variable access must be followed by `.dataSet` on a property boundary, so that
  // sibling props such as `.dataSetName` or `.dataSetSize` are not mistaken for it.
  if (!/^(?:\?\.|\.)dataSet(?![A-Za-z0-9_$])/.test(value.slice(index))) {
    return undefined;
  }

  const datasourceExpr = addOptionalChainingToPropertyPath(
    `fragment.${scopePath}${accessor}`.replace(/\?\./g, ".")
  );
  return { scopePath, datasourceExpr, variableName };
}
