import { HTMLElement } from "node-html-parser";

import {
  createExpression,
  Import,
  transformAttrs,
  Transformer,
  TranspilationContext,
} from "../../transpile";
import { extractDatasetInfo } from "../utils";

export const imports: Import[] = [
  { name: "WmSwitch", from: "@wavemaker-ai/react-runtime/components/input/default/switch" },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    let getDisplayExpression = createExpression(element, "displayexpression");
    if (getDisplayExpression) {
      element.removeAttribute("displayexpression");
    }
    const isFormField = element.getAttribute("formfield") === "true";
    return `<WmSwitch ${isFormField ? " {...$formField}" : ""} listener={fragment} ${extractDatasetInfo(element)} ${transformAttrs(element, context)} ${getDisplayExpression ? `displayExpression=${getDisplayExpression}` : ""} >`;
  },
  post: (element: HTMLElement) => "</WmSwitch>",
  imports: (element: HTMLElement) => imports,
} as Transformer;
