import { HTMLElement } from "node-html-parser";

import {
  parse,
  createComponent,
  Import,
  isHTMLElement,
  transformAttrs,
  Transformer,
  TranspilationContext,
} from "../../transpile";
import { transformRepeatChildData, transformRepeatChildAttr, findElement } from "../utils";

export const imports: Import[] = [
  { name: "WmTabs", from: "@wavemaker-ai/react-runtime/components/container/tabs" },
];

const transformAttr = (name: string, value: string) => {
  if (name === "itemclass") {
    return value.replace(/fragment\.item/g, "item").replace(/fragment\.index/g, "index");
  }
  return value;
};
export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    // Set index on tabpane children
    let i = 0;
    element.childNodes.forEach(c => {
      if (isHTMLElement(c) && c.rawTagName === "wm-tabpane") {
        c.setAttribute("index", "" + i++);
      }
    });

    const dynamic = element.getAttribute("type") === "dynamic";
    const widgetName = element.getAttribute("name") || "tabs";

    if (dynamic) {
      const dataSet = element.getAttribute("dataset") || "";
      const repeatTemplate = parse(
        `<wm-list-content name="${widgetName + "Item"}"></wm-list-content>`
      ).firstChild as HTMLElement;

      // Store all children before removing them
      const children = [...element.childNodes];
      const firstElementChild = children.find((c): c is HTMLElement => isHTMLElement(c)) as
        | HTMLElement
        | undefined;
      const firstChildIsRepeatTemplate = firstElementChild?.rawTagName === "wm-repeat-template";
      context.set("tabsFirstChildIsRepeatTemplate", firstChildIsRepeatTemplate);

      if (repeatTemplate) {
        // Move all children to the repeat template
        repeatTemplate.childNodes = children;

        // Ensure each wm-tabpane inside dynamic tabs receives index={$index}
        findElement(repeatTemplate as HTMLElement, "WM-TABPANE", (e: HTMLElement) => {
          e.setAttribute("index", "bind:$index");
        });

        transformRepeatChildAttr(
          repeatTemplate as HTMLElement,
          `fragment.Widgets.${widgetName}.currentItemWidgets`,
          "currentItemWidgets"
        );
        transformRepeatChildData(
          repeatTemplate as HTMLElement,
          `fragment.Widgets.${widgetName}.currentItem`,
          "currentItem"
        );
        transformRepeatChildAttr(repeatTemplate as HTMLElement, "fragment.item", "$item");
        transformRepeatChildAttr(repeatTemplate as HTMLElement, "fragment.index", "$index");
        transformRepeatChildData(
          repeatTemplate as HTMLElement,
          dataSet.substring(5) + "[0]",
          "list_item",
          true,
          widgetName
        );
        transformRepeatChildData(
          repeatTemplate as HTMLElement,
          dataSet.substring(5) + "[$i]",
          "list_item",
          true,
          widgetName
        );

        // Get the children content after transformation
        repeatTemplate.childNodes = element.childNodes;
        element.childNodes = [repeatTemplate];

        const renderWrapper = firstChildIsRepeatTemplate ? "" : "<> ";
        return `<WmTabs listener={fragment} ${transformAttrs(element, context, transformAttr)} render={($item:Record<string, any>, $index:number, data:Record<string, any>[]) => (${renderWrapper}`;
      }
    }

    return `<WmTabs listener={fragment} ${transformAttrs(element, context)}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => {
    if (element.getAttribute("type") === "dynamic") {
      const useRepeatTemplate = context.get("tabsFirstChildIsRepeatTemplate");
      return useRepeatTemplate ? ")}/>" : " </>)}/>";
    }
    return "</WmTabs>";
  },
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
  createComponent: (element: HTMLElement, context: TranspilationContext) => {
    if (!context.data.listCount) {
      context.props = context.get("old_props") || [];
    }
    const componentMarkup = createComponent(element, context);
    context.props = [];
    return componentMarkup;
  },
} as Transformer;
