import { HTMLElement } from "node-html-parser";

import {
  createComponent,
  Import,
  Transformer,
  transformAttrs,
  TranspilationContext,
} from "../../transpile";

const PAGE_EVENT_ATTRS = [
  "on-attach",
  "on-detach",
  "on-destroy",
  "on-orientationchange",
  "on-resize",
] as const;

const PAGE_EVENT_KEYS = ["attach", "detach", "destroy", "orientationchange", "resize"] as const;

/** Events that receive (event, widget, data) - others receive (event, widget) */
const THREE_ARG_EVENTS = new Set(["orientationchange", "resize"]);

export const imports: Import[] = [
  {
    name: "WmPage",
    from: "@wavemaker-ai/react-runtime/components/page",
  },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const pageEvents: Record<string, string> = {};
    PAGE_EVENT_ATTRS.forEach((attr, i) => {
      const value = element.getAttribute(attr);
      if (value) {
        const key = PAGE_EVENT_KEYS[i];
        const args = THREE_ARG_EVENTS.has(key) ? "($event, widget, data)" : "($event, widget)";
        pageEvents[key] = `${args} => { ${value} }`;
        element.removeAttribute(attr);
      }
    });
    // remove any other unnecssary event
    Object.keys(element.attributes).forEach(attr => {
      if (attr.startsWith("on-")) {
        if (!PAGE_EVENT_ATTRS.includes(attr as any)) {
          element.removeAttribute(attr);
        }
      }
    });
    if (Object.keys(pageEvents).length > 0) {
      (context.result as any).pageEvents = pageEvents;
    }
    // the layout shared by a group of pages drops this tag, so the title travels with the page's own content
    const pagetitle = element.getAttribute("pagetitle");
    if (pagetitle) {
      element.querySelector("wm-page-content")?.setAttribute("pagetitle", pagetitle);
    }
    return `<WmPage ${transformAttrs(element, context)} >`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "</WmPage>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
  createComponent: (element: HTMLElement, context: TranspilationContext) =>
    createComponent(element, context),
} as Transformer;
