import { HTMLElement } from "node-html-parser";

import {
  createExpression,
  Import,
  transformAttrs,
  Transformer,
  TranspilationContext,
} from "../../transpile";
import { extractDatasetInfo, getOnChangeExprforFormWidget } from "../utils";

export const imports: Import[] = [
  {
    name: "WmCheckboxset",
    from: "@wavemaker-ai/react-runtime/components/input/default/checkboxset",
  },
  {
    name: "WmPartialContainer",
    from: "@wavemaker-ai/react-runtime/components/page/partial-container",
  },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    // transformItemsPerRow(element);
    let getDisplayExpression = createExpression(element, "displayexpression");
    if (getDisplayExpression) {
      element.removeAttribute("displayexpression");
    }
    const onChange = getOnChangeExprforFormWidget(element, "on-change", context);
    const isFormField = element.getAttribute("formfield") === "true";
    return `<WmCheckboxset ${isFormField ? " {...$formField}" : ""} listener={fragment} ${extractDatasetInfo(element)} ${transformAttrs(element, context)} ${getDisplayExpression ? `getDisplayExpression=${getDisplayExpression}` : ""} ${onChange ? `onChange={${onChange}}` : ""}>`;
  },
  post: (element: HTMLElement) => "</WmCheckboxset>",
  imports: (element: HTMLElement) => imports,
} as Transformer;
