import { HTMLElement } from "node-html-parser";

import { Import, transformAttrs, Transformer, TranspilationContext } from "../../transpile";
import {
  getOnChangeExpr,
  getFormSubmitExpr,
  getFormSuccessExpr,
  setFormActions,
} from "./live-form-shared";

export const imports: Import[] = [
  { name: "WmLiveForm", from: "@wavemaker-ai/react-runtime/components/data/live-form" },
];

const FORM_ACTION_TAGS = ["wm-form-action"];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const onChange = getOnChangeExpr(element, {
      variableRegex: /fragment\.Variables\??\.[^.?]+/g,
      inheritPrefabParentForm: true,
    });
    const formSubmit = getFormSubmitExpr(element);
    const formSuccess = getFormSuccessExpr(element);
    const datasetAttr = element.getAttribute("dataset");
    const datasourceAttr = element.getAttribute("datasource");
    if (
      !datasourceAttr &&
      datasetAttr &&
      datasetAttr.startsWith("bind:fragment.Variables.") &&
      datasetAttr.endsWith(".dataSet")
    ) {
      const match = datasetAttr.match(/^bind:fragment\.Variables\.([^.]+)\.dataSet$/);
      if (match) {
        const variableName = match[1];
        element.setAttribute("datasource", `{fragment?.Variables?.${variableName}}`);
      }
    }
    setFormActions(element, context, FORM_ACTION_TAGS);
    return `<WmLiveForm listener={fragment} ${transformAttrs(element, context)} 
      ${onChange ? `onChange={${onChange}}` : ""}
      ${formSuccess ? `formSuccess={${formSuccess}}` : ""}
      ${formSubmit ? `formSubmit={${formSubmit}}` : ""}
      ${datasourceAttr ? `datasource={${datasourceAttr}}` : ""}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => `</WmLiveForm>`,
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
