import { HTMLElement } from "node-html-parser";

import { Import, Transformer, TranspilationContext } from "../../../transpile";
import { capitalize } from "lodash";

export const imports: Import[] = [];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => ``,
  post: (element: HTMLElement, context: TranspilationContext) => "",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
  createComponent: (e: HTMLElement, context: TranspilationContext, component = "list") => {
    const result = context.result;
    const widgetName = capitalize(e.attrs["name"]);
    result.components[widgetName] = `React.memo(({$item, $index, ${component}, fragment}) => {
          const item = $item;
          const [currentItemWidgets] = React.useState({});
          ${component}.itemWidgets = ${component}.itemWidgets || [];
          ${component}.itemWidgets[$index] = currentItemWidgets;
          const [listener] = React.useState({
            onComponentInit: (c) => {
              currentItemWidgets[c.name] = c;
              fragment.onComponentInit(c);
            },
            onComponentDestroy: (c) => {
              fragment.onComponentDestroy(c);
              delete currentItemWidgets[c.name];
            }
          });
          const { watch } = useWatcher(fragment.watcher);
          return (${result.markup});
      })`;
    result.markup = `<${widgetName} $item={$item} $index={$index} ${component}={${component}} key={$index} fragment={fragment}/>`;
    return result;
  },
} as Transformer;
