import {
  AST,
  Binary,
  BindingPipe,
  Chain,
  Conditional,
  ImplicitReceiver,
  KeyedRead,
  Lexer,
  LiteralArray,
  LiteralMap,
  LiteralPrimitive,
  MethodCall,
  Parser,
  PrefixNot,
  PropertyRead,
  PropertyWrite,
  SafePropertyRead,
  SafeMethodCall,
  SafeKeyedRead,
} from "@angular/compiler";
import { isString } from "lodash";
import { convertHyphenatedPropsToBracketNotation, splitTopLevel } from "../utils.browser";

const STR_ESCAPE_REGEX = /[^ a-zA-Z0-9]/g;
export const FORMAT_CONTEXT = "{formatContext:''}";
const FORMAT_CONTEXT_REGEX = /\{formatContext:''\}/g;

/** Identifiers in args that must keep `fragment.` in event mode (scoped to page fragment). */
export const FRAGMENT_SCOPED_NAMES = ["appLocale", "Variables", "App"];

/** Identifiers available as local variables in list item scope — must NOT be prefixed with ctx. */
const LIST_SCOPE_VARS = new Set(["currentItemWidgets"]);

/** Standard JS globals — referenced/called directly, never prefixed with ctx. */
const JS_GLOBALS = new Set([
  "Number",
  "String",
  "Boolean",
  "Array",
  "Object",
  "Date",
  "Math",
  "JSON",
  "RegExp",
  "Promise",
  "Symbol",
  "BigInt",
  "parseInt",
  "parseFloat",
  "isNaN",
  "isFinite",
  "encodeURIComponent",
  "decodeURIComponent",
  "encodeURI",
  "decodeURI",
]);

export class ExpressionTransformer {
  constructor(
    private ctx = "this",
    private mode: "attr" | "event" = "attr"
  ) {}

  processImplicitReceiver(ast: ImplicitReceiver) {
    return this.ctx;
  }

  processLiteralPrimitive(ast: LiteralPrimitive) {
    return isString(ast.value) ? JSON.stringify(ast.value) : ast.value;
  }

  processLiteralArray(ast: LiteralArray) {
    const s = [];
    for (const item of ast.expressions) {
      s.push(this.build(item));
    }
    return `[${s.join(",")}]`;
  }

  processLiteralMap(ast: LiteralMap) {
    const _values = [] as any[];
    for (const _value of ast.values) {
      _values.push(this.build(_value));
    }
    return `{${ast.keys.map((k, i) => `'${k.key}':${_values[i]}`)}}`;
  }

  processPropertyRead(ast: PropertyRead) {
    if (
      this.mode === "event" &&
      ast.receiver instanceof ImplicitReceiver &&
      ast.name === "$event"
    ) {
      return "$event";
    }
    if (
      ast.receiver instanceof ImplicitReceiver &&
      (LIST_SCOPE_VARS.has(ast.name) || JS_GLOBALS.has(ast.name))
    ) {
      return ast.name;
    }
    const r = this.build(ast.receiver);
    return `${r}.${ast.name}`;
  }

  processSafePropertyRead(ast: SafePropertyRead) {
    if (
      ast.receiver instanceof ImplicitReceiver &&
      (LIST_SCOPE_VARS.has(ast.name) || JS_GLOBALS.has(ast.name))
    ) {
      return ast.name;
    }
    const r = this.build(ast.receiver);
    return `${r}?.${ast.name}`;
  }

  processKeyedRead(ast: KeyedRead) {
    const k = this.build(ast.key);
    const o = this.build(ast.receiver);
    return `${o}[${k}]`;
  }

  processSafeKeyedRead(ast: SafeKeyedRead) {
    const k = this.build(ast.key);
    const o = this.build(ast.receiver);
    return `${o}?.[${k}]`;
  }

  processPrefixNot(ast: PrefixNot) {
    const r = this.build(ast.expression);
    return `!(${r})`;
  }

  processBinary(ast: Binary) {
    const l = this.build(ast.left);
    const r = this.build(ast.right);
    // Angular parser represents unary negative (e.g. -5) as Binary(0, '-', 5).
    // Emit clean negative literal instead of (0-5).
    if (
      ast.operation === "-" &&
      ast.left instanceof LiteralPrimitive &&
      ast.left.value === 0 &&
      ast.right instanceof LiteralPrimitive &&
      typeof ast.right.value === "number"
    ) {
      return String(-ast.right.value);
    }
    return `(${l}${ast.operation}${r})`;
  }

  processConditional(ast: Conditional) {
    const condition = this.build(ast.condition);
    const trueExp = this.build(ast.trueExp);
    const falseExp = this.build(ast.falseExp);
    return `(${condition}?${trueExp}:${falseExp})`;
  }

  processChain(ast: Chain) {
    return ast.expressions.map(e => this.build(e)).join(";");
  }

  processPropertyWrite(ast: PropertyWrite) {
    let receiver, lhs;
    if (ast.receiver instanceof ImplicitReceiver) {
      lhs = `${this.ctx}.${ast.name}`;
    } else {
      receiver = this.build(ast.receiver);
      lhs = `${receiver}${receiver.length ? "." : ""}${ast.name}`;
    }

    const rhs = this.build(ast.value);
    return `${lhs} = ${rhs}`;
  }

  private buildCallArgs(args: AST[]): any[] {
    const _args = [];
    for (const arg of args) {
      let argExp = this.build(arg);
      const fragmentScoped =
        typeof argExp === "string" &&
        FRAGMENT_SCOPED_NAMES.some(name => name !== this.ctx && argExp.includes(name));
      if (this.mode === "event" && !fragmentScoped && argExp.replace) {
        argExp = argExp.replace(`${this.ctx}.`, "");
      }
      _args.push(argExp);
    }
    return _args;
  }

  processMethodCall(ast: MethodCall) {
    const _args = this.buildCallArgs(ast.args);
    if (ast.receiver instanceof ImplicitReceiver && JS_GLOBALS.has(ast.name)) {
      return `${ast.name}(${_args.join(",")})`;
    }
    const fn = this.build(ast.receiver);
    if (_args.includes("currentItemWidgets")) {
      _args.forEach((arg, index) => {
        if (arg === "currentItemWidgets") {
          _args[index] = "currentItemWidgetsRef.current";
        }
      });
    }
    return `${fn}?.${ast.name}?.(${_args.join(",")})`;
  }

  processSafeMethodCall(ast: SafeMethodCall) {
    const _args = this.buildCallArgs(ast.args);
    if (ast.receiver instanceof ImplicitReceiver && JS_GLOBALS.has(ast.name)) {
      return `${ast.name}(${_args.join(",")})`;
    }
    const fn = this.build(ast.receiver);
    return `${fn}?.${ast.name}?.(${_args.join(",")})`;
  }

  processPipe(ast: BindingPipe) {
    let name = ast.name;
    const _args = [];
    const exp = this.build(ast.exp);
    for (const arg of ast.args) {
      const argExp = this.build(arg);
      _args.push(argExp === "" ? "undefined" : argExp);
    }
    if (_args[0] && name === "custom") {
      name = `custom.${_args[0]}`.replace(/"/g, "");
      _args.shift();
    }
    if (name === "currency") {
      name = "toCurrency";
    }
    if (name === "toCurrency" && _args.length === 1) {
      _args.push("undefined");
    }
    _args.unshift(exp);
    return `${this.ctx}?.formatters?.get('${name}')?.format(${_args}, ${FORMAT_CONTEXT})`;
  }

  build(ast: AST): string {
    if (ast instanceof ImplicitReceiver) {
      return this.processImplicitReceiver(ast as ImplicitReceiver);
    } else if (ast instanceof LiteralPrimitive) {
      return this.processLiteralPrimitive(ast as LiteralPrimitive);
    } else if (ast instanceof LiteralArray) {
      return this.processLiteralArray(ast as LiteralArray);
    } else if (ast instanceof LiteralMap) {
      return this.processLiteralMap(ast as LiteralMap);
    } else if (ast instanceof SafePropertyRead) {
      return this.processSafePropertyRead(ast as SafePropertyRead);
    } else if (ast instanceof PropertyRead) {
      return this.processPropertyRead(ast as PropertyRead);
    } else if (ast instanceof PropertyWrite) {
      return this.processPropertyWrite(ast as PropertyWrite);
    } else if (ast instanceof SafeKeyedRead) {
      return this.processSafeKeyedRead(ast as SafeKeyedRead);
    } else if (ast instanceof KeyedRead) {
      return this.processKeyedRead(ast as KeyedRead);
    } else if (ast instanceof PrefixNot) {
      return this.processPrefixNot(ast as PrefixNot);
    } else if (ast instanceof Binary) {
      return this.processBinary(ast as Binary);
    } else if (ast instanceof Conditional) {
      return this.processConditional(ast as Conditional);
    } else if (ast instanceof SafeMethodCall) {
      return this.processSafeMethodCall(ast as SafeMethodCall);
    } else if (ast instanceof MethodCall) {
      return this.processMethodCall(ast as MethodCall);
    } else if (ast instanceof Chain) {
      return this.processChain(ast as Chain);
    } else if (ast instanceof BindingPipe) {
      return this.processPipe(ast as BindingPipe);
    }
    return "";
  }
}

const transform = (expr: string, scopeName = "this", mode: "event" | "attr" = "attr"): string => {
  expr = expr && expr.trim();
  if (!expr || !expr.length) {
    return "";
  }
  expr = convertHyphenatedPropsToBracketNotation(expr);
  try {
    const parser = new Parser(new Lexer());
    // Split on top-level ';' — semicolons inside string literals or nested parens/
    // brackets/braces (e.g. CSS text like '<pre style="word-break: break-all;">')
    // are not statement separators and must not be split on.
    let expressions = splitTopLevel(expr, ";"),
      transformedExpressions: any = [];
    const $iExp = new RegExp("\\[" + scopeName + "\\.\\$i\\]", "g");

    expressions.forEach((currentExp: any) => {
      const ast = parser.parseBinding(currentExp, "", 0);
      let exp = new ExpressionTransformer(scopeName, mode).build(ast.ast);
      if (typeof exp === "string") {
        exp = exp.replace($iExp, "[0]");
      }
      transformedExpressions.push(exp);
    });
    return transformedExpressions.join(";");
  } catch (e: any) {
    console.error(`failed to parse ${expr}`);
    throw new Error(e);
  }
};

export default transform;

() => {
  const i = `Variables.callme($event)`;
  const s = transform(i);
  console.log(i + " : \n " + s);
};

/** Replaces the pipe placeholder emitted by processPipe with the correct format() context arg. */
export function resolveFormatContext(
  expression: string,
  context?: { get?: (key: string) => unknown }
): string {
  if (context?.get?.("isInsideList")) {
    return expression.replace(FORMAT_CONTEXT_REGEX, "$item");
  }
  if (context?.get?.("isInsideTableColumn")) {
    return expression.replace(FORMAT_CONTEXT_REGEX, "rowData");
  }
  return expression.replace(/,\s*\{formatContext:''\}/g, "").replace(FORMAT_CONTEXT_REGEX, "");
}
