class NumericParser extends Parser {
  parse(value: string) {
    // The value parameter should be used instead of an empty dimensionVal
    if (isString(value) && value.endsWith("%")) {
      return `{'${value}'}`;
    }
    // Convert to number to ensure valid JavaScript (removes leading zeros)
    const numValue = Number(value);
    return `{${numValue}}`;
  }

  parseBind(value: string) {
    return `toNumber(${value})`;
  }
}
class BooleanParser extends Parser {
  parse(value: string): string {
    if (value === "true" || value === "false") {
      return `{${value === "true"}}`;
    }
    return super.parse(value);
  }

  parseBind(value: any) {
    return value == "true" ? true : value == "false" ? false : value;
  }
}
class ArrayParser extends Parser {
  parse(value: string): string {
    if (!isNaN(Number(value))) {
      return `{${value}}`;
    }
    if (value.indexOf(",") > 0) {
      return `{[${value
        .split(",")
        .map(v => (isNaN(Number(v)) ? `"${v}"` : v))
        .join(",")}]}`;
    }
    return super.parse(value);
  }

  parseBind(value: string) {
    return super.parseBind(value);
  }
}

class UnitParser extends Parser {
  parse(value: string): string {
    const SIZE_UNITS = ["px", "em", "rem", "%", "vh", "vw", "cm", "mm", "in", "pt", "pc"];
    function hasSizeUnit(value: string): boolean {
      return SIZE_UNITS.some((unit: string) => value.toLowerCase().endsWith(unit));
    }
    const numericValue = parseFloat(value);
    if (!isNaN(numericValue) && !hasSizeUnit(value)) {
      return `"${numericValue}px"`;
    }
    return `"${value}"`;
  }

  parseBind(value: string): string {
    return value;
  }
}

