export const parseProperty = (
  value: string,
  propertyName: string,
  widgetName: string,
  runtime = false
) => {
  if (isUndefined(value)) {
    return `""`;
  }
  let parser = PARSER_MAP.get(widgetName)?.get(propertyName);
  parser = parser || PARSER_MAP.get("base")?.get(propertyName);
  if (parser) {
    return runtime ? parser.parseBind(value) : parser.parse(value);
  }
  return runtime ? STRING_PARSER.parseBind(value) : STRING_PARSER.parse(value);
};
