/**
 * Naming helpers shared by the generation side (service.generator.ts) and the consumption side
 * (variable.transformer.ts). Schema-to-TypeScript conversion itself now lives in
 * model-emitter.ts, which emits a service's `definitions` block once as shared models rather
 * than re-deriving types per operation.
 */

export function toPascalCase(name: string): string {
  const words = String(name || "")
    .split(/[^a-zA-Z0-9]+/)
    .filter(Boolean);
  if (!words.length) return "Model";
  let result = words.map(w => w.charAt(0).toUpperCase() + w.slice(1)).join("");
  if (/^[0-9]/.test(result)) result = "_" + result;
  return result;
}

/**
 * Single source of truth for turning (backend service id, tag) into a generated class name —
 * used by BOTH the generation side (service.generator.ts, which emits the class) and the
 * consumption side (variable.transformer.ts, which must predict that exact name so
 * isServiceAvailable() doesn't silently reject a variable). The two MUST never drift apart.
 *
 * The name is the tag alone (e.g. "Department" -> "DepartmentService"), because each service's
 * classes live in their own `services/<serviceId>/` folder — the folder already says which
 * backend service a class belongs to, so repeating it in the class name only makes both the file
 * and the class name longer for no added information. Two services that share an entity name
 * (e.g. an "Employee" in both hrdb and salesdb) therefore produce the same class NAME in two
 * different folders, which is fine on disk and at import time; where both are imported into one
 * generated file, the import is aliased (see service.generator.ts's singleton naming).
 *
 * `tag` must already be cleaned/capitalized by the caller (e.g. "Department", not
 * "DepartmentController").
 */
export function buildServiceClassName(serviceId: string, tag: string): string {
  const servicePascal = toPascalCase(serviceId || "");
  const serviceCore = servicePascal.endsWith("Service")
    ? servicePascal.slice(0, -"Service".length)
    : servicePascal;
  // A tag equal to the service's own name is the "one class for the whole service" case (an
  // OpenAPIService connector whose operations are all lumped together, or a single-tag service
  // like securityService/SecurityController) — it still resolves to just "<Name>Service".
  const core = tag === servicePascal || tag === serviceCore ? serviceCore : tag;
  return `${core}Service`;
}
