import { forEach } from "lodash";
import { HTMLElement } from "node-html-parser";

import { isHTMLElement, parse, TranspilationContext } from "../../transpile";

export const getDataSetExpr = (element: HTMLElement, bindExpr: any) => {
  return element.getAttribute("isLogin") ? "" : `${bindExpr}[widget.props.name] = newVal;`;
};

export const getFormSubmitExpr = (element: HTMLElement) => {
  const dataset = element.getAttribute("dataset");
  if (dataset) {
    const variableArr = dataset.match(/(fragment)+\.Variables\.[^\.]+/g);
    if (variableArr && variableArr.length) {
      let variable = variableArr[0];
      return `
      (formData, operationType, success, error) => {
        if (${variable}) {
            switch (operationType) {
                case 'insert':
                    return ${variable}.insertRecord(formData, success, error);
                case 'update':
                    return ${variable}.updateRecord(formData, success, error);
                case 'delete':
                    return ${variable}.deleteRecord(formData, success, error);
                default:
                    return ${variable}.listRecords(formData, success, error);
            }
        }
      }
    `;
    }
  }
};

export const getFormSuccessExpr = (element: HTMLElement) => {
  const dataset = element.getAttribute("dataset");
  if (dataset) {
    const variableArr = dataset.match(/(fragment)+\.Variables\.[^\.]+/g);
    if (variableArr && variableArr.length) {
      let variable = variableArr[0];
      return `
              (formData, success, error) => {
                ${variable} && ${variable}.listRecords(formData, success, error);
              }
            `;
    }
  }
};

export interface OnChangeOptions {
  variableRegex: RegExp;
  inheritPrefabParentForm?: boolean;
}

export const getOnChangeExpr = (element: HTMLElement, options: OnChangeOptions) => {
  const formDataSet = element.getAttribute("dataset")?.split(":") || [];
  let bindExpr = formDataSet?.length > 1 ? formDataSet[1] : null;
  if (!bindExpr || bindExpr?.includes("Widgets")) {
    return "";
  }
  let currentNode = element.parentNode;
  const variableArr = bindExpr.match(options.variableRegex);
  const variableName = variableArr && variableArr.length ? variableArr[0] : null;
  while (currentNode) {
    if (currentNode.rawTagName === "wm-liveform") {
      element.setAttribute("parentForm", currentNode.getAttribute("name") || "");
      // assigning child form name.
      element.setAttribute("childdatasetnode", element.getAttribute("name") || "");
      break;
    } else if (
      options.inheritPrefabParentForm &&
      (currentNode.rawTagName === "wm-prefab" || currentNode.rawTagName === "wm-prefab-container")
    ) {
      const prefabParentForm = currentNode.getAttribute("parentForm");
      if (prefabParentForm) {
        element.setAttribute("parentForm", prefabParentForm);
      }
    }
    currentNode = currentNode.parentNode;
  }
  return `
      ($event, widget, newVal, oldVal) => {
        if(${variableName}?.twoWayBinding && newVal !== oldVal) {
          ${bindExpr !== null ? getDataSetExpr(element, bindExpr) : ""}
        }
      }
    `;
};

export const removeFormActionNodes = (element: any, actionTags: string[]) => {
  if (element.childNodes.length) {
    forEach(element.childNodes, n => {
      if (isHTMLElement(n) && actionTags.includes(n.rawTagName)) {
        n.remove();
      } else {
        removeFormActionNodes(n, actionTags);
      }
    });
  }
};

export const pluckFormActionNodes = (
  element: any,
  actionTags: string[],
  actions: HTMLElement[] = []
) => {
  if (element.childNodes.length) {
    forEach(element.childNodes, n => {
      if (isHTMLElement(n) && n.rawTagName === "wm-form") {
        return;
      } else if (isHTMLElement(n) && actionTags.includes(n.rawTagName)) {
        actions.push(n);
        n.remove();
      } else {
        pluckFormActionNodes(n, actionTags, actions);
      }
    });
    return actions;
  }
};

export const setFormActions = (
  element: HTMLElement,
  context: TranspilationContext,
  actionTags: string[]
) => {
  const formActions: any = pluckFormActionNodes(element, actionTags);

  const formFooter = parse(`<wm-form-footer></wm-form-footer>`).firstChild as HTMLElement;
  var btnMarkup;
  formActions.forEach((formAction: any) => {
    formAction.setAttribute("formKey", element.attrs["name"]);
    formFooter.appendChild(formAction);
  });
  const container = parse(`<wm-container class="form-elements"></wm-container>`).firstChild;
  const formBody = parse(`<wm-form-body></wm-form-body>`).firstChild;
  formBody.childNodes.push(container);
  container.childNodes = element.childNodes;
  element.childNodes = [formBody];
  if (formActions.length) {
    formBody.childNodes.push(formFooter);
  }
};
