// Static layout props extracted from element attributes
export interface StaticLayoutProps {
  direction?: string;
  alignment?: string;
  gap?: string | number;
  columngap?: string | number;
  wrap?: boolean;
  position?: string;
  positionvalue?: string;
  zindex?: string | number;
  clipcontent?: string | boolean;
  overflow?: string;
}

// Attribute groups for independent processing of flex, overflow, and position
export const FLEX_ATTR_GROUP = new Set(["direction", "alignment", "gap", "columngap", "wrap"]);
export const OVERFLOW_ATTR_GROUP = new Set(["overflow", "clipcontent"]);
export const POSITION_ATTR_GROUP = new Set(["position", "positionvalue", "zindex"]);

// Derived union of all layout attribute names
export const LAYOUT_ATTR_NAMES = new Set([
  ...FLEX_ATTR_GROUP,
  ...OVERFLOW_ATTR_GROUP,
  ...POSITION_ATTR_GROUP,
]);

// Flags indicating which attribute groups contain dynamic (bind:) values
export interface DynamicGroupFlags {
  flex: boolean;
  overflow: boolean;
  position: boolean;
}

export interface ConditionalClassExpression {
  condition: string;
  trueClasses: string;
  falseClasses: string;
}

export interface AutoLayoutClassResult {
  staticClasses: string;
  conditionalExpressions: ConditionalClassExpression[];
}

export type AutolayoutRegistry = Map<string, string>;

export interface TernaryParts {
  condition: string;
  trueValue: string;
  falseValue: string;
}

// Supported style attribute value types
export type StyleAttrType = "dimension" | "string" | "number" | "shorthand-4";

// Maps HTML attribute name → CSS property and value type
export interface StyleAttrInfo {
  cssProperty: string;
  type: StyleAttrType;
  shorthandSides?: { top: string; right: string; bottom: string; left: string };
}

