// Widget tags that receive autolayout codegen processing
export const AUTOLAYOUT_WIDGET_TAGS = new Set<string>([
  "wm-container",
  "wm-list",
  "wm-accordionpane",
  "wm-tabpane",
  "wm-page-content",
]);

// Dimension styles that width/height="fill" handling applies to (not lineheight, borderwidth, etc.)
export const FILL_SIZE_STYLE_PROPS = new Set<string>(["width", "height"]);

// Widgets that keep the literal height="fill" for the runtime's parent-aware applySize
export const LITERAL_FILL_WIDGET_TAGS = new Set<string>([
  "wm-container",
  "wm-list",
  "wm-listtemplate",
]);

// Widgets that size themselves from fill; every other widget gets no inline width/height for it
export const FILL_STYLED_WIDGET_TAGS = new Set<string>([
  ...LITERAL_FILL_WIDGET_TAGS,
  "wm-tabpane",
  "wm-accordionpane",
]);

