import { HTMLElement } from "node-html-parser";

import { Transformer, transformAttrs, TranspilationContext } from "../../transpile";
import { inferTypeAndParseProperty } from "../utils";

const capitalize = (str: string | undefined) => {
  return str
    ? str
        .split("-")
        .map(s => s.charAt(0).toUpperCase() + s.substring(1))
        .join("")
    : str;
};

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const isFormField = element.getAttribute("formfield") === "true";
    if (isFormField) {
      element.removeAttribute("formfield");
    }
    return `<WmxRenderer listener={fragment} ${transformAttrs(element, context, inferTypeAndParseProperty)} ${isFormField ? " {...$formField}" : ""}/>`;
  },
  post: () => "",
  imports: () => [
    {
      name: `WmxRenderer`,
      from: `@wavemaker-ai/react-runtime/components/wmx/WmxRenderer`,
    },
  ],
  wmxcomponents: (element: HTMLElement, context: TranspilationContext) => [
    element.getAttribute("componentname"),
  ],
} as Transformer;
