import { HTMLElement } from "node-html-parser";

import { Import, transformAttrs, Transformer, TranspilationContext } from "../../transpile";
import { withPartialContainer, getPartialImports } from "../page/with-partial-container";
import { transformRepeatChildAttr } from "../utils";

export const imports: Import[] = [
  { name: "WmTabPane", from: "@wavemaker-ai/react-runtime/components/container/tabs/tab-pane" },
];

function isInsideDynamicTabs(element: HTMLElement): boolean {
  let current: HTMLElement | null = element.parentNode as HTMLElement | null;
  while (current) {
    const tagName =
      (current as HTMLElement).rawTagName?.toLowerCase?.() ||
      (current as HTMLElement).tagName?.toLowerCase?.();
    if (tagName === "wm-tabs") {
      return (current as HTMLElement).getAttribute("type") === "dynamic";
    }
    current = current.parentNode as HTMLElement | null;
  }
  return false;
}

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const { partialAttr } = withPartialContainer(element, context, { prop: "renderPartial" });
    const isDynamicTabs = isInsideDynamicTabs(element);
    if (isDynamicTabs) {
      transformRepeatChildAttr(element, "fragment.item", "$item");
    }
    const itemProp = isDynamicTabs ? " item={$item}" : "";
    return `<WmTabPane listener={fragment} ${transformAttrs(element, context)}${itemProp} ${partialAttr}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "</WmTabPane>",
  imports: (element: HTMLElement, context: TranspilationContext) =>
    imports.concat(getPartialImports(element, context)),
} as Transformer;
