/**
 * Converts Angular-style `{{ expr }}` text interpolation into JSX expressions, mirroring
 * `transformClassWithMustacheExpressions` (which does the same for `class` attributes).
 * Each `{{ expr }}` block becomes a `{expr}` JSX expression container; surrounding static
 * text is left as plain JSX text.
 */
const convertMustacheTextToJsx = (textContent: string, isInsideTableColumn: boolean): string => {
  return textContent.replace(/\{\{([\s\S]*?)\}\}/g, (_match, rawExpr) => {
    const expr = rawExpr.trim();
    const transformed = isInsideTableColumn
      ? transformTableColumnClassExpression(expr)
      : modifyExpression(expr);
    return `{${transformed}}`;
  });
};

/**
 * Processes text content for JSX compatibility
 * If content is only special characters (like > or <), wraps them in React expressions.
 * If content contains `{{ expr }}` interpolation, converts it to a JSX expression.
 * @param textContent The raw text content from the node
 * @param isInsideTableColumn Whether this text node is inside a table column's customExpression
 * @returns Processed text content safe for JSX, or empty string if no valid content
 */
const processTextContentForJSX = (textContent: string, isInsideTableColumn = false): string => {
  const trimmedContent = textContent.trim();
  if (!trimmedContent) {
    return "";
  }

  // If content is only special characters (like > or <), wrap in React expression
  if (/^[<>&]+$/.test(trimmedContent)) {
    // Convert each special character to React expression
    return trimmedContent
      .split("")
      .map(char => `{'${char}'}`)
      .join("");
  }

  if (trimmedContent.includes("{{") && trimmedContent.includes("}}")) {
    return convertMustacheTextToJsx(textContent, isInsideTableColumn);
  }

  return textContent;
};
// node-html-parser ESM wrapper bug: when bundlers use default interop, named exports (parse, NodeType, HTMLElement) are undefined
export const parse =
  typeof NodeHTMLParser === "function"
    ? NodeHTMLParser
    : (NodeHTMLParser as { parse?: (html: string, options?: any) => any }).parse!;
// Use standard DOM node type constants (1, 3) - NodeType named export breaks under Turbopack/Next bundling
export const NodeType = {
  ELEMENT_NODE: 1,
  TEXT_NODE: 3,
} as const;
/** Prefer over `instanceof HTMLElement` when the constructor may not match (e.g. bundlers). */
export const isHTMLElement = (node: any): node is HTMLElement =>
  node != null && node.nodeType === NodeType.ELEMENT_NODE;
// HTMLElement constructor - fallback for when named export is undefined (Turbopack/Next bundling)
function getHTMLElementClass(): typeof HTMLElement {
  const fromModule =
    (NodeHTMLParser as { HTMLElement?: typeof HTMLElement }).HTMLElement ?? HTMLElement;
  if (fromModule) return fromModule;
  // Fallback: get from parsed node (parse creates HTMLElement instances)
  const parsed = parse("<div></div>");
  const firstEl = parsed.childNodes?.find((c: any) => c?.nodeType === 1);
  return (
    (firstEl?.constructor as typeof HTMLElement) ??
    (() => {
      throw new Error("node-html-parser HTMLElement not available");
    })()
  );
}
export const HTMLElementClass = getHTMLElementClass();

