import { HTMLElement } from "node-html-parser";

import { Import, transformAttrs, Transformer, TranspilationContext } from "../../transpile";
import { getParentNode } from "../utils";

export const imports: Import[] = [
  {
    name: "WmButton",
    from: "@wavemaker-ai/react-runtime/components/form/button",
  },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    let formNameProp = "";
    if (element?.getAttribute("type") === "reset") {
      const enclosingFormName = getParentNode(element, "wm-form");
      enclosingFormName && element.setAttribute("formName", enclosingFormName);
    }
    // Check if button is inside a table column
    const isInsideTableColumn =
      getParentNode(element, "wm-table-column") || context?.get("isInsideTableColumn");
    const stopPropagation =
      context?.get("isInsideList") || isInsideTableColumn ? " stopPropagation={true}" : "";

    return `<WmButton listener={fragment} ${stopPropagation} ${transformAttrs(element, context)} ${context.isPartOfPrefab ? " prefabName={fragment.prefabName}" : ""} >`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "</WmButton>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
