import { HTMLElement } from "node-html-parser";

import { Import, transformAttrs, Transformer, TranspilationContext } from "../../../transpile";
import { convertHyphenatedPropsToBracketNotation } from "../../../../utils.browser";

export const imports: Import[] = [
  {
    name: "WmFormAction",
    from: "@wavemaker-ai/react-runtime/components/data/form/form-action",
  },
];

const getFormActionExpr = (action: string, isAsync: boolean = false) => {
  const asyncKeyword = isAsync ? "async " : "";
  const awaitKeyword = isAsync ? "await " : "";

  // For async submit actions, add await before the submit call
  const processedAction =
    isAsync && action.includes("?.submit();")
      ? action.replace(/(\S+\?\.submit\(\);)/g, `${awaitKeyword}$1`)
      : action;

  const params = /\bwidget\b/.test(action) ? "($event, widget)" : "($event)";

  return `${asyncKeyword}${params} => {
        ${processedAction}
    }`;
};

/**
 * Generates widget accessor with proper syntax for dynamic (bound) vs static form names.
 * @param prefix - Base path like "fragment?.Widgets" or "list.itemWidgets[$index]"
 * @param formName - The form name (may contain $item for dynamic)
 * @param suffix - Method call like ".formreset()" or ".submit()"
 * @param isDynamic - Whether formName is a dynamic expression
 */
const getWidgetAccessor = (
  prefix: string,
  formName: string,
  suffix: string,
  isDynamic: boolean
): string => {
  if (isDynamic) {
    // Use bracket notation with optional chaining for dynamic access
    // Convert $item.taskId to $item?.taskId for safe access
    const safeFormName = formName.replace(/\./g, "?.");
    return `${prefix}?.[${safeFormName}]${suffix}`;
  }
  return `${prefix}.${formName}${suffix}`;
};

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const listName = context.data.listname;
    const key = element.getAttribute("key");
    element.setAttribute("displayName", element.attrs["display-name"]);
    element.removeAttribute("display-name");
    element.removeAttribute("key");
    const updateMode = element.attrs["update-mode"] ?? "true";
    element.setAttribute("updateMode", updateMode);
    element.removeAttribute("update-mode");
    const widgetType = element.getAttribute("widget-type") || "button";
    element.removeAttribute("widget-type");

    let formName = element.getAttribute("formKey") || element.attrs["key"] || element.attrs["name"];
    let isDynamicFormName = false;

    if (formName.startsWith("bind:")) {
      formName = formName.replace("bind:", "");
      isDynamicFormName = true;
    }

    const actionType = element.getAttribute("type") || "button";
    if (!element.getAttribute("type")) {
      element.setAttribute("type", "button");
    }
    const name = element.getAttribute("name");
    let action = element.getAttribute("action");

    // Define prefixes for list vs non-list context
    const listPrefix = "list.itemWidgets[$index]";
    const fragmentPrefix = "fragment?.Widgets";
    const widgetsPrefix = "Widgets";
    let btnClass = "btn-default";

    if (actionType === "submit" || action === "submit()") {
      btnClass = "btn-primary";
      action = listName
        ? getWidgetAccessor(listPrefix, formName, "?.submit();", isDynamicFormName) + (action || "")
        : getWidgetAccessor(widgetsPrefix, formName, "?.submit();", isDynamicFormName) +
          (action || "");
    }
    if (actionType === "reset" || action === "reset()") {
      action = listName
        ? getWidgetAccessor(listPrefix, formName, "?.formreset()", isDynamicFormName) +
          (action || "")
        : getWidgetAccessor(widgetsPrefix, formName, "?.formreset();", isDynamicFormName) +
          (action || "");
    }
    if (action) {
      let processedAction = convertHyphenatedPropsToBracketNotation(action);
      processedAction = processedAction.endsWith(";")
        ? processedAction.substring(0, processedAction.length - 1)
        : processedAction;
      action = processedAction
        .split(";")
        .map(s => {
          if (s === "reset()") {
            return listName
              ? getWidgetAccessor(listPrefix, formName, "?.formreset()", isDynamicFormName)
              : getWidgetAccessor(fragmentPrefix, formName, "?.formreset()", isDynamicFormName);
          } else if (s === "edit()" || s === "new()" || s === "cancel()" || s === "delete()") {
            return listName
              ? getWidgetAccessor(listPrefix, formName, "?." + s, isDynamicFormName)
              : getWidgetAccessor(fragmentPrefix, formName, "?." + s, isDynamicFormName);
          } else if (s === "filter()") {
            return listName
              ? getWidgetAccessor(listPrefix, formName, "?.filter()", isDynamicFormName)
              : getWidgetAccessor(fragmentPrefix, formName, "?.filter()", isDynamicFormName);
          } else if (s === "clearFilter()") {
            return listName
              ? getWidgetAccessor(listPrefix, formName, "?.clearFilter()", isDynamicFormName)
              : getWidgetAccessor(fragmentPrefix, formName, "?.clearFilter()", isDynamicFormName);
          } else if (s === "saveAndNew()") {
            return listName
              ? getWidgetAccessor(listPrefix, formName, "?.saveAndNew()", isDynamicFormName)
              : getWidgetAccessor(fragmentPrefix, formName, "?.saveAndNew()", isDynamicFormName);
          } else if (s === "saveAndView()") {
            return listName
              ? getWidgetAccessor(listPrefix, formName, "?.saveAndView()", isDynamicFormName)
              : getWidgetAccessor(fragmentPrefix, formName, "?.saveAndView()", isDynamicFormName);
          } else if (s === "highlightInvalidFields()") {
            return listName
              ? getWidgetAccessor(
                  listPrefix,
                  formName,
                  "?.highlightInvalidFields()",
                  isDynamicFormName
                )
              : getWidgetAccessor(
                  fragmentPrefix,
                  formName,
                  "?.highlightInvalidFields()",
                  isDynamicFormName
                );
          } else {
            return listName ? s : "fragment." + s;
          }
        })
        .join(";");
    }

    if (!element.hasAttribute("class")) {
      element.setAttribute("class", btnClass);
    }

    element.removeAttribute("formKey");
    element.removeAttribute("action");
    element.setAttribute("name", name || key || formName);

    // Generate formRef with proper accessor syntax
    const formRefExpr = isDynamicFormName
      ? `fragment?.Widgets?.[${formName.replace(/\./g, "?.")}]?.ref`
      : `fragment?.Widgets?.${formName}?.ref`;

    // Use async/await for submit actions
    const isAsyncAction = actionType === "submit";

    return `<WmFormAction formRef={${formRefExpr}}  ${transformAttrs(element, context)}
            ${action && actionType ? `onClick={${getFormActionExpr(action, isAsyncAction)}} widgettype="${widgetType}"` : ""} `;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "/>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
