import { modifyExpression } from "../utils.browser";
import { transformTableColumnClassExpression } from "./components/data/table/utils";

export type ClassMustacheTransformOptions = {
  isInsideTableColumn?: boolean;
};

/**
 *  class attributes may embed  `{{ expression }}` blocks.
 * Emit a JSX expression instead of a quoted string so inner single quotes do not break Sucrase.
 */
export function transformClassWithMustacheExpressions(
  classes: string,
  options: ClassMustacheTransformOptions = {}
): string | null {
  if (!classes || !classes.includes("{{") || !classes.includes("}}")) {
    return null;
  }

  const parts: string[] = [];
  const regex = /\{\{([\s\S]*?)\}\}/g;
  let lastIndex = 0;
  let match: RegExpExecArray | null;

  while ((match = regex.exec(classes)) !== null) {
    const staticBefore = classes.substring(lastIndex, match.index).trim();
    if (staticBefore) {
      parts.push(`'${staticBefore}'`);
    }

    let expr = match[1].trim();
    if (options.isInsideTableColumn) {
      expr = transformTableColumnClassExpression(expr);
    } else {
      expr = modifyExpression(expr);
    }
    if (expr) {
      parts.push(`(${expr})`);
    }

    lastIndex = match.index + match[0].length;
  }

  const staticAfter = classes.substring(lastIndex).trim();
  if (staticAfter) {
    parts.push(`'${staticAfter}'`);
  }

  if (parts.length === 0) {
    return null;
  }

  return `{${parts.join(" + ' ' + ")}}`;
}
