import { HTMLElement } from "node-html-parser";

import { Import, transformAttrs, Transformer, TranspilationContext } from "../../transpile";
import { getOnChangeExprforFormWidget } from "../utils";

export const imports: Import[] = [
  {
    name: "WmRichtexteditor",
    from: "@wavemaker-ai/react-runtime/components/basic/richtexteditor",
  },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const onChange = getOnChangeExprforFormWidget(element, "on-change", context);
    const isFormField = element.getAttribute("formfield") === "true";
    return `<WmRichtexteditor listener={fragment} ${isFormField ? " {...$formField}" : ""} ${transformAttrs(element, context)} ${onChange ? `onChange={${onChange}}` : ""}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "</WmRichtexteditor>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
