import { HTMLElement } from "node-html-parser";
import { Import, TranspilationContext, transformAttrs, Transformer } from "../../../transpile";
import { parseVariableDataSetBinding } from "./utils";

export const imports: Import[] = [
  { name: "WmTable", from: "@wavemaker-ai/react-runtime/components/data/table" },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const datasetAttr = element.getAttribute("dataset");
    const datasourceAttr = element.getAttribute("datasource");
    const binddatasetAttr = element.getAttribute("binddataset");
    if (datasetAttr && datasetAttr.includes(".dataSet")) {
      // A dataset binding that points at a variable's dataSet gets a matching
      // datasource/binddataset derived from it, so the table runs server-side pagination.
      // See parseVariableDataSetBinding for the shapes accepted (local / active-page / app
      // scope, static or computed variable key) and why this matters.
      const binding = parseVariableDataSetBinding(datasetAttr);
      if (binding) {
        const { scopePath, datasourceExpr, variableName } = binding;
        if (variableName) {
          context.set("tableDatasetVariableName", variableName);
        }
        if (!datasourceAttr) {
          element.setAttribute("datasource", `{${datasourceExpr}}`);
        }
        // binddataset is a static path string, so it can only be derived when the variable
        // name is known at build time. datasource alone drives server-side pagination.
        if (!binddatasetAttr && variableName) {
          element.setAttribute("binddataset", `${scopePath}.${variableName}.dataSet`);
        }
      }
    }

    const beforeRowDelete =
      element.getAttribute("on-beforerowdelete") || element.getAttribute("on-Beforerowdelete");
    let returnBeforeRowDelete = "";
    if (beforeRowDelete) {
      // Remove both possible variations of the attribute
      element.removeAttribute("on-beforerowdelete");
      element.removeAttribute("on-Beforerowdelete");

      // Split and trim each statement
      const fnCalls = beforeRowDelete
        .split(";")
        .map(fn => fn.trim())
        .filter(Boolean); // remove empty entries

      // Join using `||`
      returnBeforeRowDelete = `onBeforerowdelete={($event,widget,row,options) => {return (\n  ${fnCalls.join(" ||\n  ")}\n);}}`;
    }

    const beforeFilter =
      element.getAttribute("on-beforefilter") || element.getAttribute("on-Beforefilter");
    let returnBeforeFilter = "";
    if (beforeFilter) {
      // Remove both possible variations of the attribute
      element.removeAttribute("on-beforefilter");
      element.removeAttribute("on-Beforefilter");

      // Split and trim each statement
      const fnCalls = beforeFilter
        .split(";")
        .map(fn => fn.trim())
        .filter(Boolean); // remove empty entries

      // Join using `||`
      returnBeforeFilter = `onBeforefilter={(widget,columns) => {return (\n  ${fnCalls.join(" ||\n  ")}\n);}}`;
    }

    return `<WmTable listener={fragment} ${transformAttrs(element, context)} ${returnBeforeRowDelete} ${returnBeforeFilter}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => {
    context.set("tableDatasetVariableName", undefined);
    return "</WmTable>";
  },
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
