import { Parser } from "../property/base-parser";

class ShowInDeviceParser extends Parser {
  parse(value: string) {
    if (value) {
      const devices = value.split(",");
      if (devices.indexOf("all") < 0) {
        return `{[${devices.map(d => `'${d}'`).join(",")}]}`;
      }
    }
    return "";
  }
}

export const SHOW_IN_DEVICE_PARSER = new ShowInDeviceParser();
