import { HTMLElement } from "node-html-parser";

export enum FormWidgetType {
  AUTOCOMPLETE = "autocomplete",
  CHECKBOX = "checkbox",
  CHECKBOXSET = "checkboxset",
  CHIPS = "chips",
  COLORPICKER = "colorpicker",
  CURRENCY = "currency",
  CUSTOMWIDGET = "custom-widget",
  DATE = "date",
  DATETIME = "datetime",
  NUMBER = "number",
  PASSWORD = "password",
  RADIOSET = "radioset",
  RATING = "rating",
  RICHTEXT = "richtext",
  SELECT = "select",
  TOGGLE = "toggle",
  ICONBUTTONTOGGLE = "iconbutton-toggle",
  SLIDER = "slider",
  SWITCH = "switch",
  TEXT = "text",
  TEXTAREA = "textarea",
  TIME = "time",
  TIMESTAMP = "timestamp",
  TYPEAHEAD = "typeahead",
  UPLOAD = "upload",
}

const DEFAULT_PLACEHOLDERS: Map<FormWidgetType, string[]> = new Map([
  [FormWidgetType.SELECT, ["Select Min value", "Select Max value", "Select value"]],
  [FormWidgetType.DATETIME, ["Select Min date time", "Select Max date time", "Select date time"]],
  [FormWidgetType.TIME, ["Select Min time", "Select Max time", "Select time"]],
  [FormWidgetType.DATE, ["Select Min date", "Select Max date", "Select date"]],
  [FormWidgetType.TEXTAREA, ["", "", "Enter value"]],
  [FormWidgetType.RICHTEXT, ["", "", "Enter value"]],
  [FormWidgetType.COLORPICKER, ["Select Color", "Select Color", "Select Color"]],
  [FormWidgetType.CHIPS, ["", "", "Type here..."]],
  [FormWidgetType.PASSWORD, ["Enter Min value", "Enter Max value", "Enter value"]],
  [FormWidgetType.NUMBER, ["Enter Min value", "Enter Max value", "Enter value"]],
  [FormWidgetType.TEXT, ["Enter Min value", "Enter Max value", "Enter value"]],
  [FormWidgetType.CURRENCY, ["Enter Min value", "Enter Max value", "Enter value"]],
  [FormWidgetType.AUTOCOMPLETE, ["", "", "Search"]],
]);

export const setDefaultPlaceholder = (
  element: HTMLElement,
  widgetType: FormWidgetType,
  index: number
) => {
  const prop = index === 1 ? "maxplaceholder" : "placeholder";
  let placeholder = element.getAttribute(prop) ?? "";
  if (placeholder) {
    return;
  }
  placeholder =
    DEFAULT_PLACEHOLDERS.get(widgetType)?.[index] ??
    DEFAULT_PLACEHOLDERS.get(widgetType)?.[0] ??
    "";
  if (placeholder) {
    element.setAttribute(prop, placeholder);
  }
};

export const DATASET_WIDGETS = [
  FormWidgetType.AUTOCOMPLETE,
  FormWidgetType.CHIPS,
  FormWidgetType.SELECT,
  FormWidgetType.TYPEAHEAD,
  FormWidgetType.CHECKBOXSET,
  FormWidgetType.RADIOSET,
  FormWidgetType.SWITCH,
  FormWidgetType.RATING,
];
