export const imports: Import[] = [
  { name: "WmList", from: "@wavemaker-ai/react-runtime/components/data/list" },
];

const addTemplateClass = (element: HTMLElement) => {
  const classesToAdd: string[] = [];
  if (element.attrs["class"]?.indexOf("list-card") >= 0) {
    classesToAdd.push("list-card-template");
  }
  if (classesToAdd.length) {
    element.childNodes.forEach(n => {
      if (isHTMLElement(n) && n.tagName === "WM-LISTTEMPLATE") {
        n.setAttribute("class", classesToAdd.join(" ") + " " + (n.getAttribute("class") || ""));
      }
    });
  }
};

const stripBalancedParens = (expr: string): string => {
  // Recursively strip outer balanced parentheses from expression
  let result = expr.trim();
  while (result.startsWith("(") && result.endsWith(")")) {
    // Check if the outer parens are actually balanced (matching pair)
    let depth = 0;
    let isBalanced = true;
    for (let i = 0; i < result.length - 1; i++) {
      if (result[i] === "(") depth++;
      else if (result[i] === ")") depth--;
      // If depth goes to 0 before the last char, outer parens aren't a matching pair
      if (depth === 0) {
        isBalanced = false;
        break;
      }
    }
    if (isBalanced) {
      result = result.substring(1, result.length - 1);
    } else {
      break;
    }
  }
  return result;
};

const transformAttr = (name: string, value: string) => {
  if (name === "itemclass") {
    let v = value.replace(/fragment\??\.item/g, "item").replace(/fragment\??\.index/g, "index");

    const m = v.match(/^\{([\s\S]+)\}$/);
    if (m) {
      let inner = m[1];

      // Case 1: expression references Variables?.dataSet path
      const dataPathRegex =
        /(?:fragment\?.)?Variables\?.[^.]+\.dataSet(?:\?\.\[\s*0\s*\]\??|\[\s*0\s*\])/g;
      if (dataPathRegex.test(inner)) {
        let transformed = inner.replace(
          /(?:fragment\?.)?Variables\?.[^.]+\.dataSet(?:\?\.\[\s*0\s*\]\??|\[\s*0\s*\])/g,
          "item"
        );
        transformed = stripBalancedParens(transformed);
        if (transformed) {
          return `{(item:any)=>${transformed}}`;
        }
      }

      // Case 2: expression uses "item" directly → wrap as callback
      if (/\bitem\b/.test(inner)) {
        const stripped = stripBalancedParens(inner);
        return `{(item:any)=>${stripped}}`;
      }

      // Case 3: expression exists but no "item" → return as-is expression
      return v;
    }

    // No expression, plain string → return as plain string (no curly braces)
    return v;
  }
  return value;
};

/** Serialize a style object (from transformStyleAttrs) to object-literal parts; handles bind:, number, string. */
function serializeStyleObjectToParts(styleObj: Record<string, any>): string[] {
  const parts: string[] = [];
  for (const [key, value] of Object.entries(styleObj)) {
    if (value == null) continue;
    if (typeof value === "string" && value.startsWith("bind:")) {
      let exp = value.substring(5).trim();
      exp = modifyExpression(exp);
      parts.push(`${key}: (${exp})`);
    } else if (typeof value === "number") {
      parts.push(`${key}: ${value}`);
    } else {
      parts.push(`${key}: ${JSON.stringify(value)}`);
    }
  }
  return parts;
}
const buildItemAttrsFromListTemplate = (
  template: HTMLElement,
  context: TranspilationContext
): string => {
  if (!template || template.tagName?.toLowerCase() !== "wm-listtemplate") return "";
  if (template.getAttribute("class")) {
    template.setAttribute("className", template.getAttribute("class") as string);
    template.removeAttribute("class");
  }
  const autolayout = context.data?.autolayoutCodegen as AutolayoutCodegen | undefined;
  const autoLayoutResult = autolayout?.processListTemplate(template) ?? null;
  const styleObj =
    transformStyleAttrs(template, (styleProp: string) => {
      return !LAYOUT_ATTR_NAMES.has(styleProp);
    }) || {};
  const styleParts = serializeStyleObjectToParts(styleObj);
  const parts: string[] = [];
  if (styleParts.length > 0) {
    parts.push(`styles: { ${styleParts.join(", ")} }`);
  }
  if (autoLayoutResult && autolayout) {
    parts.push(`layoutClassName: ${autolayout.buildItemAttrsClassName(autoLayoutResult)}`);
  }
  const skipAttrs = new Set(["name", "item-id", "layout"]);
  if (autoLayoutResult) {
    for (const name of LAYOUT_ATTR_NAMES) skipAttrs.add(name);
  }
  const layoutAttrs = template.attributes || {};
  for (const name of Object.keys(layoutAttrs)) {
    if (skipAttrs.has(name)) continue;
    const value = layoutAttrs[name];
    if (typeof value !== "string") continue;
    if (value.startsWith("bind:")) {
      let exp = value.substring(5).trim();
      exp = modifyExpression(exp);
      parts.push(`${name}: (${exp})`);
    } else {
      value ? parts.push(`${name}: ${JSON.stringify(value)}`) : null;
    }
  }
  if (parts.length === 0) return "";
  return ` itemAttrs={($item: any, $index: number) => ({${parts.join(", ")}})}`;
};

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    context.set("isInsideList", true);
    const widgetName = element.attrs["name"];
    const listContent = parse(`<wm-list-content name="${widgetName + "Item"}"></wm-list-content>`)
      .firstChild as HTMLElement;
    let dataSet = element.getAttribute("dataset");
    let onEndReached = "";
    let disableitem = "";
    let itemKey = "";
    let currentNode = element.parentNode;
    while (currentNode) {
      if (currentNode.rawTagName === "wm-form" || currentNode.rawTagName === "wm-liveform") {
        break;
      }
      currentNode = currentNode.parentNode;
    }
    const formName = currentNode && currentNode.getAttribute("name");
    if (formName) {
      // @ts-ignore
      element.setAttribute("formRef", formName);
    }
    const template = element.childNodes.find(c => isHTMLElement(c)) as HTMLElement;
    transformRepeatChildAttr(
      template,
      `fragment.Widgets.${widgetName}.currentItemWidgets`,
      "currentItemWidgets"
    );
    transformRepeatChildAttr(template, `fragment.Widgets.${widgetName}.currentItem`, "$item");
    if (formName) {
      transformRepeatChildAttr(
        template,
        `fragment.Widgets.${formName}.formWidgets.${widgetName}.currentItem`,
        "$item"
      );
    }
    transformRepeatChildAttr(template, "fragment.item", "$item");
    transformRepeatChildAttr(template, "fragment.index", "$index");
    transformRepeatChildAttr(template, "fragment.$index", "$index");
    transformRepeatChildAttr(template, "fragment.itemRef.$index", "$index");
    transformRepeatChildAttr(template, "fragment.itemRef.$first", "$first");
    transformRepeatChildAttr(template, "fragment.itemRef.$last", "$last");

    if (template && dataSet && dataSet.startsWith("bind:")) {
      transformRepeatChildData(
        template,
        dataSet.substring(5) + "[0]",
        "list_item",
        true,
        widgetName
      );
      transformRepeatChildData(
        template,
        dataSet.substring(5) + "[$i]",
        "list_item",
        true,
        widgetName
      );
      transformRepeatChildData(
        template,
        dataSet.substring(5) + "[fragment.$i]",
        "list_item",
        true,
        widgetName
      );
      transformRepeatChildData(
        template,
        dataSet.substring(5) + "[fragment.$i]",
        "list_item",
        true,
        widgetName
      );
      transformRepeatChildData(
        template,
        dataSet.substring(5) + ".data[0]",
        "list_item",
        true,
        widgetName
      );
      transformRepeatChildData(
        template,
        dataSet.substring(5) + ".data[$i]",
        "list_item",
        true,
        widgetName
      );
      transformRepeatChildData(
        template,
        dataSet.substring(5) + ".data[fragment.$i]",
        "list_item",
        true,
        widgetName
      );
      // Skip `dataset`/`datasource`: a descendant widget with its own independent dataset
      // (e.g. a wm-menu bound to an unrelated dropdown source) must not have that collapsed
      // to "$item" just because its expression text matches the list's own dataset path.
      transformRepeatChildAttr(template, dataSet.substring(5), "$item", ["dataset", "datasource"]);
      if (element.getAttribute("disableitem")?.startsWith("bind:")) {
        const disabelItemExp = replaceAll(
          element.getAttribute("disableitem")?.substring(5) || "",
          dataSet.substring(5) + "[fragment.$i]",
          "$item"
        );
        disableitem = `disableitem={($item, $index) => fragment.eval(() => ${disabelItemExp})}`;
        element.removeAttribute("disableitem");
      }
      if (element.getAttribute("itemkey")?.startsWith("bind:")) {
        let itemKeyExp = element.getAttribute("itemkey")?.substring(5) || "";
        itemKeyExp = replaceAll(itemKeyExp, dataSet.substring(5) + "[fragment.$i]", "$item");
        itemKeyExp = replaceAll(itemKeyExp, dataSet.substring(5) + "[0]", "$item");
        itemKey = `itemkey={($item, $index) => fragment.eval(() => ${itemKeyExp})}`;
        element.removeAttribute("itemkey");
      }
      const datasetAttr = element.getAttribute("dataset");
      const datasourceAttr = element.getAttribute("datasource");
      if (
        datasetAttr &&
        datasetAttr.startsWith("bind:fragment.Variables.") &&
        datasetAttr.includes(".dataSet")
      ) {
        // Match base pattern: bind:fragment.Variables.<varName>.dataSet
        // Allow any suffix after ".dataSet" (e.g., ?.results, .results, [0], .data, etc.)
        // but keep datasource pointing to the variable object.
        const match = datasetAttr.match(
          /^bind:fragment\.Variables\.([^.]+)\.dataSet(?=[^A-Za-z0-9_]|$)/
        );
        if (match) {
          const variableName = match[1];
          if (!datasourceAttr) {
            element.setAttribute("datasource", `{fragment?.Variables?.${variableName}}`);
          }
          // Transform both data structure patterns to $item
          const dataPatterns = [
            `fragment.Variables.${variableName}.dataSet.data[0]`,
            `fragment.Variables.${variableName}.dataSet[0]`,
            `fragment.Variables.${variableName}.dataSet`,
            `Variables.${variableName}.dataSet`,
          ];

          dataPatterns.forEach(pattern => {
            // See the skip-list note above: don't stomp a descendant's own independent dataset.
            transformRepeatChildAttr(template, pattern, "$item", ["dataset", "datasource"]);
          });
        }
      }
      const variableArr = (dataSet as string).match(/(fragment)+\.Variables\.[^\.]+/g);
      if (variableArr && variableArr.length === 1) {
        const variable = variableArr[0];
      }
    }
    const templateNode = element.childNodes.find(c => c instanceof HTMLElement) as HTMLElement;
    const itemAttrsStr =
      templateNode?.tagName?.toLowerCase() === "wm-listtemplate"
        ? buildItemAttrsFromListTemplate(templateNode, context)
        : "";
    addTemplateClass(element);
    listContent.childNodes = element.childNodes;
    element.childNodes = [listContent];
    const markup = `<WmList listener={fragment} ${transformAttrs(element, context, transformAttr)}${itemAttrsStr}
    ${disableitem || ""}
    ${itemKey || ""}
    ${onEndReached}
     renderItem={($item:Record<string, any>, $index:number, list:Record<string, any>[] ,getCurrentItemWidgets :any) => {
     const currentItemWidgetsRef = React.useRef({})   
     const currentItemWidgets = getCurrentItemWidgets($index);
     const item = $item;
     currentItemWidgetsRef.current = currentItemWidgets;
       const $first = $index === 0;
       const $last = list && $index === list.length - 1;
       return (<>`;

    context.listener = "listener";
    context.set("old_props", context.props);
    context.data.listname = widgetName;
    context.props = [
      "listener",
      "item",
      "index",
      "currentItemWidgets",
      "currentItemWidgetsRef",
      "list",
    ];
    context.data.listCount = (context.data.listCount || 0) + 1;
    return markup;
  },
  post: (element: HTMLElement, context: TranspilationContext) => {
    delete context.data.listname;
    context.data.listCount--;
    return "</>)}}></WmList>";
  },
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
  createComponent: (element: HTMLElement, context: TranspilationContext) => {
    if (!context.data.listCount) {
      context.props = context.get("old_props") || [];
    }
    const componentMarkup = createComponent(element, context);
    context.props = [];
    return componentMarkup;
  },
} as Transformer;
