import { MultiDimensionStyleParser } from "./multi-dimension-style.parser";

export class BorderWidthParser extends MultiDimensionStyleParser {
  constructor(styleName: string) {
    super(styleName);
  }

  parse(value: string) {
    const values = super.parseDimensions(value);
    return {
      borderTopWidth: values[0],
      borderRightWidth: values[1],
      borderBottomWidth: values[2],
      borderLeftWidth: values[3],
    };
  }
}
