import { HTMLElement } from "node-html-parser";

import { Import, transformAttrs, Transformer, TranspilationContext } from "../../transpile";
import { getOnChangeExprforFormWidget } from "../utils";

export const imports: Import[] = [
  {
    name: "WmCheckbox",
    from: "@wavemaker-ai/react-runtime/components/input/default/checkbox",
  },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const isFormField = element.getAttribute("formfield") === "true";
    // Angular's checkbox host fills its cell (checkbox.build.ts), except the icon button type.
    if (
      element.getAttribute("type") !== "button" &&
      !element.getAttribute("styles") &&
      !element.getAttribute("style")
    ) {
      element.setAttribute("style", "height:100%");
    }
    // Writes the new value back to a two-way bound variable (read before transformAttrs, which
    // would otherwise emit the same on-change a second time).
    const onChange = getOnChangeExprforFormWidget(element, "on-change", context);

    // Custom transform function to handle name attribute in list context
    // This is a closure that captures both context and element
    const transformNameInList = (name: string, value: string) => {
      // Check if we're inside a list context and this is the name attribute
      // An item-id already keeps each row's checkbox apart; the name stays as authored (Angular parity).
      if (name === "name" && context.data.listname && !element.getAttribute("item-id")) {
        // Get the original attribute value before any processing
        const originalName = element.getAttribute("name");
        if (originalName) {
          const nameValue = originalName.trim();
          // Check if name already contains $index concatenation
          const hasIndexConcatenation =
            nameValue.includes("$index") ||
            nameValue.includes("`") ||
            nameValue.includes("+$index");

          if (!hasIndexConcatenation) {
            // Remove bind: prefix if present
            let cleanName = originalName;
            if (cleanName.startsWith("bind:")) {
              cleanName = cleanName.substring(5);
            }
            // Remove quotes if present
            cleanName = cleanName.replace(/^["']|["']$/g, "");
            // Return JSX expression format - this will be used directly without quoting
            return `{\`${cleanName}\`+$index}`;
          }
        }
      }
      return undefined; // Let default transformation handle it
    };

    return `<WmCheckbox ${isFormField ? " {...$formField}" : ""} listener={fragment} ${transformAttrs(element, context, transformNameInList)}${onChange ? ` onChange={${onChange}}` : ""}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "</WmCheckbox>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
