import { HTMLElement } from "node-html-parser";
import {
  Import,
  isHTMLElement,
  transformAttrs,
  Transformer,
  TranspilationContext,
} from "../../transpile";

export const imports: Import[] = [
  {
    name: "WmLoginDialog",
    from: "@wavemaker-ai/react-runtime/components/dialogs/login-dialog",
  },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const widgetName = element.getAttribute("name");

    // Find and process wm-dialog-actions element
    const actionsIndex = element.childNodes.findIndex(
      e => isHTMLElement(e) && e.tagName.toLowerCase() === "wm-dialogactions"
    );

    if (actionsIndex >= 0) {
      const actionsElement = element.childNodes[actionsIndex] as HTMLElement;
      // Remove only fragment?.doLogin() from on-click attribute while preserving other methods
      actionsElement.childNodes.forEach(child => {
        if (isHTMLElement(child)) {
          const onClickValue = child.getAttribute("on-click");
          if (onClickValue) {
            // Remove fragment?.doLogin() and clean up semicolons
            let updatedValue = onClickValue
              .replace(/fragment\?\.doLogin\(\)/g, "") // Remove fragment?.doLogin()
              .replace(/;+/g, ";") // Replace multiple semicolons with single semicolon
              .replace(/^;|;$/g, "") // Remove leading/trailing semicolons
              .trim();

            if (updatedValue) {
              child.setAttribute("on-click", updatedValue);
            } else {
              child.removeAttribute("on-click");
            }
          }
        }
      });
    }

    return `<WmLoginDialog eventsource={fragment?.Actions?.loginAction} listener={fragment} ${transformAttrs(element, context)} >`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "</WmLoginDialog>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
