import { HTMLElement } from "node-html-parser";

import {
  createExpression,
  Import,
  transformAttrs,
  Transformer,
  TranspilationContext,
} from "../../transpile";
import { getOnChangeExprforFormWidget } from "../utils";

export const imports: Import[] = [
  { name: "WmSelect", from: "@wavemaker-ai/react-runtime/components/input/select" },
];

const getOnChangeExpr = (element: HTMLElement) => {
  const onChange = element.getAttribute("on-change");
  return onChange
    ? `
    ($event, widget, newVal, oldVal) => {
      ${onChange}
    }
  `
    : "";
};

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    let getDisplayExpression;
    //supportedLocale select widget handling
    const dataSet = element.getAttribute("dataset") || "";
    let onChange;
    if (dataSet.indexOf("supportedLocale") > -1) {
      onChange = getOnChangeExpr(element);
      element.removeAttribute("on-change");
      element.setAttribute("datavalue", "bind:fragment.App.selectedLocale");
    } else {
      getDisplayExpression = createExpression(element, "displayexpression");
      if (getDisplayExpression) {
        element.removeAttribute("displayexpression");
      }
      onChange = getOnChangeExprforFormWidget(element, "on-change", context);
    }

    // Extract dataPath by getting everything after first [0] and removing all array indices
    let dataPath = "";
    const match = dataSet.match(/dataSet\[0\](.*)/);
    if (dataSet.includes("[0]") && match && match[1]) {
      dataPath = match[1].replace(/\[\d+\]/g, "");
    }

    // If dataPath exists, modify the dataset to only include the base part before [0]
    if (dataPath) {
      const baseDataset = dataSet.split("[0]")[0];
      element.setAttribute("dataset", baseDataset);
    }

    const isFormField = element.getAttribute("formfield") === "true";
    return `<WmSelect ${isFormField ? " {...$formField}" : ""} ${transformAttrs(element, context)} listener={fragment}
      ${onChange ? `onChange={${onChange}}` : ""}
      ${getDisplayExpression ? `displayExpression=${getDisplayExpression}` : ""}
      ${dataPath ? `dataPath="${dataPath}"` : ""}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "</WmSelect>",
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
