import { HTMLElement } from "node-html-parser";

import { Import, transformAttrs, Transformer, TranspilationContext } from "../../transpile";
import { setFormActions } from "./live-form-shared";

export const imports: Import[] = [
  { name: "WmLiveFilter", from: "@wavemaker-ai/react-runtime/components/data/live-filter" },
];

const FILTER_ACTION_TAGS = ["wm-form-action", "wm-filter-action"];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    setFormActions(element, context, FILTER_ACTION_TAGS);
    const dataSource = element.getAttribute("dataset")?.split(".")[2];

    return `<WmLiveFilter  listener={fragment}  dataSource="${dataSource}" ${transformAttrs(element, context)} >`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => `</WmLiveFilter>`,
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
