import { HTMLElement } from "node-html-parser";
import {
  createComponent,
  Import,
  isHTMLElement,
  transformAttrs,
  Transformer,
  TranspilationContext,
} from "../../transpile";
import { transformRepeatChildAttr, transformRepeatChildData } from "../utils";

export const imports: Import[] = [
  {
    name: "WmCarousel",
    from: "@wavemaker-ai/react-runtime/components/advanced/carousel",
  },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    let dataSet = element.getAttribute("dataset");
    let widgetName = element.getAttribute("name") || "carousel";

    if (dataSet && dataSet.startsWith("bind:") && element.getAttribute("type") === "dynamic") {
      dataSet = dataSet.substring(5);
      const template = element.childNodes.find(c => isHTMLElement(c));

      transformRepeatChildAttr(template as HTMLElement, "name", "bind:$index");
      transformRepeatChildAttr(template as HTMLElement, "name", "bind:$index");
      transformRepeatChildData(template as HTMLElement, dataSet + "[0]", "carousel_item");
      transformRepeatChildData(template as HTMLElement, dataSet + "[$i]", "carousel_item");
      transformRepeatChildData(template as HTMLElement, dataSet + "[fragment.$i]", "carousel_item");
      transformRepeatChildData(template as HTMLElement, dataSet + "[fragment.$i]", "carousel_item");

      // Add key attribute to the first child element
      if (template) {
        (template as HTMLElement).setAttribute(
          "key",
          `bind:"${widgetName}_template" + '_' + $index`
        );
        (template as HTMLElement).removeAttribute("name");
      }

      context.set("old_props", context.props);
      context.props = ["$item", "$index"];

      return `<WmCarousel listener={fragment} ${transformAttrs(element, context)} render={(($item:Record<string,any>,$index:number,data:Record<string,any>[])=>(`;
    }

    return `<WmCarousel ${transformAttrs(element, context)}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => {
    let dataSet = element.getAttribute("dataset");
    if (dataSet && dataSet.startsWith("bind:") && element.getAttribute("type") === "dynamic") {
      context.props = context.get("old_props");
      return "))}/>";
    }
    return "</WmCarousel>";
  },
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
  createComponent: (element: HTMLElement, context: TranspilationContext) => {
    if (!context.data.listCount) {
      context.props = context.get("old_props") || [];
    }
    const componentMarkup = createComponent(element, context);
    context.props = [];
    return componentMarkup;
  },
} as Transformer;
