import { useMemo } from "react";
import { shouldShowPanelHeading, shouldShowPagination } from "../utils";
const usePanelStructure = ({
  title,
  subheading,
  iconclass,
  exportformat = [],
  headerActions,
  footerActions,
  shownavigation,
  onDemandLoad,
  internalDataset,
  pagesize,
  allowpagesizechange,
  datasource,
  showrecordcount = false
}) => {
  const showPanelHeading = useMemo(
    () => shouldShowPanelHeading(title, subheading, iconclass, exportformat, headerActions),
    [title, subheading, iconclass, exportformat, headerActions]
  );
  const showPagination = useMemo(
    () => shouldShowPagination({
      shownavigation,
      onDemandLoad,
      internalDataset,
      pagesize,
      allowpagesizechange,
      datasource,
      showrecordcount
    }),
    [
      shownavigation,
      onDemandLoad,
      internalDataset,
      pagesize,
      allowpagesizechange,
      datasource,
      showrecordcount
    ]
  );
  const showFooter = useMemo(
    () => shownavigation || footerActions.length > 0,
    [shownavigation, footerActions]
  );
  return {
    showPanelHeading,
    showPagination,
    showFooter
  };
};
export {
  usePanelStructure
};
