import { HTMLElement } from "node-html-parser";
import { FORMAT_CONTEXT } from "../bind.ex.transformer";
import { isHTMLElement, TranspilationContext } from "../transpile";

export const fromUnicode = (str: String) => JSON.parse('"' + str.replace(/\"/g, '\\"') + '"');

/**
 * Strips all optional chaining (`?.`) from an expression, converting it to regular access.
 *
 * Handles two forms:
 *  1. Property access:  `?.identifier` → `.identifier`
 *     e.g. `fragment?.Variables?.dataSet` → `fragment.Variables.dataSet`
 *
 *  2. Bracket access:   `?.[` → `[`
 *     e.g. `dataSet?.[0]?.name` → `dataSet[0].name`
 */
export const removeOptionChaining = (str: string): string => {
  return str.replace(/\?\.([a-zA-Z_$][a-zA-Z0-9_$]*)/g, ".$1").replace(/\?\.\[/g, "[");
};

function isListAndField(element: HTMLElement) {
  const isList = element.getAttribute("type") === "list";
  const isFormField = element.tagName.toLowerCase() === "wm-form-field";
  return isList && isFormField;
}

export const replaceAll = (str: string, find: string, replaceWith: string): string => {
  const splits = str.split(find);
  if (splits.length > 1) {
    return splits.join(replaceWith);
  }
  return str;
};

export const findElement = (
  e: HTMLElement,
  tagName: string,
  callback: (e: HTMLElement, index: number) => void,
  options: { recursive: boolean } = { recursive: true }
) => {
  let index = 0;
  e.childNodes.forEach(n => {
    if (n && isHTMLElement(n)) {
      if (n.tagName === tagName) {
        callback && callback(n, index++);
      }
      if (options.recursive) {
        findElement(n, tagName, callback, options);
      }
    }
  });
};

export const transformRepeatChildData = (
  element: HTMLElement,
  dataSetEx: string,
  prefix = "repeat_item",
  list = false,
  widgetName = ""
) => {
  Object.keys(element.attributes).forEach(name => {
    const isList = isListAndField(element);
    if (isList) {
      return;
    }
    const value: string = element.attributes[name];
    const stripped = removeOptionChaining(value);
    const replaced = replaceAll(stripped, dataSetEx, "$item");
    if (replaced !== stripped) {
      element.setAttribute(name, replaced);
    }
    if (list) {
      function genrateRandomString() {
        return Math.random().toString(36).substring(2, 5);
      }

      element.setAttribute(
        "item-id",
        `bind:'${widgetName}_' + $index + '_${element.getAttribute("name")}_${genrateRandomString()}'`
      );
    }
  });
  element.childNodes.forEach(c => {
    if (isHTMLElement(c)) {
      transformRepeatChildData(c, dataSetEx, prefix, list, widgetName);
    }
  });
};

export const transformRepeatChildAttr = (
  element: HTMLElement,
  replace: string,
  replaceWith: string,
  skipAttrNames?: string[]
) => {
  Object.keys(element.attributes).forEach(name => {
    const isList = isListAndField(element);
    if (isList) {
      return;
    }
    if (skipAttrNames?.includes(name)) {
      return;
    }
    const value: string = element.attributes[name];
    // Use regex with word boundaries to ensure we only replace complete matches
    const regex = new RegExp(
      replace.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "(?![a-zA-Z_$0-9])",
      "g"
    );
    const stripped = removeOptionChaining(value);
    const replaced = stripped.replace(regex, replaceWith);
    // Only commit if the regex actually matched — avoids stripping optional chaining
    // from already-processed event handlers (e.g. fragment?.Widgets?.x?.open) that
    // don't contain the target pattern.
    if (replaced !== stripped) {
      element.setAttribute(name, replaced);
    }
  });
  element.childNodes.forEach(c => {
    if (isHTMLElement(c)) {
      transformRepeatChildAttr(c, replace, replaceWith, skipAttrNames);
    }
  });
};

const processWidgetNode = (element: HTMLElement) => {
  // Add data-internal-widget="true" to the widget
  element.setAttribute("data-internal-widget", "true");

  // Transform the name attribute to append $index
  const name = element.getAttribute("name");
  if (name) {
    // Check if name already has $index pattern or is already a bind expression with $index
    if (!name.includes("$index")) {
      // If it's already a bind expression, extract the value
      if (name.startsWith("bind:")) {
        const bindValue = name.substring(5);
        element.setAttribute("name", `bind:${bindValue} + "_" + $index`);
      } else {
        element.setAttribute("name", `bind:${JSON.stringify(name)} + "_" + $index`);
      }
    }
  }
};

export const transformListChildWidgets = (element: HTMLElement) => {
  // Process all child nodes
  element.childNodes.forEach(c => {
    if (isHTMLElement(c)) {
      // Check if this is the listtemplate element
      const isListTemplate = c.tagName === "WM-LISTTEMPLATE";

      if (isListTemplate) {
        // For listtemplate, skip it but process all its children
        transformListChildWidgets(c);
      } else {
        // For all other widgets, process them and their children
        processWidgetNode(c);
        transformListChildWidgets(c);
      }
    }
  });
};

export const transformFormat = (
  element: HTMLElement,
  attrName: string,
  replaceFnName: string,
  addDefault = true
) => {
  let attrValue = element.getAttribute(attrName);
  if (!attrValue) {
    if (addDefault) {
      attrValue = `bind:fragment.${replaceFnName}()`;
    }
  } else if (attrValue.startsWith("bind:")) {
    attrValue = `bind:fragment.${replaceFnName}(${attrValue.substring(5)})`;
  } else {
    attrValue = `bind:fragment.${replaceFnName}("${attrValue}")`;
  }
  if (attrValue) {
    element.setAttribute(attrName, attrValue);
  }
};

export const transformItemsPerRow = (element: HTMLElement) => {
  let itemsPerRow = {} as any;
  let itemsPerRowStr = element.getAttribute("itemsperrow");
  if (itemsPerRowStr) {
    itemsPerRowStr?.split(" ").forEach(s => {
      const [k, v] = s.split("-");
      itemsPerRow[k] = parseInt(v);
    });
    element.setAttribute("itemsperrow", "bind:" + JSON.stringify(itemsPerRow));
  }
};

export const getRenderItemPartial = (context?: any) => {
  let paramStr: string = "";
  if (context?.isPartOfPrefab) {
    paramStr = paramStr + " prefab={fragment.prefab || fragment}";
  }
  return `
    renderitempartial={ (item, index, partialName)=>{
      return (<WmPartialContainer parentWatcher={fragment.watcher} 
       ${paramStr} themeToUse={fragment.theme} content={partialName} item={item} listener={fragment} />)
    }}
    `;
};

const resolveBindExpression = (element: HTMLElement): string | null => {
  const datavalue = element.getAttribute("datavalue") || "";
  const parts = datavalue.endsWith(")")
    ? element.getAttribute("dataset")?.split(":") || []
    : element.getAttribute("datavalue")?.split(":") || [];

  const bindExpr = parts.length > 1 ? parts[1] : null;
  if (
    !bindExpr ||
    bindExpr.includes("?") ||
    bindExpr.includes("Widgets") ||
    bindExpr.includes("$formField")
  ) {
    return null;
  }
  return bindExpr;
};

const REPEATING_COMPONENT_TAGS = ["wm-list", "wm-carousel", "wm-tabs", "wm-wizard", "wm-accordion"];

const findRepeatingParentContext = (element: HTMLElement): string | null => {
  let currentNode: HTMLElement | null = element.parentNode;
  while (currentNode) {
    const tagName = currentNode.tagName?.toLowerCase();
    if (tagName && REPEATING_COMPONENT_TAGS.includes(tagName)) {
      return currentNode.getAttribute("dataset") || null;
    }
    currentNode = currentNode.parentNode;
  }
  return null;
};

interface OnChangeHandlerConfig {
  variableName: string;
  updateExpr: string;
  value: string;
  oldValue: string;
  callbackEvent: string | null;
}

const buildOnChangeHandler = (config: OnChangeHandlerConfig): string => {
  const { variableName, updateExpr, value, oldValue, callbackEvent } = config;
  return `
      ($event, widget, ${value}, ${oldValue}) => {
        if(fragment?.Variables?.${variableName}?.twoWayBinding) {
          ${updateExpr}
        }
        ${callbackEvent ? `${callbackEvent}` : ""};
      }
    `;
};

/**
 * Resolves twoWayBinding update expressions for form widgets.
 * Handles both repeating contexts ($item bindings inside lists/carousels/etc.)
 * and direct variable bindings.
 */
export const getOnChangeExprforFormWidget = (
  element: HTMLElement,
  eventName: any,
  context?: TranspilationContext
) => {
  const bindExpr = resolveBindExpression(element);
  if (!bindExpr) {
    return "";
  }

  const value = eventName === "on-change" ? "newVal" : "selectedValue";
  const oldValue = eventName === "on-change" ? "oldVal" : "";

  let variableName: string | null = null;
  let updateExpr = "";

  if (bindExpr.includes("$item")) {
    const parentDataset = findRepeatingParentContext(element);

    if (parentDataset && parentDataset.startsWith("bind:")) {
      const parentDatasetExpr = parentDataset.substring(5);

      let variableMatch = parentDatasetExpr.match(/fragment\.Variables\.([^.]+)\.dataSet/);
      if (!variableMatch) {
        variableMatch = parentDatasetExpr.match(/Variables\.([^.]+)\.dataSet/);
      }

      if (variableMatch && variableMatch.length > 0) {
        variableName = variableMatch[1];

        const propertyMatch = bindExpr.match(/\$item\??\.([a-zA-Z_$][a-zA-Z0-9_$]*)/);
        const propertyName = propertyMatch ? propertyMatch[1] : null;

        if (propertyName) {
          const twoWayBindingVariables = context?.get("twoWayBindingVariables") as
            | Set<string>
            | undefined;
          const hasTwoWayBinding = twoWayBindingVariables?.has(variableName) === true;

          if (hasTwoWayBinding) {
            updateExpr = `fragment.Variables.${variableName}.dataSet[$index].${propertyName} = ${value};`;
          }
        }
      }
    }

    if (!updateExpr) {
      return "";
    }
  } else {
    const isVariable = bindExpr.includes("Variables");
    const variableExpr = bindExpr.split(".");
    variableName =
      isVariable && variableExpr ? variableExpr[2] : variableExpr ? variableExpr[1] : null;

    if (variableName) {
      const twoWayBindingVariables = context?.get("twoWayBindingVariables") as
        | Set<string>
        | undefined;
      const hasTwoWayBinding = twoWayBindingVariables?.has(variableName) === true;

      if (hasTwoWayBinding) {
        updateExpr = `${bindExpr} = ${value};`;
      }
    }
  }

  if (!variableName || !updateExpr) {
    return "";
  }

  const callbackEvent = element.getAttribute(eventName);
  if (callbackEvent) {
    element.removeAttribute(eventName);
  }

  return buildOnChangeHandler({
    variableName,
    updateExpr,
    value,
    oldValue,
    callbackEvent: callbackEvent || null,
  });
};

export const inferTypeAndParseProperty = (name: string, valWithQuotes: string) => {
  let val = valWithQuotes.startsWith('"') ? valWithQuotes.substring(1) : valWithQuotes;
  val = val.endsWith('"') ? val.substring(0, val.length - 1) : val;
  try {
    if (val === "true") {
      return "{true}";
    } else if (val === "false") {
      return "{false}";
    }
    return /^-?[0-9]*(.[0-9]*)$/.test(val) ? `{${parseFloat(val)}}` : valWithQuotes;
  } catch (e) {
    return valWithQuotes;
  }
};

export const extractDatasetInfo = (element: HTMLElement) => {
  let dataPath = "";
  const dataSet = element.getAttribute("dataset") || "";
  if (dataSet) {
    const match = dataSet.match(/dataSet\[0\](.*)/);
    if (!dataSet.includes("[0]") || !match || !match[1]) return "";
    dataPath = match[1].replace(/\[\d+\]/g, "");
    if (!dataPath) return "";
    const baseDataset = dataSet.split("[0]")[0];
    if (!baseDataset || baseDataset === dataSet) return "";
    element.setAttribute("dataset", baseDataset);
    element.setAttribute("dataPath", dataPath);
    return "";
  }
  return "";
};

export const getParentNode = (element: HTMLElement, tagName: string | string[]) => {
  const tagNames = (Array.isArray(tagName) ? tagName : [tagName]).map(t => t.toLowerCase());
  let current: HTMLElement | null = element;
  while (current) {
    if (current.tagName && tagNames.includes(current.tagName.toLowerCase())) {
      const name = current.getAttribute("name");
      return name || undefined;
    }
    current = current.parentNode;
  }
  return undefined;
};

export const getDirectParentList = (element: HTMLElement): string | undefined => {
  let current: HTMLElement | null = element.parentNode;
  while (current) {
    // If we hit another form first, this form is NOT a direct list child
    if (current.rawTagName === "wm-form") {
      return undefined;
    }
    // If we hit a list without hitting a form, this IS a direct list child
    if (current.rawTagName === "wm-list") {
      return current.getAttribute("name") || undefined;
    }
    current = current.parentNode;
  }
  return undefined;
};

export const getDatasourceExpr = (element: HTMLElement) => {
  const datasetAttr = element.getAttribute("dataset");
  const datasourceAttr = element.getAttribute("datasource");
  if (
    !datasourceAttr &&
    datasetAttr &&
    datasetAttr.startsWith("bind:fragment.Variables.") &&
    datasetAttr.endsWith(".dataSet")
  ) {
    const match = datasetAttr.match(/^bind:fragment\.Variables\.([^.]+)\.dataSet$/);
    if (match) {
      const variableName = match[1];
      const datasourceValue = `{fragment?.Variables?.${variableName}}`;
      element.setAttribute("datasource", datasourceValue);
      return datasourceValue;
    }
  }
};
