import { HTMLElement } from "node-html-parser";
import { Import, TranspilationContext, transformAttrs, Transformer } from "../../../transpile";
import { withPartialContainer, getPartialImports } from "../../page/with-partial-container";
import { buildTableRowProps } from "./utils";

export const imports: Import[] = [
  { name: "WmTableRow", from: "@wavemaker-ai/react-runtime/components/data/table/table-row" },
];

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const content = element.getAttribute("content");
    const widgetType = element.getAttribute("widget-type") || "button";
    const displayName = element.getAttribute("display-name");

    element.removeAttribute("display-name");
    if (displayName) {
      element.setAttribute("displayName", displayName);
    }
    element.removeAttribute("widget-type");
    let partial = "";
    if (content) {
      element.setAttribute("is-table-row", "true");
      element.setAttribute("rowType", "expansion");
      const { partialAttr } = withPartialContainer(element, context, {
        prop: "renderPartial",
        extraParams: "currentItem:any",
      });
      partial = partialAttr;
      element.removeAttribute("is-table-row");
    }

    const tableRowProps = buildTableRowProps(element);
    return `<WmTableRow listener={fragment} widgetType="${widgetType}" ${transformAttrs(element, context)} ${tableRowProps} ${partial}`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => "/>",
  imports: (element: HTMLElement, context: TranspilationContext) =>
    imports.concat(getPartialImports(element, context)),
} as Transformer;
