import { HTMLElement } from "node-html-parser";

import {
  createComponent,
  Transformer,
  transformAttrs,
  TranspilationContext,
  Import,
} from "../../transpile";
import { inferTypeAndParseProperty } from "../utils";

export const imports: Import[] = [
  {
    name: "WmPrefabContainer",
    from: "@wavemaker-ai/react-runtime/components/prefab/container",
  },
];
export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    return `<WmPrefabContainer 
    ${transformAttrs(element, context, inferTypeAndParseProperty)}>`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => {
    return `</WmPrefabContainer >`;
  },
  imports: (element: HTMLElement, context: TranspilationContext) => {
    return imports;
  },
  createComponent: (element: HTMLElement, context: TranspilationContext) =>
    createComponent(element, context),
  prefabs: (element: HTMLElement, context: TranspilationContext) => {
    const prefabname = element.getAttribute("prefabname");
    if (prefabname) {
      return [prefabname];
    }
    return [];
  },
} as Transformer;
