import { HTMLElement } from "node-html-parser";

import { Import, transformAttrs, Transformer, TranspilationContext } from "../../transpile";
import { withPartialContainer } from "../page/with-partial-container";

export const imports: Import[] = [
  {
    name: "WmWizardstep",
    from: "@wavemaker-ai/react-runtime/components/container/wizard/wizard-step",
  },
  {
    name: "WmPartialContainer",
    from: "@wavemaker-ai/react-runtime/components/page/partial-container",
  },
];

const getOnNext = (element: HTMLElement) => {
  const onNext = element.getAttribute("on-next");
  return onNext ? `(widget, currentStep, stepIndex) =>{return ${onNext}}` : "";
};

const getOnPrev = (element: HTMLElement) => {
  const onPrev = element.getAttribute("on-prev");
  return onPrev ? `(widget, currentStep, stepIndex) =>{return ${onPrev}}` : "";
};

function getNearestWizardType(element: HTMLElement): string | undefined {
  let current: HTMLElement | null = element;
  while (current) {
    current = current.parentNode;
    if (!current) break;
    if (current?.tagName?.toLowerCase() === "wm-wizard") {
      const type = current.getAttribute("type");
      if (type) {
        return type;
      }
    }
  }
  return undefined;
}

export default {
  pre: (element: HTMLElement, context: TranspilationContext) => {
    const { partialAttr } = withPartialContainer(element, context, { prop: "render" });

    const onNext = getOnNext(element);
    const onPrev = getOnPrev(element);
    element.removeAttribute("on-next");
    element.removeAttribute("on-prev");
    const type = getNearestWizardType(element);
    if (
      ((type && type == "dynamic") || (element.childNodes && element.childNodes.length > 0)) &&
      !partialAttr
    ) {
      return `<WmWizardstep ${transformAttrs(element, context)}
    ${onNext ? `onNext={${onNext}}` : ""} ${onPrev ? `onPrev={${onPrev}}` : ""} render={(props:Record<string, any>, onLoad:()=>void) => (<>`;
    }
    return `<WmWizardstep ${transformAttrs(element, context)}
    ${onNext ? `onNext={${onNext}}` : ""} ${onPrev ? `onPrev={${onPrev}}` : ""} ${partialAttr} >`;
  },
  post: (element: HTMLElement, context: TranspilationContext) => {
    const type = getNearestWizardType(element);
    const hasPartial = !!element.getAttribute("content");
    if (
      ((type && type == "dynamic") || (element.childNodes && element.childNodes.length > 0)) &&
      !hasPartial
    ) {
      return " </>)}/>";
    }
    return "</WmWizardstep>";
  },
  imports: (element: HTMLElement, context: TranspilationContext) => imports,
} as Transformer;
